import React from 'react';
import { useTranslation } from 'react-i18next';
import { Building2, Boxes, PackageCheck, Truck } from 'lucide-react';
import { cn } from '@shared/lib';

export interface PackingListSummaryData {
  projectCode?: string;
  projectName?: string;
  totalGroups: number;
  totalTagNos: number;
  totalDesignQuantity: number;
  totalPackedQuantity: number;
  packingProgressPercentage: number;
  totalDesignWeight: number;
  totalPackedWeight: number;
  weightProgressPercentage: number;
  totalReceiptQuantity: number;
  totalSiteDeliveryQuantity: number;
}

interface PackingListSummaryBarProps {
  summary: PackingListSummaryData;
  className?: string;
}

const formatNumber = (val?: number | null) =>
  val != null ? new Intl.NumberFormat('vi-VN').format(val) : '0';

export const PackingListSummaryBar: React.FC<PackingListSummaryBarProps> = ({
  summary,
  className,
}) => {
  const { t } = useTranslation(['mechanicalPackingList', 'common']);

  return (
    <div
      className={cn(
        'grid grid-cols-1 gap-3 sm:grid-cols-2 xl:grid-cols-4 rounded-xl border bg-card/90 px-4 py-3.5 shadow-xs backdrop-blur-sm',
        className,
      )}
    >
      {/* 1. Dự án */}
      <div className="flex items-start gap-3 min-w-0">
        <div className="flex h-9 w-9 shrink-0 items-center justify-center rounded-lg bg-primary/10 text-primary ring-1 ring-primary/20">
          <Building2 className="h-4.5 w-4.5" />
        </div>
        <div className="min-w-0 flex-1 space-y-0.5">
          <div className="text-[11px] font-semibold uppercase tracking-wider text-muted-foreground">
            {t('mechanicalPackingList:report.filter.project', { defaultValue: 'DỰ ÁN' })}
          </div>
          <div
            className="font-semibold text-foreground truncate text-sm"
            title={summary.projectName || summary.projectCode || '—'}
          >
            {summary.projectName || summary.projectCode || '—'}
          </div>
          {summary.projectCode && summary.projectName && (
            <div className="font-mono text-xs text-muted-foreground truncate">
              {summary.projectCode}
            </div>
          )}
        </div>
      </div>

      {/* 2. Quy mô hàng hóa */}
      <div className="flex items-start gap-3 min-w-0 border-t pt-2 sm:border-t-0 sm:pt-0 sm:border-l sm:pl-3 xl:pl-4">
        <div className="flex h-9 w-9 shrink-0 items-center justify-center rounded-lg bg-indigo-500/10 text-indigo-600 dark:text-indigo-400 ring-1 ring-indigo-500/20">
          <Boxes className="h-4.5 w-4.5" />
        </div>
        <div className="min-w-0 flex-1 space-y-0.5">
          <div className="text-[11px] font-semibold uppercase tracking-wider text-muted-foreground">
            {t('mechanicalPackingList:report.summary.goodsScale', {
              defaultValue: 'QUY MÔ HÀNG HÓA',
            })}
          </div>
          <div className="flex items-baseline gap-1.5">
            <span className="font-mono text-base font-bold text-foreground">
              {formatNumber(summary.totalGroups)}
            </span>
            <span className="text-xs text-muted-foreground">
              {t('mechanicalPackingList:report.summary.groupsUnit', { defaultValue: 'nhóm TP' })}
            </span>
          </div>
          <div className="font-mono text-xs text-muted-foreground">
            <span>{t('mechanicalPackingList:report.summary.totalTagNos', { defaultValue: 'Tổng kiện' })}: </span>
            <span className="font-semibold text-foreground">{formatNumber(summary.totalTagNos)}</span>
            <span> TagNo</span>
          </div>
        </div>
      </div>

      {/* 3. Tiến độ đóng kiện */}
      <div className="flex items-start gap-3 min-w-0 border-t pt-2 xl:border-t-0 xl:pt-0 xl:border-l xl:pl-4">
        <div className="flex h-9 w-9 shrink-0 items-center justify-center rounded-lg bg-emerald-500/10 text-emerald-600 dark:text-emerald-400 ring-1 ring-emerald-500/20">
          <PackageCheck className="h-4.5 w-4.5" />
        </div>
        <div className="min-w-0 flex-1 space-y-1">
          <div className="flex items-center justify-between">
            <span className="text-[11px] font-semibold uppercase tracking-wider text-muted-foreground">
              {t('mechanicalPackingList:report.summary.packingProgress', {
                defaultValue: 'TIẾN ĐỘ ĐÓNG KIỆN',
              })}
            </span>
            <span className="font-mono text-xs font-bold text-emerald-600 dark:text-emerald-400">
              {summary.packingProgressPercentage}%
            </span>
          </div>
          <div className="w-full bg-muted rounded-full h-1.5 overflow-hidden border border-border/50">
            <div
              className="bg-emerald-500 h-full rounded-full transition-all duration-300"
              style={{
                width: `${Math.min(100, Math.max(0, summary.packingProgressPercentage))}%`,
              }}
            />
          </div>
          <div className="flex items-center justify-between text-[11px] text-muted-foreground font-mono">
            <span>
              SL: <strong className="text-foreground">{formatNumber(summary.totalPackedQuantity)}</strong>/{formatNumber(summary.totalDesignQuantity)}
            </span>
            <span>
              KL: <strong className="text-foreground">{formatNumber(summary.totalPackedWeight)}</strong>/{formatNumber(summary.totalDesignWeight)} kg
            </span>
          </div>
        </div>
      </div>

      {/* 4. Tiến độ Nhập kho & Giao hàng */}
      <div className="flex items-start gap-3 min-w-0 border-t pt-2 xl:border-t-0 xl:pt-0 xl:border-l xl:pl-4">
        <div className="flex h-9 w-9 shrink-0 items-center justify-center rounded-lg bg-amber-500/10 text-amber-600 dark:text-amber-400 ring-1 ring-amber-500/20">
          <Truck className="h-4.5 w-4.5" />
        </div>
        <div className="min-w-0 flex-1 space-y-0.5">
          <div className="text-[11px] font-semibold uppercase tracking-wider text-muted-foreground">
            {t('mechanicalPackingList:report.summary.receiptAndDelivery', {
              defaultValue: 'NHẬP KHO & GIAO CÔNG TRÌNH',
            })}
          </div>
          <div className="flex items-center justify-between text-xs pt-0.5">
            <span className="text-muted-foreground">
              {t('mechanicalPackingList:report.summary.receiptShort', { defaultValue: 'Nhập kho TP' })}:
            </span>
            <span className="font-mono font-bold text-emerald-600 dark:text-emerald-400">
              {formatNumber(summary.totalReceiptQuantity)}
            </span>
          </div>
          <div className="flex items-center justify-between text-xs">
            <span className="text-muted-foreground">
              {t('mechanicalPackingList:report.summary.deliveryShort', { defaultValue: 'Giao công trình' })}:
            </span>
            <span className="font-mono font-bold text-amber-600 dark:text-amber-400">
              {formatNumber(summary.totalSiteDeliveryQuantity)}
            </span>
          </div>
        </div>
      </div>
    </div>
  );
};

