const totalGroupCount = useMemo(() => {
  const s = new Set<string>();
  for (const r of optionSource) s.add(getGroupKey(r));
  return s.size;
}, [optionSource]);

const selectedProject = useMemo(
  () => projectOptions.find((p) => p.value === appliedFilters.projectId),
  [projectOptions, appliedFilters.projectId],
);

// Thống kê KPI tổng thể cho toàn bộ báo cáo
const summary = useMemo<PackingListSummaryData>(() => {
  let totalDesignQuantity = 0;
  let totalPackedQuantity = 0;
  let totalDesignWeight = 0;
  let totalPackedWeight = 0;
  let totalReceiptQuantity = 0;
  let totalSiteDeliveryQuantity = 0;
  let totalTagNos = 0;

  for (const group of groupedRows) {
    totalDesignQuantity += group.totalDesignQuantity;
    totalPackedQuantity += group.totalPackedQuantity;
    totalDesignWeight += group.totalDesignWeight;
    totalPackedWeight += group.totalPackedWeight;
    totalReceiptQuantity += group.totalReceiptQuantity;
    totalSiteDeliveryQuantity += group.totalSiteDeliveryQuantity;
    totalTagNos += group.details.length;
  }

  const packingProgressPercentage =
    totalDesignQuantity > 0
      ? Math.min(100, Math.round((totalPackedQuantity / totalDesignQuantity) * 100))
      : 0;

  const weightProgressPercentage =
    totalDesignWeight > 0
      ? Math.min(100, Math.round((totalPackedWeight / totalDesignWeight) * 100))
      : 0;

  return {
    projectCode: selectedProject?.code,
    projectName: selectedProject?.label,
    totalGroups: groupedRows.length,
    totalTagNos,
    totalDesignQuantity,
    totalPackedQuantity,
    packingProgressPercentage,
    totalDesignWeight,
    totalPackedWeight,
    weightProgressPercentage,
    totalReceiptQuantity,
    totalSiteDeliveryQuantity,
  };
}, [groupedRows, selectedProject]);

// Quản lý trạng thái mở rộng/thu gọn (Accordion)
const allGroupKeys = useMemo(() => groupedRows.map((g) => g.key), [groupedRows]);
const [openKeys, setOpenKeys] = useState<Set<string>>(new Set());

// Tự động mở khi chỉ có 1 nhóm hoặc reset trạng thái khi danh sách nhóm thay đổi
const prevKeysSig = useRef('');
const keysSig = allGroupKeys.join('|');
if (prevKeysSig.current !== keysSig) {
  prevKeysSig.current = keysSig;
  if (allGroupKeys.length === 1) {
    setOpenKeys(new Set(allGroupKeys));
  }
}

const toggleOpen = useCallback((key: string) => {
  setOpenKeys((prev) => {
    const next = new Set(prev);
    if (next.has(key)) next.delete(key);
    else next.add(key);
    return next;
  });
}, []);

const isAllExpanded = groupedRows.length > 0 && openKeys.size === groupedRows.length;

const toggleExpandAll = useCallback(() => {
  setOpenKeys((prev) => {
    if (prev.size === allGroupKeys.length) {
      return new Set();
    }
    return new Set(allGroupKeys);
  });
}, [allGroupKeys]);

// Cấu hình ẩn/hiện cột
const toggleColumnGroup = useCallback((id: ColGroupId) => {
  setHiddenGroups((prev) => {
    const next = new Set(prev);
    if (next.has(id)) next.delete(id);
    else next.add(id);
    return next;
  });
}, []);

const hiddenColIds = useMemo(() => {
  const s = new Set<string>();
  for (const g of COLUMN_GROUP_DEFS) {
    if (hiddenGroups.has(g.id)) g.columnIds.forEach((colId) => s.add(colId));
  }
  return s;
}, [hiddenGroups]);

const visibleColumns = useMemo(
  () => columns.filter((c) => !hiddenColIds.has(c.id)),
  [columns, hiddenColIds],
);

const visibleColumnGroups = useMemo(
  () =>
    COLUMN_GROUP_DEFS.filter((g) => g.inTableGroup && !hiddenGroups.has(g.id)).map((g) => ({
      label: t(g.labelKey),
      columnIds: g.columnIds,
    })),
  [hiddenGroups, t],
);

const tableMinWidth = useMemo(
  () => visibleColumns.reduce((sum, c) => sum + (c.defaultWidth ?? 120), 0),
  [visibleColumns],
);

// Handlers
const handleApplyFilters = useCallback(() => {
  if (!draftFilters.projectId) return;
  setAppliedFilters({ ...draftFilters });
  setHasApplied(true);
  setClientFilters(EMPTY_CLIENT_FILTERS);
}, [draftFilters]);

const handleExportReport = useCallback(async () => {
  if (!appliedFilters.projectId) return;
  try {
    const filePath = await mechanicalPackingListService.reportExport({
      projectId: appliedFilters.projectId,
      finishedGoodId: clientFilters.finishedGoodId || undefined,
      modelId: clientFilters.modelId || undefined,
      designModelId: clientFilters.designModelId || undefined,
      receiptStatus:
        clientFilters.receiptStatus === 'ALL' ? undefined : clientFilters.receiptStatus,
      siteDeliveryStatus:
        clientFilters.siteDeliveryStatus === 'ALL' ? undefined : clientFilters.siteDeliveryStatus,
    });
    if (filePath) {
      await downloadFile({
        filePath,
        uploadType: EUploadType.Sftp,
        downloadFileName: t('report.exportFilename', { date: format(new Date(), 'yyyyMMdd') }),
      });
    }
  } catch (error) {
    console.error('Export error:', error);
  }
}, [appliedFilters.projectId, clientFilters, downloadFile, t]);

const handleProjectSearch = useCallback((query: string) => {
  setProjectSearchText(query);
}, []);

const handleProjectChange = useCallback((value: string = '') => {
  setDraftFilters((prev) => ({
    ...prev,
    projectId: value,
  }));
}, []);

const setStatusFilter = useCallback(
  (key: 'receiptStatus' | 'siteDeliveryStatus', val: string) => {
    setClientFilters((prev) => ({
      ...prev,
      [key]: !val || val === 'ALL' ? 'ALL' : (Number(val) as EPackingReportStatus),
    }));
  },
  [],
);

const clearClientFilters = useCallback(() => {
  setClientFilters(EMPTY_CLIENT_FILTERS);
}, []);

return {
  t,
  draftFilters,
  appliedFilters,
  hasApplied,
  clientFilters,
  projectQuery,
  projectOptions,
  selectedProject,
  reportQuery,
  groupedRows,
  totalGroupCount,
  summary,
  openKeys,
  toggleOpen,
  isAllExpanded,
  toggleExpandAll,
  optionSource,
  finishedGoodOptions,
  modelOptions,
  designModelOptions,
  hasModelData,
  hasDesignModelData,
  hasActiveClientFilter,
  hiddenGroups,
  toggleColumnGroup,
  visibleColumns,
  visibleColumnGroups,
  tableMinWidth,
  handleApplyFilters,
  handleExportReport,
  handleProjectSearch,
  handleProjectChange,
  setClientFilters,
  setStatusFilter,
  clearClientFilters,
};

