import { useMemo, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { ChevronDown, RotateCcw } from 'lucide-react';
import { Button, Card, Combobox } from '@shared/ui';
import {
  ResizableWrapTable,
  type ResizableWrapTableColumn,
  type ResizableWrapTableColumnGroup,
} from '@shared/components';
import { cn } from '@shared/lib';
import { EPackingReportStatus } from '@/enums/packing-report-status.enum';
import type { GroupedFGRow, ReportRow } from './packing-list-report.types';

interface FinishedGoodExpandItemProps {
  item: GroupedFGRow;
  columns: ResizableWrapTableColumn<ReportRow>[];
  columnGroups: ResizableWrapTableColumnGroup[];
  tableMinWidth: number;
  isOpen?: boolean;
  onToggle?: () => void;
}

const formatNumber = (val?: number | null) =>
  val != null ? new Intl.NumberFormat('vi-VN').format(val) : '0';

export function FinishedGoodExpandItem({
  item,
  columns,
  columnGroups,
  tableMinWidth,
  isOpen: controlledIsOpen,
  onToggle: controlledOnToggle,
}: Readonly<FinishedGoodExpandItemProps>) {
  const { t } = useTranslation(['mechanicalPackingList', 'common']);
  const [internalIsOpen, setInternalIsOpen] = useState(false);

  const isExpanded = controlledIsOpen !== undefined ? controlledIsOpen : internalIsOpen;
  const toggle = controlledOnToggle ?? (() => setInternalIsOpen((prev) => !prev));

  // State cho search & filter của bảng con
  const [searchText, setSearchText] = useState('');
  const [filterPackingStatus, setFilterPackingStatus] = useState<string>('ALL');
  const [filterReceiptStatus, setFilterReceiptStatus] = useState<string>('ALL');
  const [filterSiteDeliveryStatus, setFilterSiteDeliveryStatus] = useState<string>('ALL');

  const packingStatusOptions = useMemo(
    () => [
      { value: 'ALL', label: t('report.filter.statusAll', { defaultValue: 'Tất cả trạng thái' }) },
      {
        value: String(EPackingReportStatus.Empty),
        label: t('report.status.PACKING_STATUS_EMPTY', { defaultValue: 'Chưa đóng kiện' }),
      },
      {
        value: String(EPackingReportStatus.Partial),
        label: t('report.status.PACKING_STATUS_PARTIAL', { defaultValue: 'Đóng kiện chưa đủ' }),
      },
      {
        value: String(EPackingReportStatus.Full),
        label: t('report.status.PACKING_STATUS_FULL', { defaultValue: 'Đã đóng kiện đủ' }),
      },
    ],
    [t],
  );

  const receiptStatusOptions = useMemo(
    () => [
      { value: 'ALL', label: t('report.filter.statusAll', { defaultValue: 'Tất cả trạng thái' }) },
      {
        value: String(EPackingReportStatus.Empty),
        label: t('report.status.RECEIPT_STATUS_EMPTY', { defaultValue: 'Chưa nhập kho' }),
      },
      {
        value: String(EPackingReportStatus.Partial),
        label: t('report.status.RECEIPT_STATUS_PARTIAL', { defaultValue: 'Đã nhập chưa đủ' }),
      },
      {
        value: String(EPackingReportStatus.Full),
        label: t('report.status.RECEIPT_STATUS_FULL', { defaultValue: 'Đã nhập đủ' }),
      },
    ],
    [t],
  );

  const deliveryStatusOptions = useMemo(
    () => [
      { value: 'ALL', label: t('report.filter.statusAll', { defaultValue: 'Tất cả trạng thái' }) },
      {
        value: String(EPackingReportStatus.Empty),
        label: t('report.status.DELIVERY_STATUS_EMPTY', { defaultValue: 'Chưa giao' }),
      },
      {
        value: String(EPackingReportStatus.Partial),
        label: t('report.status.DELIVERY_STATUS_PARTIAL', { defaultValue: 'Đã giao chưa đủ' }),
      },
      {
        value: String(EPackingReportStatus.Full),
        label: t('report.status.DELIVERY_STATUS_FULL', { defaultValue: 'Đã giao đủ' }),
      },
    ],
    [t],
  );

  const filteredDetails = useMemo(() => {
    let list = item.details;
    const term = searchText.trim().toLowerCase();
    if (term) {
      list = list.filter((d) =>
        [d.tagNo, d.productPartName, d.productDescription, d.uomName, d.remark]
          .filter(Boolean)
          .some((s) => String(s).toLowerCase().includes(term)),
      );
    }
    if (filterPackingStatus && filterPackingStatus !== 'ALL') {
      list = list.filter((d) => String(d.packingCodeCheck) === filterPackingStatus);
    }
    if (filterReceiptStatus && filterReceiptStatus !== 'ALL') {
      list = list.filter((d) => String(d.receiptStatus) === filterReceiptStatus);
    }
    if (filterSiteDeliveryStatus && filterSiteDeliveryStatus !== 'ALL') {
      list = list.filter((d) => String(d.siteDeliveryStatus) === filterSiteDeliveryStatus);
    }
    return list;
  }, [
    item.details,
    searchText,
    filterPackingStatus,
    filterReceiptStatus,
    filterSiteDeliveryStatus,
  ]);

  const hasActiveDetailFilters =
    Boolean(searchText.trim()) ||
    filterPackingStatus !== 'ALL' ||
    filterReceiptStatus !== 'ALL' ||
    filterSiteDeliveryStatus !== 'ALL';

  const resetDetailFilters = () => {
    setSearchText('');
    setFilterPackingStatus('ALL');
    setFilterReceiptStatus('ALL');
    setFilterSiteDeliveryStatus('ALL');
  };

  const packingPct =
    item.totalDesignQuantity > 0
      ? Math.min(100, Math.round((item.totalPackedQuantity / item.totalDesignQuantity) * 100))
      : 0;

  return (
    <Card className="overflow-hidden rounded-xl border bg-card shadow-xs transition-all duration-200 py-0 gap-0">
      {/* Accordion Header */}
      <button
        type="button"
        onClick={toggle}
        className={cn(
          'flex w-full flex-col gap-3 px-4 py-3 text-left transition-colors hover:bg-muted/40 lg:flex-row lg:items-center lg:justify-between',
          isExpanded && 'bg-muted/30 border-b',
        )}
      >
        {/* Khối bên trái: STT + Mã/Tên Thành phẩm + Models */}
        <div className="flex min-w-0 items-start gap-2.5 sm:items-center">
          <span className="mt-1 h-5 w-1.5 shrink-0 rounded-full bg-primary sm:mt-0" />
          <div className="flex h-7 w-7 shrink-0 items-center justify-center rounded-md bg-primary/10 font-mono text-xs font-bold text-primary ring-1 ring-primary/20">
            #{item.stt}
          </div>

          <div className="min-w-0 flex-1 space-y-1">
            <div className="flex flex-wrap items-center gap-2">
              <span className="inline-flex shrink-0 items-center rounded-md bg-primary/10 px-2 py-0.5 font-mono text-xs font-bold text-primary ring-1 ring-inset ring-primary/20">
                {item.finishedGoodCode}
              </span>
              <span className="truncate text-sm font-bold text-foreground">
                {item.finishedGoodName}
              </span>
              {item.mechanicalPackingListCodes.length > 0 && (
                <div className="flex flex-wrap gap-1">
                  {item.mechanicalPackingListCodes.map((code) => (
                    <span
                      key={code}
                      className="rounded border border-border bg-muted/60 px-1.5 py-0.2 font-mono text-[10px] font-medium text-foreground/80"
                    >
                      {code}
                    </span>
                  ))}
                </div>
              )}
            </div>

            <div className="flex flex-wrap items-center gap-1.5 text-xs">
              {item.modelCode ? (
                <span className="inline-flex items-center gap-1 rounded bg-muted/80 px-1.5 py-0.5 text-[11px] font-medium text-muted-foreground ring-1 ring-inset ring-border/60">
                  <span className="text-[10px] text-muted-foreground/80">
                    {t('report.columns.performanceModel', { defaultValue: 'Model' })}:
                  </span>
                  <span className="font-mono font-semibold text-foreground/90">{item.modelCode}</span>
                  {item.modelName ? <span className="truncate max-w-[120px]">· {item.modelName}</span> : null}
                </span>
              ) : null}

              {item.designModelCode ? (
                <span className="inline-flex items-center gap-1 rounded bg-indigo-50/80 px-1.5 py-0.5 text-[11px] font-medium text-indigo-700 ring-1 ring-inset ring-indigo-200 dark:bg-indigo-950/40 dark:text-indigo-300 dark:ring-indigo-800">
                  <span className="text-[10px] text-indigo-500/90">
                    {t('report.columns.designModel', { defaultValue: 'Model TK' })}:
                  </span>
                  <span className="font-mono font-semibold">{item.designModelCode}</span>
                  {item.designModelName ? (
                    <span className="truncate max-w-[120px]">· {item.designModelName}</span>
                  ) : null}
                </span>
              ) : null}
            </div>
          </div>
        </div>

        {/* Khối bên phải: Các chỉ số thống kê + Đếm TagNo + Chevron */}
        <div className="flex flex-wrap items-center gap-4 lg:gap-6 border-t pt-2 lg:border-t-0 lg:pt-0">
          {/* Tiến độ đóng kiện */}
          <div className="flex flex-col gap-1 min-w-[140px]">
            <div className="flex items-center justify-between text-[11px] text-muted-foreground font-medium">
              <span>{t('report.summary.packedQuantityShort', { defaultValue: 'Đóng kiện' })}:</span>
              <span className="font-mono font-bold text-emerald-600 dark:text-emerald-400">
                {packingPct}%
              </span>
            </div>
            <div className="w-full bg-muted rounded-full h-1.5 overflow-hidden border border-border/50">
              <div
                className="bg-emerald-500 h-full rounded-full transition-all duration-300"
                style={{ width: `${packingPct}%` }}
              />
            </div>
            <div className="flex items-center justify-between font-mono text-[10px] text-muted-foreground tabular-nums">
              <span>
                SL: {formatNumber(item.totalPackedQuantity)}/{formatNumber(item.totalDesignQuantity)}
              </span>
              <span>
                {formatNumber(item.totalPackedWeight)}/{formatNumber(item.totalDesignWeight)} kg
              </span>
            </div>
          </div>

          {/* Nhập kho & Giao hàng */}
          <div className="hidden sm:flex flex-col text-[11px] font-mono leading-tight gap-0.5 min-w-[110px]">
            <div className="flex justify-between gap-2">
              <span className="text-muted-foreground">
                {t('report.summary.receiptShort', { defaultValue: 'Nhập kho' })}:
              </span>
              <span className="font-semibold text-emerald-600 dark:text-emerald-400">
                {formatNumber(item.totalReceiptQuantity)}
              </span>
            </div>
            <div className="flex justify-between gap-2">
              <span className="text-muted-foreground">
                {t('report.summary.deliveryShort', { defaultValue: 'Giao CT' })}:
              </span>
              <span className="font-semibold text-amber-600 dark:text-amber-400">
                {formatNumber(item.totalSiteDeliveryQuantity)}
              </span>
            </div>
          </div>

          {/* TagNo Count Badge & Chevron */}
          <div className="flex items-center gap-2 text-muted-foreground ml-auto lg:ml-0">
            <span className="inline-flex items-center rounded-full bg-muted px-2.5 py-0.5 text-xs font-semibold text-foreground/80 tabular-nums">
              {t('report.summary.packageCount', { count: item.details.length })}
            </span>
            <div
              className={cn(
                'flex h-7 w-7 items-center justify-center rounded-full transition-transform duration-200',
                isExpanded
                  ? 'rotate-180 bg-primary/10 text-primary'
                  : 'bg-muted/70 text-muted-foreground',
              )}
            >
              <ChevronDown className="h-4 w-4" />
            </div>
          </div>
        </div>
      </button>

      {/* Accordion Body: Bảng Chi Tiết có Search & Filter Popover */}
      {isExpanded && (
        <div className="animate-in slide-in-from-top-1 duration-150 p-3 bg-muted/20">
          <ResizableWrapTable
            columns={columns}
            data={filteredDetails}
            getRowId={(r) => r.key}
            columnGroups={columnGroups}
            tableMinWidth={tableMinWidth}
            maxBodyHeight={550}
            className="rounded-lg border bg-card shadow-2xs [&_thead_th]:!bg-[var(--figma-background-selected-primary)] [&_thead_th]:!text-foreground [&_thead_th:first-child]:!rounded-tl-none"
            showPagination={filteredDetails.length > 50}
            emptyMessage={t('common:noData', { defaultValue: 'Không có dữ liệu' })}
            toolbarProps={{
              searchValue: searchText,
              onSearchChange: setSearchText,
              searchDebounce: 300,
              searchPlaceholder: t('report.filter.searchDetailPlaceholder', {
                defaultValue: 'Tìm theo TagNo, cụm sản phẩm, mô tả...',
              }),
              filterLabel: t('report.filter.label', { defaultValue: 'Bộ lọc' }),
              filterPopoverTitle: t('report.filter.detailFilterTitle', {
                defaultValue: 'Lọc chi tiết kiện hàng',
              }),
              totalCount: item.details.length,
              filteredCount: filteredDetails.length,
              renderFilterContent: (close: () => void) => (
                <form
                  className="space-y-4 w-120 sm:w-160 max-w-[90vw]"
                  onSubmit={(e) => {
                    e.preventDefault();
                    close();
                  }}
                >
                  <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
                    <div className="space-y-1.5">
                      <span className="text-xs font-semibold text-muted-foreground uppercase tracking-wide">
                        {t('report.columns.packingCodeCheck', {
                          defaultValue: 'Tình trạng đóng kiện',
                        })}
                      </span>
                      <Combobox
                        options={packingStatusOptions}
                        value={filterPackingStatus}
                        onValueChange={(val) => setFilterPackingStatus(val || 'ALL')}
                        placeholder={t('report.filter.statusAll', {
                          defaultValue: 'Tất cả trạng thái',
                        })}
                        buttonProps={{ className: 'w-full text-xs h-9' }}
                      />
                    </div>

                    <div className="space-y-1.5">
                      <span className="text-xs font-semibold text-muted-foreground uppercase tracking-wide">
                        {t('report.status.receiptStatus', {
                          defaultValue: 'Tình trạng nhập kho',
                        })}
                      </span>
                      <Combobox
                        options={receiptStatusOptions}
                        value={filterReceiptStatus}
                        onValueChange={(val) => setFilterReceiptStatus(val || 'ALL')}
                        placeholder={t('report.filter.statusAll', {
                          defaultValue: 'Tất cả trạng thái',
                        })}
                        buttonProps={{ className: 'w-full text-xs h-9' }}
                      />
                    </div>

                    <div className="space-y-1.5">
                      <span className="text-xs font-semibold text-muted-foreground uppercase tracking-wide">
                        {t('report.status.deliveryStatus', {
                          defaultValue: 'Tình trạng giao',
                        })}
                      </span>
                      <Combobox
                        options={deliveryStatusOptions}
                        value={filterSiteDeliveryStatus}
                        onValueChange={(val) => setFilterSiteDeliveryStatus(val || 'ALL')}
                        placeholder={t('report.filter.statusAll', {
                          defaultValue: 'Tất cả trạng thái',
                        })}
                        buttonProps={{ className: 'w-full text-xs h-9' }}
                      />
                    </div>
                  </div>

                  <div className="flex justify-end gap-2 pt-1 border-t">
                    <Button
                      type="button"
                      variant="ghost"
                      size="sm"
                      onClick={() => {
                        setFilterPackingStatus('ALL');
                        setFilterReceiptStatus('ALL');
                        setFilterSiteDeliveryStatus('ALL');
                      }}
                    >
                      {t('report.filter.clear', { defaultValue: 'Đặt lại' })}
                    </Button>
                    <Button type="submit" size="sm">
                      {t('common:apply', { defaultValue: 'Áp dụng' })}
                    </Button>
                  </div>
                </form>
              ),
              actions: hasActiveDetailFilters && (
                <Button
                  type="button"
                  variant="ghost"
                  size="sm"
                  className="h-8 gap-1 text-xs text-muted-foreground hover:text-foreground"
                  onClick={resetDetailFilters}
                >
                  <RotateCcw className="h-3 w-3" />
                  <span>{t('report.filter.clear', { defaultValue: 'Xóa lọc' })}</span>
                </Button>
              ),
            }}
          />
        </div>
      )}
    </Card>
  );
}

