import { useMemo } from 'react';
import { createFileRoute } from '@tanstack/react-router';
import {
  Boxes,
  ChevronsDownUp,
  ChevronsUpDown,
  Columns3,
  Download,
  Loader2,
  PackageCheck,
  RotateCcw,
  Search,
  SlidersHorizontal,
} from 'lucide-react';
import { useTranslation } from 'react-i18next';

import { EPackingReportStatus } from '@/enums/packing-report-status.enum';
import {
  AutocompleteCombobox,
  Button,
  Card,
  CardContent,
  Checkbox,
  Combobox,
  Popover,
  PopoverContent,
  PopoverTrigger,
} from '@shared/ui';
import { cn } from '@shared/lib';

import type { GroupedFGRow } from './_components/packing-list-report.types';
import { COLUMN_GROUP_DEFS } from './_components/packing-list-report-columns';
import { FinishedGoodExpandItem } from './_components/packing-list-report-expand-item';
import { PackingListSummaryBar } from './_components/packing-list-summary-bar';
import { usePackingListReport } from './_hooks/use-packing-list-report';

export const Route = createFileRoute('/_app/logistic/packing-list-report/')({
  component: PackingListReportPage,
});

export default function PackingListReportPage() {
  const {
    t,
    draftFilters,
    hasApplied,
    clientFilters,
    projectQuery,
    projectOptions,
    reportQuery,
    groupedRows,
    totalGroupCount,
    summary,
    openKeys,
    toggleOpen,
    isAllExpanded,
    toggleExpandAll,
    optionSource,
    finishedGoodOptions,
    modelOptions,
    designModelOptions,
    hasModelData,
    hasDesignModelData,
    hasActiveClientFilter,
    hiddenGroups,
    toggleColumnGroup,
    visibleColumns,
    visibleColumnGroups,
    tableMinWidth,
    handleApplyFilters,
    handleExportReport,
    handleProjectSearch,
    handleProjectChange,
    setClientFilters,
    setStatusFilter,
    clearClientFilters,
  } = usePackingListReport();

  const canApply = !!draftFilters.projectId;

  const receiptStatusOptions = useMemo(
    () => [
      { value: 'ALL', label: t('report.filter.statusAll', { defaultValue: 'Tất cả trạng thái' }) },
      {
        value: String(EPackingReportStatus.Empty),
        label: t('report.status.RECEIPT_STATUS_EMPTY', { defaultValue: 'Chưa nhập kho' }),
      },
      {
        value: String(EPackingReportStatus.Partial),
        label: t('report.status.RECEIPT_STATUS_PARTIAL', { defaultValue: 'Đã nhập chưa đủ' }),
      },
      {
        value: String(EPackingReportStatus.Full),
        label: t('report.status.RECEIPT_STATUS_FULL', { defaultValue: 'Đã nhập đủ' }),
      },
    ],
    [t],
  );

  const deliveryStatusOptions = useMemo(
    () => [
      { value: 'ALL', label: t('report.filter.statusAll', { defaultValue: 'Tất cả trạng thái' }) },
      {
        value: String(EPackingReportStatus.Empty),
        label: t('report.status.DELIVERY_STATUS_EMPTY', { defaultValue: 'Chưa giao' }),
      },
      {
        value: String(EPackingReportStatus.Partial),
        label: t('report.status.DELIVERY_STATUS_PARTIAL', { defaultValue: 'Đã giao chưa đủ' }),
      },
      {
        value: String(EPackingReportStatus.Full),
        label: t('report.status.DELIVERY_STATUS_FULL', { defaultValue: 'Đã giao đủ' }),
      },
    ],
    [t],
  );

  const filterButtonClass =
    'w-full h-9 flex justify-between font-normal shadow-none bg-background text-xs';

  return (
    <div className="space-y-3 pb-8">
      {/* 1. Page Header */}
      <div className="flex flex-col gap-1 pb-1 sm:flex-row sm:items-center sm:justify-between">
        <div className="flex items-center gap-2.5">
          <div className="flex h-9 w-9 items-center justify-center rounded-lg bg-primary/10 text-primary ring-1 ring-primary/20">
            <PackageCheck className="h-5 w-5" />
          </div>
          <div>
            <h1 className="text-lg font-bold tracking-tight text-foreground">
              {t('report.title', { defaultValue: 'Báo cáo Packing List' })}
            </h1>
            <p className="text-xs text-muted-foreground">
              {t('report.description', {
                defaultValue:
                  'Theo dõi tiến độ đóng kiện, quy cách hàng hóa và tình trạng nhập kho / giao hàng theo dự án',
              })}
            </p>
          </div>
        </div>
      </div>

      {/* 2. Top Filter Card: Chọn Dự Án + Nút Hành Động */}
      <Card className="rounded-xl border bg-card/95 p-3.5 shadow-xs">
        <div className="flex flex-col gap-3 sm:flex-row sm:items-end sm:justify-between">
          <div className="w-full sm:max-w-md">
            <label className="mb-1 ml-0.5 block text-xs font-semibold uppercase tracking-wide text-muted-foreground">
              {t('report.filter.project', { defaultValue: 'DỰ ÁN' })}
            </label>
            <AutocompleteCombobox
              options={projectOptions}
              loading={projectQuery.isFetching}
              error={projectQuery.error}
              onRetry={() => projectQuery.refetch()}
              value={draftFilters.projectId}
              onValueChange={handleProjectChange}
              onSearch={handleProjectSearch}
              placeholder={t('report.filter.projectPlaceholder', { defaultValue: 'Chọn dự án' })}
              searchPlaceholder={t('report.filter.projectSearchPlaceholder', {
                defaultValue: 'Tìm dự án...',
              })}
            />
          </div>

          <div className="flex flex-wrap items-center gap-2">
            <Button
              size="sm"
              onClick={handleApplyFilters}
              className="gap-2 active:scale-95 transition-transform"
              disabled={!canApply}
            >
              <Search className="h-4 w-4" />
              {t('report.filter.applyFilter', { defaultValue: 'Áp dụng bộ lọc' })}
            </Button>
            <Button
              variant="outline"
              size="sm"
              onClick={handleExportReport}
              className="gap-2 active:scale-95 transition-transform"
              disabled={!hasApplied || reportQuery.isLoading}
            >
              <Download className="h-4 w-4" />
              {t('report.filter.exportExcel', { defaultValue: 'Xuất Excel' })}
            </Button>
          </div>
        </div>
      </Card>

      {/* 3. KPI Summary Bar: 4 khối tóm tắt tổng quan */}
      {hasApplied && optionSource.length > 0 && (
        <PackingListSummaryBar summary={summary} />
      )}

      {/* 4. Secondary Filter & Action Toolbar */}
      {hasApplied && optionSource.length > 0 && (
        <div className="sticky top-0 z-20 flex flex-col gap-3 rounded-xl border bg-card/95 px-4 py-3 shadow-xs backdrop-blur-md supports-backdrop-filter:bg-card/85">
          <div className="flex flex-col gap-2.5 lg:flex-row lg:items-center lg:justify-between">
            {/* Lọc con: Thành phẩm, Model, Trạng thái */}
            <div className="flex flex-1 flex-col gap-2.5 lg:flex-row lg:items-center">
              <div className="flex shrink-0 items-center gap-1.5 text-xs font-semibold text-muted-foreground">
                <SlidersHorizontal className="h-3.5 w-3.5" />
                <span className="tabular-nums">
                  {t('report.filter.resultCount', {
                    shown: groupedRows.length,
                    total: totalGroupCount,
                    defaultValue: `${groupedRows.length}/${totalGroupCount} nhóm`,
                  })}
                </span>
              </div>

              <div
                className={cn(
                  'grid flex-1 grid-cols-1 gap-2 sm:grid-cols-2',
                  hasModelData && hasDesignModelData
                    ? 'xl:grid-cols-5'
                    : hasModelData || hasDesignModelData
                      ? 'xl:grid-cols-4'
                      : 'xl:grid-cols-3',
                )}
              >
                <Combobox
                  options={finishedGoodOptions}
                  value={clientFilters.finishedGoodId}
                  onValueChange={(val) => {
                    setClientFilters((prev) => ({
                      ...prev,
                      finishedGoodId: val || '',
                    }));
                  }}
                  placeholder={t('report.filter.allFinishedGoods', {
                    defaultValue: 'Tất cả thành phẩm',
                  })}
                  searchPlaceholder={t('report.filter.finishedGood', {
                    defaultValue: 'Thành phẩm',
                  })}
                  popoverClassName="z-[60]"
                  buttonProps={{ className: filterButtonClass }}
                />

                {hasModelData && (
                  <Combobox
                    options={modelOptions}
                    value={clientFilters.modelId}
                    onValueChange={(val) => {
                      setClientFilters((prev) => ({
                        ...prev,
                        modelId: val || '',
                      }));
                    }}
                    placeholder={t('report.filter.allModels', {
                      defaultValue: 'Tất cả model hiệu suất',
                    })}
                    searchPlaceholder={t('report.filter.model', { defaultValue: 'Model hiệu suất' })}
                    popoverClassName="z-[60]"
                    buttonProps={{ className: filterButtonClass }}
                  />
                )}

                {hasDesignModelData && (
                  <Combobox
                    options={designModelOptions}
                    value={clientFilters.designModelId}
                    onValueChange={(val) => {
                      setClientFilters((prev) => ({
                        ...prev,
                        designModelId: val || '',
                      }));
                    }}
                    placeholder={t('report.filter.allDesignModels', {
                      defaultValue: 'Tất cả model thiết kế',
                    })}
                    searchPlaceholder={t('report.filter.designModel', {
                      defaultValue: 'Model thiết kế',
                    })}
                    popoverClassName="z-[60]"
                    buttonProps={{ className: filterButtonClass }}
                  />
                )}

                <Combobox
                  options={receiptStatusOptions}
                  value={
                    clientFilters.receiptStatus === 'ALL'
                      ? 'ALL'
                      : String(clientFilters.receiptStatus)
                  }
                  onValueChange={(val) => setStatusFilter('receiptStatus', val)}
                  placeholder={t('report.filter.receiptStatus', {
                    defaultValue: 'Tình trạng nhập kho',
                  })}
                  popoverClassName="z-[60]"
                  buttonProps={{ className: filterButtonClass }}
                />

                <Combobox
                  options={deliveryStatusOptions}
                  value={
                    clientFilters.siteDeliveryStatus === 'ALL'
                      ? 'ALL'
                      : String(clientFilters.siteDeliveryStatus)
                  }
                  onValueChange={(val) => setStatusFilter('siteDeliveryStatus', val)}
                  placeholder={t('report.filter.deliveryStatus', {
                    defaultValue: 'Tình trạng giao',
                  })}
                  popoverClassName="z-[60]"
                  buttonProps={{ className: filterButtonClass }}
                />
              </div>

              {hasActiveClientFilter && (
                <Button
                  variant="ghost"
                  size="sm"
                  onClick={clearClientFilters}
                  className="h-9 shrink-0 gap-1 text-xs text-muted-foreground hover:text-foreground"
                >
                  <RotateCcw className="h-3.5 w-3.5" />
                  <span>{t('report.filter.clear', { defaultValue: 'Xóa lọc' })}</span>
                </Button>
              )}
            </div>

            {/* Các hành động bảng: Mở rộng/Thu gọn tất cả + Ẩn hiện cột */}
            <div className="flex shrink-0 items-center gap-2 border-t pt-2 lg:border-t-0 lg:pt-0 lg:border-l lg:pl-3">
              {groupedRows.length > 1 && (
                <Button
                  type="button"
                  variant="outline"
                  size="sm"
                  className="h-9 gap-1.5 text-xs text-foreground/80 hover:text-foreground"
                  onClick={toggleExpandAll}
                >
                  {isAllExpanded ? (
                    <>
                      <ChevronsDownUp className="h-3.5 w-3.5" />
                      <span>{t('report.action.collapseAll', { defaultValue: 'Thu gọn tất cả' })}</span>
                    </>
                  ) : (
                    <>
                      <ChevronsUpDown className="h-3.5 w-3.5" />
                      <span>{t('report.action.expandAll', { defaultValue: 'Mở rộng tất cả' })}</span>
                    </>
                  )}
                </Button>
              )}

              {/* Bật/tắt nhóm cột */}
              <Popover>
                <PopoverTrigger asChild>
                  <Button variant="outline" size="sm" className="h-9 shrink-0 gap-1.5 text-xs">
                    <Columns3 className="h-4 w-4" />
                    <span>{t('report.filter.columns', { defaultValue: 'Cột' })}</span>
                    {hiddenGroups.size > 0 && (
                      <span className="ml-0.5 rounded bg-primary/10 px-1 text-[11px] font-medium text-primary tabular-nums">
                        {COLUMN_GROUP_DEFS.length - hiddenGroups.size}/{COLUMN_GROUP_DEFS.length}
                      </span>
                    )}
                  </Button>
                </PopoverTrigger>
                <PopoverContent align="end" className="w-64 p-1.5">
                  <div className="px-2 py-1.5 text-[11px] font-semibold uppercase tracking-wide text-muted-foreground">
                    {t('report.filter.columnGroups', { defaultValue: 'Nhóm cột hiển thị' })}
                  </div>
                  {COLUMN_GROUP_DEFS.map((g) => (
                    <button
                      key={g.id}
                      type="button"
                      onClick={() => toggleColumnGroup(g.id)}
                      className="flex w-full items-center gap-2 rounded-md px-2 py-1.5 text-left text-sm hover:bg-muted"
                    >
                      <Checkbox checked={!hiddenGroups.has(g.id)} className="pointer-events-none" />
                      <span>{t(g.labelKey)}</span>
                    </button>
                  ))}
                </PopoverContent>
              </Popover>
            </div>
          </div>
        </div>
      )}

      {/* 5. Report Content / Rows */}
      <ReportContent
        columns={visibleColumns}
        columnGroups={visibleColumnGroups}
        tableMinWidth={tableMinWidth}
        groupedRows={groupedRows}
        isLoading={reportQuery.isLoading}
        isFetching={reportQuery.isFetching}
        hasApplied={hasApplied}
        hasRows={optionSource.length > 0}
        openKeys={openKeys}
        toggleOpen={toggleOpen}
      />
    </div>
  );
}

interface ReportContentProps {
  columns: any[];
  columnGroups: { label: string; columnIds: string[] }[];
  tableMinWidth: number;
  groupedRows: GroupedFGRow[];
  isLoading: boolean;
  isFetching: boolean;
  hasApplied: boolean;
  hasRows: boolean;
  openKeys: Set<string>;
  toggleOpen: (key: string) => void;
}

function ReportContent({
  columns,
  columnGroups,
  tableMinWidth,
  groupedRows,
  isLoading,
  isFetching,
  hasApplied,
  hasRows,
  openKeys,
  toggleOpen,
}: Readonly<ReportContentProps>) {
  const { t } = useTranslation(['mechanicalPackingList', 'common']);

  if (isLoading) {
    return (
      <Card className="rounded-xl border bg-card shadow-xs">
        <CardContent className="px-5 py-12 flex flex-col items-center justify-center gap-3 text-muted-foreground">
          <Loader2 className="h-8 w-8 animate-spin text-primary" />
          <span className="text-sm font-medium">
            {t('report.summary.loading', { defaultValue: 'Đang tải dữ liệu báo cáo...' })}
          </span>
        </CardContent>
      </Card>
    );
  }

  if (!hasApplied) {
    return (
      <Card className="rounded-xl border bg-card shadow-xs">
        <CardContent className="px-5 py-12 text-center">
          <div className="flex flex-col items-center gap-3">
            <div className="rounded-full bg-primary/10 p-3 text-primary">
              <Boxes className="h-6 w-6" />
            </div>
            <p className="text-sm font-medium text-muted-foreground">
              {t('report.summary.applyToView', {
                defaultValue: 'Vui lòng chọn dự án và nhấn "Áp dụng bộ lọc" để xem báo cáo.',
              })}
            </p>
          </div>
        </CardContent>
      </Card>
    );
  }

  if (groupedRows.length === 0) {
    return (
      <Card className="rounded-xl border bg-card shadow-xs">
        <CardContent className="px-5 py-12 text-center">
          <div className="flex flex-col items-center gap-3 text-muted-foreground">
            {isFetching ? (
              <>
                <Loader2 className="h-6 w-6 animate-spin text-primary/60" />
                <span className="text-sm">
                  {t('report.summary.searching', { defaultValue: 'Đang tìm kiếm...' })}
                </span>
              </>
            ) : (
              <>
                <div className="rounded-full bg-muted p-3">
                  <Search className="h-6 w-6 text-muted-foreground/40" />
                </div>
                <span className="text-sm">
                  {t(hasRows ? 'report.summary.noMatch' : 'report.summary.noData', {
                    defaultValue: hasRows
                      ? 'Không có thành phẩm nào khớp với bộ lọc hiện tại.'
                      : 'Không tìm thấy dữ liệu packing list cho dự án này.',
                  })}
                </span>
              </>
            )}
          </div>
        </CardContent>
      </Card>
    );
