interface ReportContentProps {
  columns: any[];
  columnGroups: { label: string; columnIds: string[] }[];
  tableMinWidth: number;
  groupedRows: GroupedFGRow[];
  isLoading: boolean;
  isFetching: boolean;
  hasApplied: boolean;
  hasRows: boolean;
  openKeys: Set<string>;
  toggleOpen: (key: string) => void;
  isAllExpanded: boolean;
  toggleExpandAll: () => void;
  totalGroupCount: number;
  totalTagNos: number;
  hiddenGroups: Set<ColGroupId>;
  toggleColumnGroup: (id: ColGroupId) => void;
}

function ReportContent({
  columns,
  columnGroups,
  tableMinWidth,
  groupedRows,
  isLoading,
  isFetching,
  hasApplied,
  hasRows,
  openKeys,
  toggleOpen,
  isAllExpanded,
  toggleExpandAll,
  totalGroupCount,
  totalTagNos,
  hiddenGroups,
  toggleColumnGroup,
}: Readonly<ReportContentProps>) {
  const { t } = useTranslation(['mechanicalPackingList', 'common']);

  if (isLoading) {
    return (
      <Card className="rounded-xl border bg-card shadow-xs">
        <CardContent className="px-5 py-12 flex flex-col items-center justify-center gap-3 text-muted-foreground">
          <Loader2 className="h-8 w-8 animate-spin text-primary" />
          <span className="text-sm font-medium">
            {t('report.summary.loading', { defaultValue: 'Đang tải dữ liệu báo cáo...' })}
          </span>
        </CardContent>
      </Card>
    );
  }

  if (!hasApplied) {
    return (
      <Card className="rounded-xl border bg-card shadow-xs">
        <CardContent className="px-5 py-12 text-center">
          <div className="flex flex-col items-center gap-3">
            <div className="rounded-full bg-primary/10 p-3 text-primary">
              <Boxes className="h-6 w-6" />
            </div>
            <p className="text-sm font-medium text-muted-foreground">
              {t('report.summary.applyToView', {
                defaultValue: 'Vui lòng chọn dự án và nhấn "Áp dụng bộ lọc" để xem báo cáo.',
              })}
            </p>
          </div>
        </CardContent>
      </Card>
    );
  }

  if (groupedRows.length === 0) {
    return (
      <Card className="rounded-xl border bg-card shadow-xs">
        <CardContent className="px-5 py-12 text-center">
          <div className="flex flex-col items-center gap-3 text-muted-foreground">
            {isFetching ? (
              <>
                <Loader2 className="h-6 w-6 animate-spin text-primary/60" />
                <span className="text-sm">
                  {t('report.summary.searching', { defaultValue: 'Đang tìm kiếm...' })}
                </span>
              </>
            ) : (
              <>
                <div className="rounded-full bg-muted p-3">
                  <Search className="h-6 w-6 text-muted-foreground/40" />
                </div>
                <span className="text-sm">
                  {t(hasRows ? 'report.summary.noMatch' : 'report.summary.noData', {
                    defaultValue: hasRows
                      ? 'Không có thành phẩm nào khớp với bộ lọc hiện tại.'
                      : 'Không tìm thấy dữ liệu packing list cho dự án này.',
                  })}
                </span>
              </>
            )}
          </div>
        </CardContent>
      </Card>
    );
  }

  return (
    <div className="space-y-2.5">
      {/* Thanh điều khiển danh sách: Tiêu đề + Đếm số lượng + Mở rộng tất cả + Cột hiển thị */}
      <div className="flex flex-col gap-2 sm:flex-row sm:items-center sm:justify-between px-1 pt-1 pb-0.5">
        <div className="flex items-center gap-2">
          <span className="h-4 w-1.5 shrink-0 rounded-full bg-primary" />
          <h2 className="text-sm font-bold text-foreground">
            {t('report.section.finishedGoodList', { defaultValue: 'Danh sách thành phẩm' })}
          </h2>
          <span className="inline-flex items-center rounded-md bg-muted px-2 py-0.5 text-xs font-semibold text-foreground tabular-nums">
            {groupedRows.length} / {totalGroupCount} {t('report.summary.groupsUnit', { defaultValue: 'nhóm' })}
          </span>
          <span className="text-xs text-muted-foreground tabular-nums">
            · {totalTagNos} {t('report.summary.tagNoUnit', { defaultValue: 'kiện' })}
          </span>
        </div>

        <div className="flex items-center gap-2">
          <Button
            type="button"
            variant="outline"
            size="sm"
            className="h-8 gap-1.5 text-xs font-medium text-foreground hover:bg-muted"
            onClick={toggleExpandAll}
          >
            {isAllExpanded ? (
              <>
                <ChevronsDownUp className="h-3.5 w-3.5 text-primary" />
                <span>{t('report.action.collapseAll', { defaultValue: 'Thu gọn tất cả' })}</span>
              </>
            ) : (
              <>
                <ChevronsUpDown className="h-3.5 w-3.5 text-primary" />
                <span>{t('report.action.expandAll', { defaultValue: 'Mở rộng tất cả' })}</span>
              </>
            )}
          </Button>

          {/* Tùy chọn nhóm cột */}
          <Popover>
            <PopoverTrigger asChild>
              <Button variant="outline" size="sm" className="h-8 gap-1.5 text-xs font-medium text-foreground">
                <Columns3 className="h-3.5 w-3.5 text-muted-foreground" />
                <span>{t('report.filter.columns', { defaultValue: 'Cột hiển thị' })}</span>
                {hiddenGroups.size > 0 && (
                  <span className="ml-0.5 rounded bg-primary/10 px-1 text-[11px] font-semibold text-primary tabular-nums">
                    {COLUMN_GROUP_DEFS.length - hiddenGroups.size}/{COLUMN_GROUP_DEFS.length}
                  </span>
                )}
              </Button>
            </PopoverTrigger>
            <PopoverContent align="end" className="w-64 p-1.5">
              <div className="px-2 py-1.5 text-[11px] font-semibold uppercase tracking-wide text-muted-foreground">
                {t('report.filter.columnGroups', { defaultValue: 'Nhóm cột hiển thị' })}
              </div>
              {COLUMN_GROUP_DEFS.map((g) => (
                <button
                  key={g.id}
                  type="button"
                  onClick={() => toggleColumnGroup(g.id)}
                  className="flex w-full items-center gap-2 rounded-md px-2 py-1.5 text-left text-sm hover:bg-muted"
                >
                  <Checkbox checked={!hiddenGroups.has(g.id)} className="pointer-events-none" />
                  <span>{t(g.labelKey)}</span>
                </button>
              ))}
            </PopoverContent>
          </Popover>
        </div>
      </div>

      {/* Danh sách Cards Thành phẩm */}
      <div className="flex flex-col gap-2.5">
        {groupedRows.map((item) => (
          <FinishedGoodExpandItem
            key={item.key}
            item={item}
            columns={columns}
            columnGroups={columnGroups}
            tableMinWidth={tableMinWidth}
            isOpen={openKeys.has(item.key)}
            onToggle={() => toggleOpen(item.key)}
          />
        ))}
      </div>
    </div>
  );
}

