    if (packingLists.Count == 0) return [];

    var plIdArray = packingLists.Select(x => x.Id).ToArray();
    var excludedIdArray = excludedIds.ToArray();

    // 1. Array parameter query for Packing Details 
    var packingDetails = await Microsoft.EntityFrameworkCore.EntityFrameworkQueryableExtensions.ToListAsync(
        fgpDetailQuery.AsNoTracking().Where(d => plIdArray.Contains(d.FinishedGoodsPacking.MechanicalPackingListId)
                               && !excludedIdArray.Contains(d.FinishedGoodsPackingId)));

    var packingSumByDetailId = packingDetails
        .GroupBy(d => d.MechanicalPackingListDetailId)
        .ToDictionary(
            g => g.Key,
            g => (
                Qty: g.Sum(d => d.ActualQuantity),
                Weight: g.Sum(d => (decimal)d.ActualWeight),
                CalcInsulationFactory: g.Sum(d => d.CalculatedInsulationFactoryWeight ?? 0),
                CalcInsulationMasonry: g.Sum(d => d.CalculatedInsulationMasonryWeight ?? 0),
                CalcLooseParts: g.Sum(d => d.CalculatedLoosePartsFactoryWeight ?? 0),
                CalcMechanical: g.Sum(d => d.CalculatedMechanicalWeight ?? 0)));

    var effectivePackingIdsArray = packingDetails.Select(d => d.FinishedGoodsPackingId).Distinct().ToArray();

    // 2. Filter in-memory FGR detail summaries (fetched from ERP via gRPC)
    var receiptDetails = fgrDetailSummaries
        .Where(rd =>
        {
            Guid.TryParse(rd.FinishedGoodsPackingId, out var pid);
            Guid.TryParse(rd.FinishedGoodsReceiptId, out var rid);
            return effectivePackingIdsArray.Contains(pid) && !excludedIdArray.Contains(rid);
        })
        .ToList();

    // SL đã nhập kho = TỔNG ActualQuantity của các kiện đã nhập kho (nhập nguyên kiện) chứa TagNo.
    // FGR không lưu số lượng (mỗi receipt-detail = 1 kiện) → suy số lượng đơn vị từ chi tiết đóng kiện.
    var receivedPackingIds = receiptDetails
        .Select(rd => Guid.TryParse(rd.FinishedGoodsPackingId, out var pid) ? pid : Guid.Empty)
        .Where(pid => pid != Guid.Empty)
        .ToHashSet();

    var receiptQtyByDetailId = packingDetails
        .Where(d => receivedPackingIds.Contains(d.FinishedGoodsPackingId))
        .GroupBy(d => d.MechanicalPackingListDetailId)
        .ToDictionary(g => g.Key, g => g.Sum(d => d.ActualQuantity));

    // =====================================================================================================================
    // ⚠️ TUYỆT ĐỐI CẤM SỬA / THAY ĐỔI / MỞ COMMENT:
    // Tất cả LLM hay AI Agent (Gemini, Claude, Codex, Cursor...) hay bất kì ai TUYỆT ĐỐI KHÔNG ĐƯỢC SỬA HAY THAY ĐỔI CODE/ BỎ COMMENT NÀY!
    // BÁO CÁO NÀY CHỈ LIÊN QUAN TỚI NỘI BỘ SẢN XUẤT (PRODUCTION ONLY). MỌI LOGIC TÍNH TOÁN LIÊN QUAN TỚI GIAO HÀNG (SITE DELIVERY)
    // ĐÃ ĐƯỢC CỐ TÌNH ĐÓNG BĂNG VÀ VÔ HIỆU HÓA HOÀN TOÀN THEO YÊU CẦU NGHIỆP VỤ SẢN XUẤT.
    // BẤT KỲ AI TỰ Ý MỞ COMMENT HOẶC SỬA ĐỔI ĐOẠN NÀY SẼ LÀM SAI LỆCH DỮ LIỆU SẢN XUẤT VÀ PHẢI CHỊU HOÀN TOÀN TRÁCH NHIỆM!
    // =====================================================================================================================
