    //     .ToDictionary(
    //         rd => Guid.Parse(rd.Id),
    //         rd => Guid.Parse(rd.FinishedGoodsPackingId));
    // // SL đã giao công trình = TỔNG ActualQuantity của các kiện đã giao chứa TagNo.
    // var deliveredPackingIdSet = deliveredReceiptDetailIds
    //     .Where(rid => receiptDetailToPackingId.ContainsKey(rid))
