    //     .GroupBy(d => d.MechanicalPackingListDetailId)
    //     .ToDictionary(g => g.Key, g => g.Sum(d => d.ActualQuantity));

    // Map DTOs
    int estimatedRowCount = packingLists.Sum(pl => pl.Details?.Count ?? 0);
    var rows = new List<PackingListReportRowDto>(estimatedRowCount);
    int stt = 1;

    foreach (var pl in packingLists.OrderBy(x => x.FinishedGoodsCode))
    {
        var project = projMap.GetValueOrDefault(pl.ProjectId.ToString());

        foreach (var detail in (pl.Details ?? Enumerable.Empty<MechanicalPackingListDetail>()).OrderBy(d => d.LineNum))
        {
            var packedSum = packingSumByDetailId.GetValueOrDefault(detail.Id);
            var receiptQty = receiptQtyByDetailId.GetValueOrDefault(detail.Id);

