        .GroupBy(d => d.MechanicalPackingListDetailId)
        .ToDictionary(g => g.Key, g => g.Sum(d => d.ActualQuantity));

    // 3. Xác định các kiện đã giao công trình cho mỗi mechanical-packing detail.
    //    SiteDeliveryDetail giờ trỏ tới kiện lớn (FinishedGoodsDeliveryPackingId) → bắc cầu qua
    //    FinishedGoodsDeliveryPackingDetail để biết FinishedGoodsReceiptDetailId nào đã giao.
    var receiptDetailIdsArray = receiptDetails
        .Select(rd => Guid.TryParse(rd.Id, out var id) ? id : Guid.Empty)
        .Where(id => id != Guid.Empty)
        .ToArray();

    var deliveredPackingIds = await Microsoft.EntityFrameworkCore.EntityFrameworkQueryableExtensions.ToListAsync(
        sdDetailQuery.AsNoTracking()
            .Where(sd => !excludedIdArray.Contains(sd.SiteDeliveryId))
            .Select(sd => sd.FinishedGoodsDeliveryPackingId)
            .Distinct());

    var deliveredReceiptDetailIds = deliveredPackingIds.Count == 0
        ? new List<Guid>()
        : await Microsoft.EntityFrameworkCore.EntityFrameworkQueryableExtensions.ToListAsync(
            fgDeliveryPackingDetailQuery.AsNoTracking()
                .Where(d => deliveredPackingIds.Contains(d.FinishedGoodsDeliveryPackingId)
                            && receiptDetailIdsArray.Contains(d.FinishedGoodsReceiptDetailId))
                .Select(d => d.FinishedGoodsReceiptDetailId)
                .Distinct());

    var receiptDetailToPackingId = receiptDetails
        .Where(rd => Guid.TryParse(rd.Id, out _) && Guid.TryParse(rd.FinishedGoodsPackingId, out _))
        .ToDictionary(
            rd => Guid.Parse(rd.Id),
            rd => Guid.Parse(rd.FinishedGoodsPackingId));
    // SL đã giao công trình = TỔNG ActualQuantity của các kiện đã giao chứa TagNo.
    var deliveredPackingIdSet = deliveredReceiptDetailIds
        .Where(rid => receiptDetailToPackingId.ContainsKey(rid))
        .Select(rid => receiptDetailToPackingId[rid])
        .ToHashSet();

    var deliveryQtyByDetailId = packingDetails
        .Where(d => deliveredPackingIdSet.Contains(d.FinishedGoodsPackingId))
        .GroupBy(d => d.MechanicalPackingListDetailId)
        .ToDictionary(g => g.Key, g => g.Sum(d => d.ActualQuantity));

    // Map DTOs
    int estimatedRowCount = packingLists.Sum(pl => pl.Details?.Count ?? 0);
    var rows = new List<PackingListReportRowDto>(estimatedRowCount);
    int stt = 1;

    foreach (var pl in packingLists.OrderBy(x => x.FinishedGoodsCode))
    {
        var project = projMap.GetValueOrDefault(pl.ProjectId.ToString());

        foreach (var detail in (pl.Details ?? Enumerable.Empty<MechanicalPackingListDetail>()).OrderBy(d => d.LineNum))
        {
            var packedSum = packingSumByDetailId.GetValueOrDefault(detail.Id);
            var receiptQty = receiptQtyByDetailId.GetValueOrDefault(detail.Id);
            var deliveryQty = deliveryQtyByDetailId.GetValueOrDefault(detail.Id);

            rows.Add(new PackingListReportRowDto
            {
                STT = stt++,
                MechanicalPackingListCode = pl.Code,
                MechanicalPackingListId = pl.Id,
                MechanicalPackingListDetailId = detail.Id,
                FinishedGoodId = pl.FinishedGoodId,
                FinishedGoodCode = pl.FinishedGoodsCode,
                FinishedGoodName = pl.FinishedGoodsName,
                ModelId = pl.ModelId ?? Guid.Empty,
                DesignModelId = pl.DesignModelId,
                SemiFinishedGoodId = detail.SemiFinishedGoodId,
                ProductPartName = null,
                ProductDescription = detail.ProductDescription,
                TagNo = detail.TagNo,
                UOMId = detail.UOMId,
                DimensionL = detail.DimensionL,
                DimensionW = detail.DimensionW,
                DimensionH = detail.DimensionH,
                DesignQuantity = detail.Quantity,
                DesignWeight = detail.DesignWeight,
                InsulationFactoryWeight = detail.InsulationFactoryWeight,
                InsulationMasonryWeight = detail.InsulationMasonryWeight,
                LoosePartsFactoryWeight = detail.LoosePartsFactoryWeight,
                PackedQuantity = packedSum.Qty,
                PackedWeight = packedSum.Weight,
                CalculatedInsulationFactoryWeight = packedSum.CalcInsulationFactory,
                CalculatedInsulationMasonryWeight = packedSum.CalcInsulationMasonry,
                CalculatedLoosePartsFactoryWeight = packedSum.CalcLooseParts,
                CalculatedMechanicalWeight = packedSum.CalcMechanical,
                ReceiptQuantity = receiptQty,
                SiteDeliveryQuantity = deliveryQty,
                ReceiptStatus = ComputeStatus(receiptQty, detail.Quantity),
                SiteDeliveryStatus = ComputeStatus(deliveryQty, detail.Quantity),
                PackingCodeCheck = ComputeStatus(packedSum.Qty, detail.Quantity),
                Remark = detail.Remark,

