144:             if (!map.TryGetValue(pk.OrderId, out var r)) continue;
145:             r.PackedQuantity += pk.Qty;
146:             r.PackedWeight += pk.ActualTotalWeight;
147:             r.PackageCount++;
148:             if (deliveredSet.Contains(pk.Id))
149:             {
