162:                 r.PlannedQuantity > 0 && r.DeliveredQuantity >= r.PlannedQuantity ? EDeliveryStage.Completed
163:                 : r.DeliveredPackageCount > 0 ? EDeliveryStage.Delivering
164:                 : r.PackageCount > 0 ? EDeliveryStage.Packed
