using System;
using System.Collections.Generic;
using Shared.Domain.Entities;
using Shared.Enums;

namespace Shared.Dto.ServiceDesk.PackingList;

/// <summary>Bộ lọc cho Báo cáo Packing Giao hàng (Delivery Packing Report)</summary>
public record DeliveryPackingReportFilterRequest : AutoFilterPaging
{
    /// <summary>ID dự án (nếu lọc theo Dự án công trình)</summary>
    public Guid? ProjectId { get; set; }

    /// <summary>ID đơn bán hàng (nếu lọc theo Đơn bán hàng SO - bán thẳng NVL/thương mại)</summary>
    public Guid? SalesOrderId { get; set; }

    /// <summary>Lệnh đóng gói giao hàng (DeliveryPackaging)</summary>
    public Guid? DeliveryPackagingId { get; set; }

    /// <summary>Trạng thái giao hàng công trình / khách hàng</summary>
    public EPackingReportStatus? SiteDeliveryStatus { get; set; }

    /// <summary>Mã kiện cần tìm</summary>
    public string PackingCode { get; set; }

    /// <summary>ID thành phẩm</summary>
    public Guid? FinishedGoodId { get; set; }

    /// <summary>ID model</summary>
    public Guid? ModelId { get; set; }

    /// <summary>Lọc từ ngày</summary>
    public DateTime? FromDate { get; set; }

    /// <summary>Lọc đến ngày</summary>
    public DateTime? ToDate { get; set; }
}

/// <summary>Dòng con cấp 2: Cụm chi tiết sản phẩm HOẶC Nguyên vật liệu bán thẳng nằm trong kiện</summary>
public record DeliveryPackingReportSubItemDto
{
    public Guid Id { get; set; }

    /// <summary>Loại mặt hàng: "PART" (Cụm chi tiết) hoặc "MATERIAL" (Nguyên vật liệu bán thẳng)</summary>
    public string ItemType { get; set; } = "PART";

    /// <summary>Mã nhận dạng: TagNo (nếu là cụm) hoặc MaterialCode (nếu là NVL)</summary>
    public string Code { get; set; }

    /// <summary>Tên cụm hoặc Tên nguyên vật liệu</summary>
    public string Name { get; set; }

    /// <summary>Mô tả / Quy cách chi tiết</summary>
    public string Specification { get; set; }

    /// <summary>Mã và Tên Đơn vị tính</summary>
    public Guid? UomId { get; set; }
    public string UomName { get; set; }

    /// <summary>Kích thước cụm</summary>
    public decimal? DimensionL { get; set; }
    public decimal? DimensionW { get; set; }
    public decimal? DimensionH { get; set; }

    /// <summary>Số lượng trong kiện</summary>
    public decimal Quantity { get; set; }

    /// <summary>Khối lượng thực tế (kg)</summary>
    public decimal Weight { get; set; }

    /// <summary>Kho xuất hàng (áp dụng cho NVL bán thẳng)</summary>
    public Guid? FromWarehouseId { get; set; }
    public string FromWarehouseName { get; set; }

    /// <summary>Ghi chú</summary>
    public string Remark { get; set; }
}

/// <summary>Dòng cha cấp 1: KIỆN GIAO HÀNG / KIỆN KHO XUẤT</summary>
public record DeliveryPackingReportPackageDto
{
    public int STT { get; set; }
    public Guid Id { get; set; }

    /// <summary>Mã kiện giao hàng</summary>
    public string PackingCode { get; set; }

    /// <summary>Kích thước kiện (D x R x C mm)</summary>
    public string Dimensions { get; set; }

    /// <summary>Khối lượng thực tế kiện (kg)</summary>
    public decimal ActualTotalWeight { get; set; }

    /// <summary>Nguồn gốc: "PROJECT" (Theo dự án) hoặc "SALES_ORDER" (Theo SO)</summary>
    public string SourceType { get; set; } = "PROJECT";

    // --- Thông tin Dự án ---
    public Guid? ProjectId { get; set; }
    public string ProjectCode { get; set; }
    public string ProjectName { get; set; }

    // --- Thông tin Đơn bán hàng SO (nếu là bán thẳng NVL) ---
    public Guid? SalesOrderId { get; set; }
    public string SalesOrderCode { get; set; }
    public string CustomerName { get; set; }

    // --- Thông tin Lệnh giao & Bảng kê ---
    public Guid? DeliveryPackagingId { get; set; }
    public string DeliveryPackagingCode { get; set; }
    public string MechanicalPackingListCode { get; set; }

    // --- Thông tin Thành phẩm / Model ---
    public Guid? FinishedGoodId { get; set; }
    public string FinishedGoodCode { get; set; }
    public string FinishedGoodName { get; set; }
    public Guid? ModelId { get; set; }
    public string ModelCode { get; set; }
    public string ModelName { get; set; }
    public string DesignModelCode { get; set; }

    // --- Tình trạng giao hàng công trình ---
    public Guid? SiteDeliveryId { get; set; }
    public string SiteDeliveryCode { get; set; }
    public EPackingReportStatus SiteDeliveryStatus { get; set; } = EPackingReportStatus.Empty;

    public DateTime? CreatedDate { get; set; }
    public string CreatedBy { get; set; }
    public string Remark { get; set; }

    /// <summary>Số lượng mặt hàng/cụm bên trong kiện</summary>
    public int ItemCount => SubItems?.Count ?? 0;

    /// <summary>Danh sách các Cụm hoặc NVL con bên trong kiện này</summary>
    public List<DeliveryPackingReportSubItemDto> SubItems { get; set; } = [];
}

/// <summary>Dữ liệu tổng hợp KPI cho Báo cáo Packing Giao hàng</summary>
public record DeliveryPackingReportSummaryDto
{
    public int TotalPackages { get; set; }
    public int DeliveredPackages { get; set; }
    public int PendingPackages { get; set; }
    public decimal DeliveryPercentage { get; set; }
    public decimal TotalWeight { get; set; }
    public decimal DeliveredWeight { get; set; }
    public int TotalSubItems { get; set; }
}

/// <summary>Response trả về cho trang Báo cáo Packing Giao hàng</summary>
public record DeliveryPackingReportResponseDto
{
    public DeliveryPackingReportSummaryDto Summary { get; set; } = new();
    public List<DeliveryPackingReportPackageDto> Packages { get; set; } = [];
}

