using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;
using CogainSolution.Grpc.ErpInfo;
using Microsoft.EntityFrameworkCore;
using ServiceDesk.Data.Entities.PackingList;
using ServiceDesk.Data.Entities.SalesOrders;
using Shared.Dto.ServiceDesk.PackingList;
using Shared.Enums;

namespace ServiceDesk.Services.Implement.PackingList;

public static class DeliveryPackingReportQueryBuilder
{
    /// <summary>
    /// Xây dựng dữ liệu báo cáo Packing Giao hàng (Delivery Packing Report)
    /// Hỗ trợ cả 2 nguồn: Theo Dự án (ProjectId) và Bán thẳng theo SO (SalesOrderId).
    /// Cấu trúc bảng lồng 2 cấp: Dòng cha (Kiện) -> Dòng con (Cụm sản phẩm hoặc Nguyên vật liệu).
    /// </summary>
    public static async Task<DeliveryPackingReportResponseDto> BuildReportDataAsync(
        IQueryable<FinishedGoodsDeliveryPacking> deliveryPackingQuery,
        IQueryable<SiteDeliveryDetail> sdDetailQuery,
        IQueryable<FinishedGoodsPackingDetail> fgpDetailQuery,
        List<FgrDetailSummary> fgrDetailSummaries,
        IQueryable<SalesOrder> salesOrderQuery,
        IQueryable<MaterialPackingListDetail> matPlDetailQuery,
        DeliveryPackingReportFilterDto filter,
        HashSet<Guid> excludedWorkItemIds,
        Dictionary<string, CogainSolution.Grpc.MasterDataInfo.ProjectSummary> projMap)
    {
        var response = new DeliveryPackingReportResponseDto();

        // 1. Lọc theo Dự án hoặc Đơn bán hàng SO ở cấp Query
        var query = deliveryPackingQuery.AsNoTracking()
            .Include(p => p.Details)
            .Include(p => p.DeliveryPackaging)
            .AsQueryable();

        if (filter.ProjectId.HasValue && filter.ProjectId.Value != Guid.Empty)
        {
            var pid = filter.ProjectId.Value;
            query = query.Where(p => p.ProjectId == pid || (p.DeliveryPackaging != null && p.DeliveryPackaging.ProjectId == pid));
        }

        if (filter.SalesOrderId.HasValue && filter.SalesOrderId.Value != Guid.Empty)
        {
            var soId = filter.SalesOrderId.Value;
            query = query.Where(p => p.DeliveryPackaging != null && p.DeliveryPackaging.SalesOrderId == soId);
        }

        if (filter.DeliveryPackagingId.HasValue && filter.DeliveryPackagingId.Value != Guid.Empty)
        {
            query = query.Where(p => p.DeliveryPackagingId == filter.DeliveryPackagingId.Value);
        }

        if (!string.IsNullOrWhiteSpace(filter.PackingCode))
        {
            var code = filter.PackingCode.Trim();
            query = query.Where(p => p.Code.Contains(code));
        }

        if (filter.FromDate.HasValue)
        {
            query = query.Where(p => p.CreatedDate >= filter.FromDate.Value);
        }

        if (filter.ToDate.HasValue)
        {
            query = query.Where(p => p.CreatedDate <= filter.ToDate.Value);
        }

        var packagesList = await query.ToListAsync();
        if (packagesList.Count == 0)
        {
            return response;
        }

        // Loại bỏ các WorkItem bị Cancelled / Excluded
        if (excludedWorkItemIds.Count > 0)
        {
            packagesList = packagesList
                .Where(p => p.DeliveryPackagingId == null || !excludedWorkItemIds.Contains(p.DeliveryPackagingId.Value))
                .ToList();
        }

        var packageIds = packagesList.Select(p => p.Id).ToList();

        // 2. Tra cứu trạng thái giao hàng công trình (SiteDelivery)
        var siteDeliveryMap = (await sdDetailQuery.AsNoTracking()
                .Where(sd => packageIds.Contains(sd.FinishedGoodsDeliveryPackingId))
                .Select(sd => new
                {
                    sd.FinishedGoodsDeliveryPackingId,
                    SiteDeliveryId = sd.SiteDeliveryId,
                    SiteDeliveryCode = sd.SiteDelivery.Code
                })
                .ToListAsync())
            .GroupBy(x => x.FinishedGoodsDeliveryPackingId)
            .ToDictionary(g => g.Key, g => g.First());

        // 3. Map SalesOrder Code & CustomerName nếu có
        var salesOrderIds = packagesList
            .Where(p => p.DeliveryPackaging?.SalesOrderId != null)
            .Select(p => p.DeliveryPackaging!.SalesOrderId!.Value)
            .Distinct()
            .ToList();

        var salesOrderMap = salesOrderIds.Count == 0
            ? new Dictionary<Guid, (string Code, string CustomerName)>()
            : (await salesOrderQuery.AsNoTracking()
                .Where(so => salesOrderIds.Contains(so.Id))
                .Select(so => new
                {
                    so.Id,
                    so.Code,
                    CustomerName = so.CustomerNameSnapshot ?? so.CustomerCodeSnapshot ?? ""
                })
                .ToListAsync())
            .ToDictionary(x => x.Id, x => (x.Code, x.CustomerName));

        // 4. Bóc tách Cụm / Chi tiết cơ khí TagNo từ kiện kho thành phẩm
        // Lấy danh sách FinishedGoodsReceiptDetailId từ tất cả packages
        var receiptDetailIds = packagesList
            .SelectMany(p => p.Details ?? Enumerable.Empty<FinishedGoodsDeliveryPackingDetail>())
            .Select(d => d.FinishedGoodsReceiptDetailId)
            .Where(id => id != Guid.Empty)
            .Distinct()
            .ToHashSet();

        // Map ReceiptDetailId -> FinishedGoodsPackingId từ gRPC summaries
        var receiptToPackingMap = fgrDetailSummaries
            .Where(rd => Guid.TryParse(rd.Id, out var rid) && receiptDetailIds.Contains(rid) && Guid.TryParse(rd.FinishedGoodsPackingId, out _))
            .ToDictionary(rd => Guid.Parse(rd.Id), rd => Guid.Parse(rd.FinishedGoodsPackingId));

        var effectiveFgPackingIds = receiptToPackingMap.Values.Distinct().ToArray();

        // Lấy chi tiết cơ khí (TagNo, Cụm) từ FinishedGoodsPackingDetail
        var fgpDetails = effectiveFgPackingIds.Length == 0
            ? []
            : await fgpDetailQuery.AsNoTracking()
                .Where(d => effectiveFgPackingIds.Contains(d.FinishedGoodsPackingId))
                .Include(d => d.MechanicalPackingListDetail)
                .ToListAsync();

        var fgpDetailByPackingId = fgpDetails
            .GroupBy(d => d.FinishedGoodsPackingId)
            .ToDictionary(g => g.Key, g => g.ToList());

        // 5. Build DTOs
        var resultPackages = new List<DeliveryPackingReportPackageDto>(packagesList.Count);
        int stt = 1;

        foreach (var p in packagesList.OrderBy(x => x.Code))
        {
            var project = p.ProjectId.HasValue ? projMap.GetValueOrDefault(p.ProjectId.Value.ToString()) : null;
            var soInfo = p.DeliveryPackaging?.SalesOrderId != null
                ? salesOrderMap.GetValueOrDefault(p.DeliveryPackaging.SalesOrderId.Value)
                : default;

            var siteInfo = siteDeliveryMap.GetValueOrDefault(p.Id);
            var isDelivered = siteInfo != null;

            var firstDetail = p.Details?.FirstOrDefault();

            var pkgDto = new DeliveryPackingReportPackageDto
            {
                STT = stt++,
                Id = p.Id,
                PackingCode = p.Code,
                Dimensions = p.Dimensions,
                ActualTotalWeight = p.ActualTotalWeight,
                SourceType = p.ProjectId.HasValue ? "PROJECT" : "SALES_ORDER",
                ProjectId = p.ProjectId,
                ProjectCode = project?.Code ?? p.ProjectCodeSnapshot,
                ProjectName = project?.Name ?? p.ProjectNameSnapshot,
                SalesOrderId = p.DeliveryPackaging?.SalesOrderId,
                SalesOrderCode = soInfo.Code ?? p.DeliveryPackaging?.SalesOrderCodeSnapshot,
                CustomerName = soInfo.CustomerName,
                DeliveryPackagingId = p.DeliveryPackagingId,
                DeliveryPackagingCode = p.DeliveryPackagingCodeSnapshot ?? p.DeliveryPackaging?.Code,
                MechanicalPackingListCode = firstDetail?.MechanicalPackingListCode,
                FinishedGoodCode = firstDetail?.FinishedGoodsCode,
                FinishedGoodName = firstDetail?.FinishedGoodsName,
                DesignModelCode = firstDetail?.DesignModelCode,
                SiteDeliveryId = siteInfo?.SiteDeliveryId,
                SiteDeliveryCode = siteInfo?.SiteDeliveryCode,
                SiteDeliveryStatus = isDelivered ? EPackingReportStatus.Full : EPackingReportStatus.Empty,
                CreatedDate = p.CreatedDate,
                CreatedBy = p.CreatedBy
            };

            // Lấy danh sách sub-items bên trong kiện
            var subItems = new List<DeliveryPackingReportSubItemDto>();

            if (p.Details != null && p.Details.Count > 0)
            {
                foreach (var detail in p.Details.OrderBy(d => d.LineNum))
                {
                    // Thử tìm các Cụm TagNo chi tiết từ kiện sản xuất
                    if (receiptToPackingMap.TryGetValue(detail.FinishedGoodsReceiptDetailId, out var fgPackingId)
                        && fgpDetailByPackingId.TryGetValue(fgPackingId, out var parts)
                        && parts.Count > 0)
                    {
                        foreach (var part in parts)
                        {
                            var mech = part.MechanicalPackingListDetail;
                            subItems.Add(new DeliveryPackingReportSubItemDto
                            {
                                Id = part.Id,
                                ItemType = "PART",
                                Code = mech?.TagNo ?? part.MechanicalPackingListDetailCodeSnapshot,
                                Name = mech?.SemiFinishedGoodId ?? part.MechanicalPackingListDetailNameSnapshot,
                                Specification = mech?.ProductDescription ?? detail.Remark,
                                UomId = mech?.UOMId,
                                DimensionL = mech?.DimensionL,
                                DimensionW = mech?.DimensionW,
                                DimensionH = mech?.DimensionH,
                                Quantity = part.ActualQuantity,
                                Weight = part.ActualWeight,
                                Remark = detail.Remark
                            });
                        }
                    }
                    else
                    {
                        // Fallback: Kiện kho đã nhập hoặc NVL bán thẳng chưa bóc TagNo
                        subItems.Add(new DeliveryPackingReportSubItemDto
                        {
                            Id = detail.Id,
                            ItemType = p.ProjectId.HasValue ? "PART" : "MATERIAL",
                            Code = detail.PackingCode ?? detail.FinishedGoodsCode ?? $"#{detail.LineNum}",
                            Name = detail.FinishedGoodsName ?? (p.ProjectId.HasValue ? "Kiện thành phẩm" : "Nguyên vật liệu bán thẳng"),
                            Specification = detail.Dimensions ?? detail.DesignModelName,
                            Quantity = detail.ActualQuantity,
                            Weight = detail.ActualWeight,
                            Remark = detail.Remark
                        });
                    }
                }
            }

            pkgDto.SubItems = subItems;
            resultPackages.Add(pkgDto);
        }

        // 6. Áp dụng các bộ lọc phụ ở In-Memory
        if (filter.SiteDeliveryStatus.HasValue)
        {
            resultPackages = resultPackages.Where(p => p.SiteDeliveryStatus == filter.SiteDeliveryStatus.Value).ToList();
        }

        if (filter.FinishedGoodId.HasValue && filter.FinishedGoodId.Value != Guid.Empty)
        {
            resultPackages = resultPackages.Where(p => p.FinishedGoodId == filter.FinishedGoodId.Value).ToList();
        }

        response.Packages = resultPackages;

        // 7. Tính toán KPI Summary
        int totalPkgs = resultPackages.Count;
        int deliveredPkgs = resultPackages.Count(p => p.SiteDeliveryStatus == EPackingReportStatus.Full);
        decimal totalWt = resultPackages.Sum(p => p.ActualTotalWeight);
        decimal deliveredWt = resultPackages.Where(p => p.SiteDeliveryStatus == EPackingReportStatus.Full).Sum(p => p.ActualTotalWeight);
        int totalSubs = resultPackages.Sum(p => p.ItemCount);

        response.Summary = new DeliveryPackingReportSummaryDto
        {
            TotalPackages = totalPkgs,
            DeliveredPackages = deliveredPkgs,
            PendingPackages = totalPkgs - deliveredPkgs,
            DeliveryPercentage = totalPkgs > 0 ? Math.Round((decimal)deliveredPkgs / totalPkgs * 100m, 1) : 0m,
            TotalWeight = totalWt,
            DeliveredWeight = deliveredWt,
            TotalSubItems = totalSubs
        };

        return response;
    }
}

