using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;
using CogainSolution.Grpc.ErpInfo;
using CogainSolution.Grpc.MasterDataInfo;
using Contracts.Domains;
using Contracts.Domain.Entities;
using Contracts.Domain.Interfaces;
using Contracts.Services;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Configuration;
using Serilog;
using ServiceDesk.Data.Entities.PackingList;
using ServiceDesk.Data.Entities.SalesOrders;
using ServiceDesk.Services.Interface.PackingList;
using Shared.Dto.ServiceDesk.PackingList;
using Shared.Enums;

namespace ServiceDesk.Services.Implement.PackingList;

public partial class DeliveryPackingReportService(
    IUnitOfWork unitOfWork,
    IConfiguration config,
    IFileService fileService,
    ILogger logger,
    MasterDataInfoGrpc.MasterDataInfoGrpcClient masterDataGrpcClient,
    ErpInfoGrpc.ErpInfoGrpcClient erpGrpcClient
) : IDeliveryPackingReportService
{
    private readonly IUnitOfWork _unitOfWork = unitOfWork;
    private readonly IConfiguration _config = config;
    private readonly IFileService _fileService = fileService;
    private readonly ILogger _logger = logger;
    private readonly MasterDataInfoGrpc.MasterDataInfoGrpcClient _masterDataGrpcClient = masterDataGrpcClient;
    private readonly ErpInfoGrpc.ErpInfoGrpcClient _erpGrpcClient = erpGrpcClient;

    public async Task<Result<DeliveryPackingReportResponseDto>> GetReportDataAsync(DeliveryPackingReportFilterDto filter)
    {
        // 1. Phải chọn Dự án HOẶC Đơn bán hàng SO
        bool hasProject = filter.ProjectId.HasValue && filter.ProjectId.Value != Guid.Empty;
        bool hasSalesOrder = filter.SalesOrderId.HasValue && filter.SalesOrderId.Value != Guid.Empty;

        if (!hasProject && !hasSalesOrder)
        {
            return Result<DeliveryPackingReportResponseDto>.Failure("Vui lòng chọn Dự án hoặc Đơn bán hàng (SO) để xem báo cáo.");
        }

        // 2. Resolve ProjectInfo qua gRPC nếu có ProjectId
        var projMap = new Dictionary<string, ProjectSummary>(StringComparer.OrdinalIgnoreCase);
        if (hasProject)
        {
            try
            {
                var pResp = await _masterDataGrpcClient.GetProjectsByIdsAsync(new GetIdsRequest
                {
                    Ids = { filter.ProjectId.Value.ToString() }
                }).ResponseAsync;

                if (pResp?.Success == true)
                {
                    foreach (var p in pResp.Projects)
                    {
                        projMap[p.Id] = p;
                    }
                }
            }
            catch (Exception ex)
            {
                _logger.Warning(ex, "gRPC error resolving project for DeliveryPackingReport: {ProjectId}", filter.ProjectId);
            }
        }

        // 3. Lấy excluded WorkItem IDs
        var excludedIds = await GetExcludedWorkItemIdsAsync();

        // 4. Lấy FGR detail summaries từ ERP gRPC
        var fgrDetailSummaries = await FetchFgrDetailSummariesAsync(excludedIds);

        // 5. Chuẩn bị repositories
        var deliveryPackingQuery = _unitOfWork.GetRepository<FinishedGoodsDeliveryPacking>().Query();
        var sdDetailQuery = _unitOfWork.GetRepository<SiteDeliveryDetail>().Query();
        var fgpDetailQuery = _unitOfWork.GetRepository<FinishedGoodsPackingDetail>().Query();
        var salesOrderQuery = _unitOfWork.GetRepository<SalesOrder>().Query();
        var matPlDetailQuery = _unitOfWork.GetRepository<MaterialPackingListDetail>().Query();

        var reportData = await DeliveryPackingReportQueryBuilder.BuildReportDataAsync(
            deliveryPackingQuery,
            sdDetailQuery,
            fgpDetailQuery,
            fgrDetailSummaries,
            salesOrderQuery,
            matPlDetailQuery,
            filter,
            excludedIds,
            projMap);

        // 6. Enrich UnitOfMeasure cho các sub-items
        await EnrichUomAsync(reportData.Packages);

        // 7. Enrich Tên cụm / Bán thành phẩm cho các sub-items
        await EnrichPartNamesAsync(reportData.Packages);

        return Result<DeliveryPackingReportResponseDto>.Success(reportData);
    }

    private async Task<HashSet<Guid>> GetExcludedWorkItemIdsAsync()
    {
        try
        {
            var grpcResponse = await _masterDataGrpcClient.GetWorkItemIdsByStatusAsync(
                new GetWorkItemIdsByStatusRequest
                {
                    StatusEnums = { (int)EWorkItemStatus.Cancelled }
                });

            if (!grpcResponse.Success) return [];

            return [.. grpcResponse.WorkItemIds
                .Where(idStr => Guid.TryParse(idStr, out _))
                .Select(Guid.Parse)];
        }
        catch (Exception ex)
        {
            _logger.Warning(ex, "Không thể lấy danh sách WorkItem bị hủy qua gRPC");
            return [];
        }
    }

    private async Task<List<FgrDetailSummary>> FetchFgrDetailSummariesAsync(HashSet<Guid> excludedIds)
    {
        try
        {
            var grpcRequest = new GetFgrDetailSummariesRequest();
            grpcRequest.ExcludedReceiptIds.AddRange(excludedIds.Select(id => id.ToString()));
            var grpcResponse = await _erpGrpcClient.GetFinishedGoodsReceiptDetailSummariesAsync(grpcRequest);
            return [.. grpcResponse.Items];
        }
        catch (Exception ex)
        {
            _logger.Warning(ex, "Không thể lấy FGR detail summaries từ ERP");
            return [];
        }
    }

    private async Task EnrichUomAsync(List<DeliveryPackingReportPackageDto> packages)
    {
        var uomIds = packages
            .SelectMany(p => p.SubItems)
            .Where(s => s.UomId.HasValue && s.UomId.Value != Guid.Empty)
            .Select(s => s.UomId.Value.ToString())
            .Distinct()
            .ToList();

        if (uomIds.Count == 0) return;

        try
        {
            var uomRequest = new GetIdsRequest();
            uomRequest.Ids.AddRange(uomIds);
            var uomResponse = await _masterDataGrpcClient.GetUnitOfMeasuresByIdsAsync(uomRequest);
            if (uomResponse.Success)
            {
                var uomMap = uomResponse.Items.ToDictionary(x => x.Id, x => x.Name, StringComparer.OrdinalIgnoreCase);
                foreach (var pkg in packages)
                {
                    foreach (var item in pkg.SubItems)
                    {
                        if (item.UomId.HasValue && uomMap.TryGetValue(item.UomId.Value.ToString(), out var uomName))
                        {
                            item.UomName = uomName;
                        }
                    }
                }
            }
        }
        catch (Exception ex)
        {
            _logger.Warning(ex, "Lỗi lấy đơn vị tính từ MasterData gRPC");
        }
    }

    private async Task EnrichPartNamesAsync(List<DeliveryPackingReportPackageDto> packages)
    {
        var partIds = packages
            .SelectMany(p => p.SubItems)
            .Where(s => s.ItemType == "PART" && Guid.TryParse(s.Name, out _))
            .Select(s => s.Name)
            .Distinct()
            .ToList();

        if (partIds.Count == 0) return;

        try
        {
            var response = await _masterDataGrpcClient.GetAllSemiFinishedGoodsAsync(
                new Google.Protobuf.WellKnownTypes.Empty());
            if (response?.Success == true && response.Items.Count > 0)
            {
                var partMap = response.Items.ToDictionary(x => x.Id, x => x, StringComparer.OrdinalIgnoreCase);
                foreach (var pkg in packages)
                {
                    foreach (var item in pkg.SubItems)
                    {
                        if (item.ItemType == "PART" && partMap.TryGetValue(item.Name, out var part))
                        {
                            item.Name = part.Name;
                            if (string.IsNullOrWhiteSpace(item.Code))
                            {
                                item.Code = part.Code;
                            }
                        }
                    }
                }
            }
        }
        catch (Exception ex)
        {
            _logger.Warning(ex, "Lỗi lấy tên cụm SemiFinishedGood qua gRPC");
        }
    }
}

