using System;
using System.IO;
using System.Linq;
using System.Threading.Tasks;
using ClosedXML.Excel;
using Contracts.Domains;
using Infrastructure.Services;
using ServiceDesk.Data.Entities.PackingList;
using Shared.Dto.ServiceDesk.PackingList;
using Shared.Enums;

namespace ServiceDesk.Services.Implement.PackingList;

public partial class DeliveryPackingReportService
{
    public async Task<Result<string>> ExportReportAsync(DeliveryPackingReportFilterDto filter)
    {
        try
        {
            var dataResult = await GetReportDataAsync(filter);
            if (!dataResult.IsSuccess || dataResult.Data == null)
            {
                return Result<string>.Failure(dataResult.Message ?? "Không thể lấy dữ liệu báo cáo để xuất Excel.");
            }

            var packages = dataResult.Data.Packages;
            if (packages.Count == 0)
            {
                return Result<string>.Failure("Không có dữ liệu để xuất Excel.");
            }

            using var workbook = new XLWorkbook();
            var ws = workbook.Worksheets.Add("Delivery_Packing_Report");

            // --- 1. TIÊU ĐỀ BÁO CÁO ---
            ws.Cell(1, 1).Value = "BÁO CÁO PACKING GIAO HÀNG (DELIVERY PACKING REPORT)";
            ws.Cell(1, 1).Style.Font.Bold = true;
            ws.Cell(1, 1).Style.Font.FontSize = 14;
            ws.Range(1, 1, 1, 10).Merge();

            // --- 2. HEADER CÁC CỘT (Dòng 3) ---
            var headers = new string[]
            {
                "STT", "Mã Kiện Giao Hàng", "Nguồn (Dự án / SO)", "Thành Phẩm / Model",
                "Kích Thước Kiện (mm)", "Khối Lượng Kiện (kg)", "Tình Trạng Giao", "Phiếu Giao Hàng",
                "Loại Hàng", "Mã Nhận Dạng / TagNo / Mã NVL", "Tên Cụm / Tên Nguyên Vật Liệu",
                "Quy Cách / Mô Tả", "ĐVT", "Số Lượng", "Khối Lượng Con (kg)", "Kho Xuất", "Ghi Chú"
            };

            for (int i = 0; i < headers.Length; i++)
            {
                var cell = ws.Cell(3, i + 1);
                cell.Value = headers[i];
                cell.Style.Font.Bold = true;
                cell.Style.Font.FontColor = XLColor.White;
                cell.Style.Fill.BackgroundColor = XLColor.FromHtml("#1E3A8A"); // Navy blue
                cell.Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
                cell.Style.Alignment.Vertical = XLAlignmentVerticalValues.Center;
                cell.Style.Alignment.WrapText = true;
                cell.Style.Border.OutsideBorder = XLBorderStyleValues.Thin;
            }

            int rowIdx = 4;
            int pkgStt = 1;

            foreach (var pkg in packages)
            {
                // Dòng Kiện (Parent Package Row)
                int startPkgRow = rowIdx;
                ws.Cell(rowIdx, 1).Value = pkgStt++;
                ws.Cell(rowIdx, 2).Value = pkg.PackingCode;
                ws.Cell(rowIdx, 3).Value = pkg.SourceType == "PROJECT"
                    ? $"Dự án: {pkg.ProjectCode ?? pkg.ProjectName}"
                    : $"SO: {pkg.SalesOrderCode} ({pkg.CustomerName})";
                ws.Cell(rowIdx, 4).Value = $"{pkg.FinishedGoodCode} - {pkg.FinishedGoodName} {pkg.DesignModelCode}".Trim();
                ws.Cell(rowIdx, 5).Value = pkg.Dimensions ?? "-";
                ws.Cell(rowIdx, 6).Value = pkg.ActualTotalWeight;
                ws.Cell(rowIdx, 7).Value = pkg.SiteDeliveryStatus == EPackingReportStatus.Full ? "ĐÃ GIAO" : "CHƯA GIAO";
                ws.Cell(rowIdx, 8).Value = pkg.SiteDeliveryCode ?? "-";

                // Tô màu highlight nhẹ cho dòng kiện
                var pkgRange = ws.Range(rowIdx, 1, rowIdx, headers.Length);
                pkgRange.Style.Font.Bold = true;
                pkgRange.Style.Fill.BackgroundColor = XLColor.FromHtml("#E0E7FF"); // Light Indigo
                pkgRange.Style.Border.OutsideBorder = XLBorderStyleValues.Thin;
                rowIdx++;

                // Các dòng con (Sub-items: Cụm hoặc NVL bên trong kiện)
                if (pkg.SubItems != null && pkg.SubItems.Count > 0)
                {
                    int subStt = 1;
                    foreach (var item in pkg.SubItems)
                    {
                        ws.Cell(rowIdx, 1).Value = $"   {subStt++}";
                        ws.Cell(rowIdx, 9).Value = item.ItemType == "PART" ? "Cụm chi tiết" : "Nguyên vật liệu";
                        ws.Cell(rowIdx, 10).Value = item.Code ?? "-";
                        ws.Cell(rowIdx, 11).Value = item.Name ?? "-";
                        ws.Cell(rowIdx, 12).Value = item.Specification ?? "-";
                        ws.Cell(rowIdx, 13).Value = item.UomName ?? "-";
                        ws.Cell(rowIdx, 14).Value = item.Quantity;
                        ws.Cell(rowIdx, 15).Value = item.Weight;
                        ws.Cell(rowIdx, 16).Value = item.FromWarehouseName ?? "-";
                        ws.Cell(rowIdx, 17).Value = item.Remark ?? "-";

                        var subRange = ws.Range(rowIdx, 1, rowIdx, headers.Length);
                        subRange.Style.Border.OutsideBorder = XLBorderStyleValues.Hair;
                        rowIdx++;
                    }
                }
            }

            ws.Columns().AdjustToContents();

            // Save to stream & upload
            await using var ms = new MemoryStream();
            workbook.SaveAs(ms);
            var excelBytes = ms.ToArray();

            if (excelBytes.Length == 0)
                return Result<string>.Failure("Không thể tạo dữ liệu file export");

            var fileName = $"BaoCao_Packing_GiaoHang_{DateTime.Now:yyyyMMdd_HHmmss}.xlsx";
            var formFile = new FormFileHelper(new MemoryStream(excelBytes), excelBytes.Length, "file", fileName)
            {
                ContentType = "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"
            };

            string ip = _config["FtpSettings:Ip"] ?? string.Empty;
            string environment = _config["FtpSettings:Environment"] ?? string.Empty;
            string ftpUsername = _config["FtpSettings:Username"] ?? string.Empty;
            string ftpPassword = _config["FtpSettings:Password"] ?? string.Empty;
            string folderName = $"{typeof(FinishedGoodsDeliveryPacking).Name}/Exports";
            EUploadType uploadType = Enum.TryParse<EUploadType>(_config["FtpSettings:UploadType"], out var type)
                ? type : EUploadType.Sftp;

            var uploadResult = _fileService.UploadFile(formFile, ip, ftpUsername, ftpPassword,
                environment, folderName, uploadType, fileName);

            if (uploadResult != null && uploadResult.TryGetValue("filePath", out var exportFilePath) && exportFilePath != null)
                return Result<string>.Success(exportFilePath.ToString());

            return Result<string>.Failure("Không thể lưu trữ file export trên server");
        }
        catch (Exception ex)
        {
            _logger.Error(ex, "Lỗi khi export DeliveryPackingReport Excel");
            return Result<string>.Failure("Lỗi hệ thống khi tạo file Excel báo cáo: " + ex.Message);
        }
    }
}

