using System;
using System.Collections.Generic;
using Shared.Domain.Entities;
using Shared.Enums;

namespace Shared.Dto.ServiceDesk.PackingList;

/// <summary>
/// Bộ lọc báo cáo đóng kiện giao hàng (hỗ trợ cả 2 nguồn: Dự án HOẶC Đơn bán hàng SO).
/// </summary>
public record DeliveryPackingReportFilterRequest : AutoFilterPaging
{
    /// <summary>Lọc theo Dự án (nếu là giao hàng theo dự án/chế tạo).</summary>
    public Guid? ProjectId { get; set; }
    public string ProjectCodeSnapshot { get; set; }
    public string ProjectNameSnapshot { get; set; }

    /// <summary>Lọc theo Đơn bán hàng (SO) - trường hợp bán thẳng NVL/hàng hóa không qua dự án.</summary>
    public Guid? SalesOrderId { get; set; }
    public string SalesOrderCodeSnapshot { get; set; }
    public string SalesOrderNameSnapshot { get; set; }

    /// <summary>Lọc theo Lệnh đóng gói giao hàng.</summary>
    public Guid? DeliveryPackagingId { get; set; }

    /// <summary>Lọc theo ID Mã kiện (tra cứu ID từ DB/MasterData, tuyệt đối không gán cứng).</summary>
    public Guid? PackingCodesId { get; set; }

    /// <summary>Lọc theo ID Thành phẩm.</summary>
    public Guid? FinishedGoodId { get; set; }

    /// <summary>Lọc theo ID Model hiệu suất (tra cứu ID).</summary>
    public Guid? ModelId { get; set; }

    /// <summary>Lọc theo ID Model thiết kế (tra cứu ID từ DB/MasterData, tuyệt đối không gán cứng).</summary>
    public Guid? DesignModelId { get; set; }

    /// <summary>Lọc theo Tình trạng giao hàng công trình/khách hàng.</summary>
    public EPackingReportStatus? SiteDeliveryStatus { get; set; }

    /// <summary>Khoảng ngày đóng gói.</summary>
    public DateTime? FromDate { get; set; }
    public DateTime? ToDate { get; set; }

    /// <summary>Từ khóa tìm kiếm nhanh (mã kiện, TagNo, mã NVL, mô tả...).</summary>
    public string? SearchText { get; set; }
}

/// <summary>
/// Cấp 1 (Dòng cha): Quản lý theo từng KIỆN GIAO HÀNG / KIỆN XUẤT KHO.
/// </summary>
public record DeliveryPackingReportPackageDto
{
    /// <summary>Số thứ tự kiện</summary>
    public int STT { get; set; }

    /// <summary>ID kiện giao hàng (FinishedGoodsDeliveryPackingId)</summary>
    public Guid Id { get; set; }

    /// <summary>Mã phiếu kiện</summary>
    public string Code { get; set; }

    /// <summary>ID mã kiện trong bảng PackingCodes</summary>
    public Guid? PackingCodesId { get; set; }

    /// <summary>Mã kiện hiển thị (VD: PK-001)</summary>
    public string PackingCode { get; set; }

    /// <summary>Kích thước kiện (D x R x C mm)</summary>
    public string Dimensions { get; set; }

    /// <summary>Khối lượng thực tế của cả kiện (kg)</summary>
    public decimal ActualTotalWeight { get; set; }

    /// <summary>Nguồn hàng: "Project" (Dự án chế tạo) hoặc "SalesOrder" (Bán thẳng SO)</summary>
    public string SourceType { get; set; } = "Project";

    // ─── Thông tin Dự án ─────────────────────────────────────────────
    public Guid? ProjectId { get; set; }
    public string? ProjectCode { get; set; }
    public string? ProjectName { get; set; }

    // ─── Thông tin Đơn bán hàng SO (nếu bán thẳng) ─────────────────────
    public Guid? SalesOrderId { get; set; }
    public string? SalesOrderCode { get; set; }
    public string? CustomerName { get; set; }

    // ─── Chứng từ liên kết ───────────────────────────────────────────
    public Guid? DeliveryPackagingId { get; set; }
    public string? DeliveryPackagingCode { get; set; }

    public Guid? SiteDeliveryId { get; set; }
    public string? SiteDeliveryCode { get; set; }

    /// <summary>Tình trạng giao hàng (Empty: Chưa giao, Partial: Đang giao, Full: Đã giao)</summary>
    public EPackingReportStatus SiteDeliveryStatus { get; set; } = EPackingReportStatus.Empty;

    /// <summary>Tổng số lượng mặt hàng / cụm bên trong kiện</summary>
    public int ItemCount { get; set; }

    /// <summary>Tổng số lượng đơn vị bên trong kiện</summary>
    public decimal TotalQuantity { get; set; }

    /// <summary>Ngày đóng kiện</summary>
    public DateTime? CreatedDate { get; set; }

    /// <summary>Người tạo / đóng kiện</summary>
    public string? CreatedByUser { get; set; }

    /// <summary>Ghi chú</summary>
    public string? Remark { get; set; }

    /// <summary>
    /// Cấp 2: Bảng lồng danh sách các CỤM CHI TIẾT hoặc NGUYÊN VẬT LIỆU bên trong kiện này.
    /// </summary>
    public List<DeliveryPackingReportItemDto> Items { get; set; } = [];
}

/// <summary>
/// Cấp 2 (Dòng con): Chi tiết CỤM (hàng dự án) HOẶC NGUYÊN VẬT LIỆU (bán thẳng SO) bên trong kiện.
/// </summary>
public record DeliveryPackingReportItemDto
{
