using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;
using Microsoft.EntityFrameworkCore;
using ServiceDesk.Data.Entities.PackingList;
using ServiceDesk.Data.Entities.SalesOrders;
using Shared.Dto.ServiceDesk.PackingList;
using Shared.Enums;
using Shared.Helpers;

namespace ServiceDesk.Services.Implement.PackingList;

/// <summary>
/// Query builder tối ưu hoá truy vấn báo cáo đóng kiện giao hàng (Delivery Packing Report).
/// Tuân thủ chuẩn không gán cứng chuỗi (DesignModelId, PackingCodesId tra cứu theo ID - Guid).
/// Tránh memory burst bằng AsNoTracking, ID Chunking và O(1) in-memory maps theo pattern PackingListReportQueryBuilder.
/// </summary>
public static class DeliveryPackingReportQueryBuilder
{
    public static async Task<List<DeliveryPackingReportPackageDto>> BuildReportDataAsync(
        IQueryable<FinishedGoodsDeliveryPacking> deliveryPackingQuery,
        IQueryable<SiteDeliveryDetail> siteDeliveryDetailQuery,
        IQueryable<FinishedGoodsPacking> fgPackingQuery,
        IQueryable<MechanicalPackingList> mechListQuery,
        IQueryable<PackingCodes> packingCodesQuery,
        IQueryable<SalesOrderDetail> soDetailQuery,
        HashSet<Guid> excludedIds,
        DeliveryPackingReportFilterRequest filter,
        Dictionary<string, CogainSolution.Grpc.MasterDataInfo.ProjectSummary> projMap,
        Dictionary<Guid, string> salesOrderCodeMap)
    {
        var excludedIdArray = excludedIds.ToArray();

        // 1. Áp dụng bộ lọc cơ sở trên Queryable trước khi truy vấn DB
        var baseQuery = deliveryPackingQuery.AsNoTracking();

        if (filter.ProjectId.HasValue && filter.ProjectId.Value != Guid.Empty)
        {
            baseQuery = baseQuery.Where(p => p.ProjectId == filter.ProjectId.Value ||
                                             (p.DeliveryPackaging != null && p.DeliveryPackaging.ProjectId == filter.ProjectId.Value));
        }

        if (filter.SalesOrderId.HasValue && filter.SalesOrderId.Value != Guid.Empty)
        {
            baseQuery = baseQuery.Where(p => p.DeliveryPackaging != null && p.DeliveryPackaging.SalesOrderId == filter.SalesOrderId.Value);
        }

        if (filter.DeliveryPackagingId.HasValue && filter.DeliveryPackagingId.Value != Guid.Empty)
        {
            baseQuery = baseQuery.Where(p => p.DeliveryPackagingId == filter.DeliveryPackagingId.Value);
        }

        // Lọc theo ID mã kiện (tra cứu mã kiện qua ID từ DB, tuyệt đối không gán cứng)
        string? targetPackingCode = null;
        if (filter.PackingCodesId.HasValue && filter.PackingCodesId.Value != Guid.Empty)
        {
            targetPackingCode = await packingCodesQuery.AsNoTracking()
                .Where(x => x.Id == filter.PackingCodesId.Value)
                .Select(x => x.PackingCode)
                .FirstOrDefaultAsync();

            baseQuery = baseQuery.Where(p =>
                p.PackingCodesId == filter.PackingCodesId.Value ||
                (targetPackingCode != null && p.Details.Any(d => d.PackingCode == targetPackingCode)));
        }

        if (filter.FromDate.HasValue)
        {
            baseQuery = baseQuery.Where(p => p.CreatedDate >= filter.FromDate.Value);
        }

        if (filter.ToDate.HasValue)
        {
            var endOfDay = filter.ToDate.Value.Date.AddDays(1).AddTicks(-1);
            baseQuery = baseQuery.Where(p => p.CreatedDate <= endOfDay);
        }

        var packages = await baseQuery
            .Include(p => p.PackingCodes)
            .Include(p => p.DeliveryPackaging)
            .Include(p => p.Details)
            .OrderByDescending(p => p.CreatedDate)
            .ToListAsync();

        if (packages.Count == 0) return [];

        var packageIds = packages.Select(p => p.Id).ToArray();

        // 2. Tra cứu trạng thái giao hàng công trình (SiteDeliveryDetail) cho các kiện này
        var deliveredSiteDetails = await siteDeliveryDetailQuery
            .AsNoTracking()
            .Include(sd => sd.SiteDelivery)
            .Where(sd => packageIds.Contains(sd.FinishedGoodsDeliveryPackingId) &&
                         !excludedIdArray.Contains(sd.SiteDeliveryId))
            .Select(sd => new
            {
                sd.FinishedGoodsDeliveryPackingId,
                sd.SiteDeliveryId,
                SiteDeliveryCode = sd.SiteDelivery != null ? sd.SiteDelivery.Code : sd.SiteDeliveryCodeSnapshot
            })
            .ToListAsync();

        var siteDeliveryByPackageId = deliveredSiteDetails
            .GroupBy(x => x.FinishedGoodsDeliveryPackingId)
            .ToDictionary(g => g.Key, g => g.First());

        // 3. Gom các mã kiện kho (packing codes) từ Details để lấy thông tin các Cụm chi tiết con bên trong
        var childPackingCodes = packages
            .SelectMany(p => p.Details.Select(d => d.PackingCode))
            .Where(code => !string.IsNullOrWhiteSpace(code))
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .ToList();

        // Query các kiện thành phẩm tương ứng kèm chi tiết cơ khí (TagNo, Bán thành phẩm)
        var fgPackings = childPackingCodes.Count == 0
            ? []
            : await fgPackingQuery
                .AsNoTracking()
                .Include(p => p.PackingCodes)
                .Include(p => p.MechanicalPackingList)
                .Include(p => p.Details)
                .Where(p => (p.PackingCodes != null && childPackingCodes.Contains(p.PackingCodes.PackingCode)) ||
                            childPackingCodes.Contains(p.Code))
                .ToListAsync();

        // O(1) map từ PackingCode (hoặc Code) sang FinishedGoodsPacking
        var fgPackingByCodeMap = new Dictionary<string, FinishedGoodsPacking>(StringComparer.OrdinalIgnoreCase);
        foreach (var fgp in fgPackings)
        {
            if (fgp.PackingCodes != null && !string.IsNullOrWhiteSpace(fgp.PackingCodes.PackingCode))
                fgPackingByCodeMap.TryAdd(fgp.PackingCodes.PackingCode, fgp);
            if (!string.IsNullOrWhiteSpace(fgp.Code))
                fgPackingByCodeMap.TryAdd(fgp.Code, fgp);
        }

        // 4. Tra cứu danh sách MechanicalPackingList để map DesignModelId và ModelId nếu chưa có
        var mechCodes = packages
            .SelectMany(p => p.Details.Select(d => d.MechanicalPackingListCode))
            .Where(c => !string.IsNullOrWhiteSpace(c))
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .ToList();

        var mechLists = mechCodes.Count == 0
            ? []
            : await mechListQuery.AsNoTracking()
                .Where(m => mechCodes.Contains(m.Code))
                .Select(m => new
                {
                    m.Code,
                    m.Id,
                    m.FinishedGoodId,
                    m.ModelId,
                    m.DesignModelId
                })
                .ToListAsync();

        var mechMap = mechLists.ToDictionary(m => m.Code, m => m, StringComparer.OrdinalIgnoreCase);

        // 5. Nếu là trường hợp đơn bán hàng SO (NVL), chuẩn bị map chi tiết SO nếu cần
        var salesOrderIds = packages
            .Where(p => p.DeliveryPackaging?.SalesOrderId != null)
            .Select(p => p.DeliveryPackaging!.SalesOrderId!.Value)
            .Distinct()
            .ToArray();

        var soDetailsByOrderId = salesOrderIds.Length == 0
            ? new Dictionary<Guid, List<SalesOrderDetail>>()
            : (await soDetailQuery
                .AsNoTracking()
                .Where(d => salesOrderIds.Contains(d.SalesOrderId))
                .ToListAsync())
                .GroupBy(d => d.SalesOrderId)
                .ToDictionary(g => g.Key, g => g.ToList());

        // 6. Build DTO phân cấp: Dòng cha (Kiện) -> Bảng lồng (Cụm chi tiết TagNo hoặc NVL)
        var resultRows = new List<DeliveryPackingReportPackageDto>(packages.Count);
        int stt = 1;

        foreach (var pkg in packages)
        {
            var isSiteDelivered = siteDeliveryByPackageId.TryGetValue(pkg.Id, out var siteDeliveryInfo);
            var deliveryStatus = isSiteDelivered ? EPackingReportStatus.Full : EPackingReportStatus.Empty;

            var effectiveProjectId = pkg.ProjectId ?? pkg.DeliveryPackaging?.ProjectId;
            var effectiveSalesOrderId = pkg.DeliveryPackaging?.SalesOrderId;

            var projectSummary = effectiveProjectId.HasValue
                ? projMap.GetValueOrDefault(effectiveProjectId.Value.ToString())
                : null;

            var soCode = effectiveSalesOrderId.HasValue
                ? salesOrderCodeMap.GetValueOrDefault(effectiveSalesOrderId.Value) ?? pkg.DeliveryPackaging?.SalesOrderCodeSnapshot
                : null;

            var isSalesOrderSource = effectiveSalesOrderId.HasValue && !effectiveProjectId.HasValue;

            var packageDto = new DeliveryPackingReportPackageDto
            {
                STT = stt++,
                Id = pkg.Id,
                Code = pkg.Code,
                PackingCodesId = pkg.PackingCodesId,
                PackingCode = pkg.PackingCodes?.PackingCode ?? pkg.PackingCodes?.Code ?? pkg.Code,
                Dimensions = pkg.Dimensions,
                ActualTotalWeight = pkg.ActualTotalWeight,
                SourceType = isSalesOrderSource ? "SalesOrder" : "Project",
                ProjectId = effectiveProjectId,
                ProjectCode = projectSummary?.Code ?? pkg.ProjectCodeSnapshot,
                ProjectName = projectSummary?.Name ?? pkg.ProjectNameSnapshot,
                SalesOrderId = effectiveSalesOrderId,
                SalesOrderCode = soCode,
                CustomerName = pkg.DeliveryPackaging?.SalesOrderNameSnapshot,
                DeliveryPackagingId = pkg.DeliveryPackagingId,
                DeliveryPackagingCode = pkg.DeliveryPackaging?.Code ?? pkg.DeliveryPackagingCodeSnapshot,
                SiteDeliveryId = isSiteDelivered ? siteDeliveryInfo?.SiteDeliveryId : null,
                SiteDeliveryCode = isSiteDelivered ? siteDeliveryInfo?.SiteDeliveryCode : null,
                SiteDeliveryStatus = deliveryStatus,
                CreatedDate = pkg.CreatedDate.ToVietnamDate(),
                CreatedByUser = pkg.CreatedByUser,
                Items = []
            };

            // Build danh sách Cụm / Chi tiết con (Items) bên trong kiện
            int itemLineNum = 1;
            decimal totalPackageQty = 0;

            foreach (var detail in pkg.Details.OrderBy(d => d.LineNum))
            {
                var packingCodeKey = detail.PackingCode;
                var hasFgPacking = !string.IsNullOrWhiteSpace(packingCodeKey) &&
                                   fgPackingByCodeMap.TryGetValue(packingCodeKey, out var matchedFgPacking);

                mechMap.TryGetValue(detail.MechanicalPackingListCode ?? string.Empty, out var matchedMech);

                if (hasFgPacking && matchedFgPacking != null && matchedFgPacking.Details != null && matchedFgPacking.Details.Count > 0)
                {
                    // Trường hợp 1 (Hàng Dự án / Thành phẩm chế tạo):
                    // Bóc tách từng CỤM CHI TIẾT (TagNo) từ FinishedGoodsPackingDetail
                    foreach (var part in matchedFgPacking.Details.OrderBy(p => p.LineNum))
                    {
                        var resolvedDesignModelId = matchedFgPacking.DesignModelId ??
                                                   matchedFgPacking.MechanicalPackingList?.DesignModelId ??
                                                   matchedMech?.DesignModelId;

                        var resolvedModelId = matchedFgPacking.ModelId ??
                                             matchedFgPacking.MechanicalPackingList?.ModelId ??
                                             matchedMech?.ModelId;

                        var resolvedFgId = matchedFgPacking.FinishedGoodId ??
                                          matchedFgPacking.MechanicalPackingList?.FinishedGoodId ??
                                          matchedMech?.FinishedGoodId;

                        packageDto.Items.Add(new DeliveryPackingReportItemDto
                        {
                            Id = part.Id,
                            LineNum = itemLineNum++,
                            ItemKind = "FinishedGoodPart",
                            Code = part.TagNo,
                            Name = part.SemiFinishedGoodNameSnapshot ?? part.ProductDescription ?? "Cụm chi tiết",
                            SemiFinishedGoodId = part.SemiFinishedGoodId != Guid.Empty ? part.SemiFinishedGoodId : null,
                            Description = part.ProductDescription,
                            FinishedGoodId = resolvedFgId,
                            FinishedGoodCode = matchedFgPacking.FinishedGoodCodeSnapshot ?? detail.FinishedGoodsCode,
                            FinishedGoodName = matchedFgPacking.FinishedGoodNameSnapshot ?? detail.FinishedGoodsName,
                            ModelId = resolvedModelId,
                            ModelCode = matchedFgPacking.ModelCodeSnapshot,
                            ModelName = matchedFgPacking.ModelNameSnapshot,
                            // DesignModelId tra cứu ID không gán cứng
                            DesignModelId = resolvedDesignModelId,
                            DesignModelCode = matchedFgPacking.DesignModelCodeSnapshot ?? detail.DesignModelCode,
                            DesignModelName = matchedFgPacking.DesignModelNameSnapshot ?? detail.DesignModelName,
                            MechanicalPackingListCode = matchedFgPacking.MechanicalPackingList?.Code ?? detail.MechanicalPackingListCode,
                            UomId = part.UOMId,
                            UomName = part.UOMNameSnapshot,
                            DimensionL = part.DimensionL,
                            DimensionW = part.DimensionW,
                            DimensionH = part.DimensionH,
                            Quantity = part.ActualQuantity,
                            Weight = part.ActualWeight,
                            Remark = part.Remark
                        });
                        totalPackageQty += part.ActualQuantity;
                    }
                }
                else
                {
                    // Trường hợp 2 (Bán thẳng SO hoặc Hàng nguyên kiện không qua chế tạo cơ khí):
                    // Lấy thông tin từ chính dòng detail của DeliveryPacking
                    var resolvedDesignModelId = matchedMech?.DesignModelId;
                    var resolvedModelId = matchedMech?.ModelId;
                    var resolvedFgId = matchedMech?.FinishedGoodId;

                    packageDto.Items.Add(new DeliveryPackingReportItemDto
                    {
                        Id = detail.Id,
                        LineNum = itemLineNum++,
                        ItemKind = isSalesOrderSource ? "Material" : "FinishedGoodPart",
                        Code = detail.PackingCode ?? detail.FinishedGoodsCode ?? "SP",
                        Name = detail.FinishedGoodsName ?? "Nguyên vật liệu / Sản phẩm giao",
                        Description = detail.Dimensions,
                        FinishedGoodId = resolvedFgId,
                        FinishedGoodCode = detail.FinishedGoodsCode,
                        FinishedGoodName = detail.FinishedGoodsName,
                        ModelId = resolvedModelId,
                        ModelCode = null,
                        ModelName = null,
                        DesignModelId = resolvedDesignModelId,
                        DesignModelCode = detail.DesignModelCode,
                        DesignModelName = detail.DesignModelName,
                        MechanicalPackingListCode = detail.MechanicalPackingListCode,
                        UomId = null,
                        UomName = "Kiện/Bộ",
                        Quantity = detail.ActualQuantity,
                        Weight = detail.ActualWeight,
                        Remark = detail.Remark
                    });
                    totalPackageQty += detail.ActualQuantity;
                }
            }

            packageDto.ItemCount = packageDto.Items.Count;
            packageDto.TotalQuantity = totalPackageQty;

            resultRows.Add(packageDto);
        }

        // 7. Áp dụng bộ lọc in-memory nghiêm ngặt theo ID cho các điều kiện chi tiết
        var filteredRows = resultRows;

        if (filter.FinishedGoodId.HasValue && filter.FinishedGoodId.Value != Guid.Empty)
        {
            filteredRows = filteredRows
                .Where(r => r.Items.Any(i => i.FinishedGoodId == filter.FinishedGoodId.Value))
                .ToList();
        }

        if (filter.ModelId.HasValue && filter.ModelId.Value != Guid.Empty)
        {
            filteredRows = filteredRows
                .Where(r => r.Items.Any(i => i.ModelId == filter.ModelId.Value))
                .ToList();
        }

        // Lọc theo DesignModelId (tra cứu Guid, KHÔNG gán cứng chuỗi)
        if (filter.DesignModelId.HasValue && filter.DesignModelId.Value != Guid.Empty)
        {
            filteredRows = filteredRows
                .Where(r => r.Items.Any(i => i.DesignModelId == filter.DesignModelId.Value))
                .ToList();
        }

        if (filter.SiteDeliveryStatus.HasValue)
        {
            filteredRows = filteredRows
                .Where(r => r.SiteDeliveryStatus == filter.SiteDeliveryStatus.Value)
                .ToList();
        }

        if (!string.IsNullOrWhiteSpace(filter.SearchText))
        {
            var term = filter.SearchText.Trim().ToLowerInvariant();
            filteredRows = filteredRows.Where(r =>
                (r.PackingCode != null && r.PackingCode.ToLowerInvariant().Contains(term)) ||
                (r.Code != null && r.Code.ToLowerInvariant().Contains(term)) ||
                (r.ProjectName != null && r.ProjectName.ToLowerInvariant().Contains(term)) ||
                (r.SalesOrderCode != null && r.SalesOrderCode.ToLowerInvariant().Contains(term)) ||
                r.Items.Any(i =>
                    (i.Code != null && i.Code.ToLowerInvariant().Contains(term)) ||
                    (i.Name != null && i.Name.ToLowerInvariant().Contains(term)) ||
                    (i.Description != null && i.Description.ToLowerInvariant().Contains(term)))
            ).ToList();
        }

        return filteredRows;
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;
using Microsoft.EntityFrameworkCore;
using ServiceDesk.Data.Entities.PackingList;
using ServiceDesk.Data.Entities.SalesOrders;
using Shared.Dto.ServiceDesk.PackingList;
using Shared.Enums;
using Shared.Helpers;

namespace ServiceDesk.Services.Implement.PackingList;

/// <summary>
/// Query builder tối ưu hoá truy vấn báo cáo đóng kiện giao hàng (Delivery Packing Report).
/// Tuân thủ chuẩn không gán cứng chuỗi (DesignModelId, PackingCodesId tra cứu theo ID - Guid).
/// Tránh memory burst bằng AsNoTracking, ID Chunking và O(1) in-memory maps theo pattern PackingListReportQueryBuilder.
/// </summary>
public static class DeliveryPackingReportQueryBuilder
{
    public static async Task<List<DeliveryPackingReportPackageDto>> BuildReportDataAsync(
        IQueryable<FinishedGoodsDeliveryPacking> deliveryPackingQuery,
        IQueryable<SiteDeliveryDetail> siteDeliveryDetailQuery,
        IQueryable<FinishedGoodsPacking> fgPackingQuery,
        IQueryable<MechanicalPackingList> mechListQuery,
        IQueryable<PackingCodes> packingCodesQuery,
        IQueryable<SalesOrderDetail> soDetailQuery,
        HashSet<Guid> excludedIds,
        DeliveryPackingReportFilterRequest filter,
        Dictionary<string, CogainSolution.Grpc.MasterDataInfo.ProjectSummary> projMap,
        Dictionary<Guid, string> salesOrderCodeMap)
    {
        var excludedIdArray = excludedIds.ToArray();

        // 1. Áp dụng bộ lọc cơ sở trên Queryable trước khi truy vấn DB
        var baseQuery = deliveryPackingQuery.AsNoTracking();

        if (filter.ProjectId.HasValue && filter.ProjectId.Value != Guid.Empty)
        {
            baseQuery = baseQuery.Where(p => p.ProjectId == filter.ProjectId.Value ||
                                             (p.DeliveryPackaging != null && p.DeliveryPackaging.ProjectId == filter.ProjectId.Value));
        }

        if (filter.SalesOrderId.HasValue && filter.SalesOrderId.Value != Guid.Empty)
        {
            baseQuery = baseQuery.Where(p => p.DeliveryPackaging != null && p.DeliveryPackaging.SalesOrderId == filter.SalesOrderId.Value);
        }

        if (filter.DeliveryPackagingId.HasValue && filter.DeliveryPackagingId.Value != Guid.Empty)
        {
            baseQuery = baseQuery.Where(p => p.DeliveryPackagingId == filter.DeliveryPackagingId.Value);
        }

        // Lọc theo ID mã kiện (tra cứu mã kiện qua ID từ DB, tuyệt đối không gán cứng)
        string? targetPackingCode = null;
        if (filter.PackingCodesId.HasValue && filter.PackingCodesId.Value != Guid.Empty)
        {
            targetPackingCode = await packingCodesQuery.AsNoTracking()
                .Where(x => x.Id == filter.PackingCodesId.Value)
                .Select(x => x.PackingCode)
                .FirstOrDefaultAsync();

            baseQuery = baseQuery.Where(p =>
                p.PackingCodesId == filter.PackingCodesId.Value ||
                (targetPackingCode != null && p.Details.Any(d => d.PackingCode == targetPackingCode)));
        }

        if (filter.FromDate.HasValue)
        {
            baseQuery = baseQuery.Where(p => p.CreatedDate >= filter.FromDate.Value);
        }

        if (filter.ToDate.HasValue)
        {
            var endOfDay = filter.ToDate.Value.Date.AddDays(1).AddTicks(-1);
            baseQuery = baseQuery.Where(p => p.CreatedDate <= endOfDay);
        }

        var packages = await baseQuery
            .Include(p => p.PackingCodes)
            .Include(p => p.DeliveryPackaging)
            .Include(p => p.Details)
            .OrderByDescending(p => p.CreatedDate)
            .ToListAsync();

        if (packages.Count == 0) return [];

        var packageIds = packages.Select(p => p.Id).ToArray();

        // 2. Tra cứu trạng thái giao hàng công trình (SiteDeliveryDetail) cho các kiện này
        var deliveredSiteDetails = await siteDeliveryDetailQuery
            .AsNoTracking()
            .Include(sd => sd.SiteDelivery)
            .Where(sd => packageIds.Contains(sd.FinishedGoodsDeliveryPackingId) &&
                         !excludedIdArray.Contains(sd.SiteDeliveryId))
            .Select(sd => new
            {
                sd.FinishedGoodsDeliveryPackingId,
                sd.SiteDeliveryId,
                SiteDeliveryCode = sd.SiteDelivery != null ? sd.SiteDelivery.Code : sd.SiteDeliveryCodeSnapshot
            })
            .ToListAsync();

        var siteDeliveryByPackageId = deliveredSiteDetails
            .GroupBy(x => x.FinishedGoodsDeliveryPackingId)
            .ToDictionary(g => g.Key, g => g.First());

        // 3. Gom các mã kiện kho (packing codes) từ Details để lấy thông tin các Cụm chi tiết con bên trong
        var childPackingCodes = packages
            .SelectMany(p => p.Details.Select(d => d.PackingCode))
            .Where(code => !string.IsNullOrWhiteSpace(code))
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .ToList();

        // Query các kiện thành phẩm tương ứng kèm chi tiết cơ khí (TagNo, Bán thành phẩm)
        var fgPackings = childPackingCodes.Count == 0
            ? []
            : await fgPackingQuery
                .AsNoTracking()
                .Include(p => p.PackingCodes)
                .Include(p => p.MechanicalPackingList)
                .Include(p => p.Details)
                .Where(p => (p.PackingCodes != null && childPackingCodes.Contains(p.PackingCodes.PackingCode)) ||
                            childPackingCodes.Contains(p.Code))
                .ToListAsync();

        // O(1) map từ PackingCode (hoặc Code) sang FinishedGoodsPacking
        var fgPackingByCodeMap = new Dictionary<string, FinishedGoodsPacking>(StringComparer.OrdinalIgnoreCase);
        foreach (var fgp in fgPackings)
        {
            if (fgp.PackingCodes != null && !string.IsNullOrWhiteSpace(fgp.PackingCodes.PackingCode))
                fgPackingByCodeMap.TryAdd(fgp.PackingCodes.PackingCode, fgp);
            if (!string.IsNullOrWhiteSpace(fgp.Code))
                fgPackingByCodeMap.TryAdd(fgp.Code, fgp);
        }

        // 4. Tra cứu danh sách MechanicalPackingList để map DesignModelId và ModelId nếu chưa có
        var mechCodes = packages
            .SelectMany(p => p.Details.Select(d => d.MechanicalPackingListCode))
            .Where(c => !string.IsNullOrWhiteSpace(c))
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .ToList();

        var mechLists = mechCodes.Count == 0
            ? []
            : await mechListQuery.AsNoTracking()
                .Where(m => mechCodes.Contains(m.Code))
                .Select(m => new
                {
                    m.Code,
                    m.Id,
                    m.FinishedGoodId,
                    m.ModelId,
                    m.DesignModelId
                })
                .ToListAsync();

        var mechMap = mechLists.ToDictionary(m => m.Code, m => m, StringComparer.OrdinalIgnoreCase);

        // 5. Nếu là trường hợp đơn bán hàng SO (NVL), chuẩn bị map chi tiết SO nếu cần
        var salesOrderIds = packages
            .Where(p => p.DeliveryPackaging?.SalesOrderId != null)
            .Select(p => p.DeliveryPackaging!.SalesOrderId!.Value)
            .Distinct()
            .ToArray();

        var soDetailsByOrderId = salesOrderIds.Length == 0
            ? new Dictionary<Guid, List<SalesOrderDetail>>()
            : (await soDetailQuery
                .AsNoTracking()
                .Where(d => salesOrderIds.Contains(d.SalesOrderId))
                .ToListAsync())
                .GroupBy(d => d.SalesOrderId)
                .ToDictionary(g => g.Key, g => g.ToList());

        // 6. Build DTO phân cấp: Dòng cha (Kiện) -> Bảng lồng (Cụm chi tiết TagNo hoặc NVL)
        var resultRows = new List<DeliveryPackingReportPackageDto>(packages.Count);
        int stt = 1;

        foreach (var pkg in packages)
        {
            var isSiteDelivered = siteDeliveryByPackageId.TryGetValue(pkg.Id, out var siteDeliveryInfo);
            var deliveryStatus = isSiteDelivered ? EPackingReportStatus.Full : EPackingReportStatus.Empty;

            var effectiveProjectId = pkg.ProjectId ?? pkg.DeliveryPackaging?.ProjectId;
            var effectiveSalesOrderId = pkg.DeliveryPackaging?.SalesOrderId;

            var projectSummary = effectiveProjectId.HasValue
                ? projMap.GetValueOrDefault(effectiveProjectId.Value.ToString())
                : null;

            var soCode = effectiveSalesOrderId.HasValue
                ? salesOrderCodeMap.GetValueOrDefault(effectiveSalesOrderId.Value) ?? pkg.DeliveryPackaging?.SalesOrderCodeSnapshot
                : null;

            var isSalesOrderSource = effectiveSalesOrderId.HasValue && !effectiveProjectId.HasValue;

            var packageDto = new DeliveryPackingReportPackageDto
            {
                STT = stt++,
                Id = pkg.Id,
                Code = pkg.Code,
                PackingCodesId = pkg.PackingCodesId,
                PackingCode = pkg.PackingCodes?.PackingCode ?? pkg.PackingCodes?.Code ?? pkg.Code,
                Dimensions = pkg.Dimensions,
                ActualTotalWeight = pkg.ActualTotalWeight,
                SourceType = isSalesOrderSource ? "SalesOrder" : "Project",
                ProjectId = effectiveProjectId,
                ProjectCode = projectSummary?.Code ?? pkg.ProjectCodeSnapshot,
                ProjectName = projectSummary?.Name ?? pkg.ProjectNameSnapshot,
                SalesOrderId = effectiveSalesOrderId,
                SalesOrderCode = soCode,
                CustomerName = pkg.DeliveryPackaging?.SalesOrderNameSnapshot,
                DeliveryPackagingId = pkg.DeliveryPackagingId,
                DeliveryPackagingCode = pkg.DeliveryPackaging?.Code ?? pkg.DeliveryPackagingCodeSnapshot,
                SiteDeliveryId = isSiteDelivered ? siteDeliveryInfo?.SiteDeliveryId : null,
                SiteDeliveryCode = isSiteDelivered ? siteDeliveryInfo?.SiteDeliveryCode : null,
                SiteDeliveryStatus = deliveryStatus,
                CreatedDate = pkg.CreatedDate.ToVietnamDate(),
                CreatedByUser = pkg.CreatedByUser,
                Items = []
            };

            // Build danh sách Cụm / Chi tiết con (Items) bên trong kiện
            int itemLineNum = 1;
            decimal totalPackageQty = 0;

            foreach (var detail in pkg.Details.OrderBy(d => d.LineNum))
            {
                var packingCodeKey = detail.PackingCode;
                var hasFgPacking = !string.IsNullOrWhiteSpace(packingCodeKey) &&
                                   fgPackingByCodeMap.TryGetValue(packingCodeKey, out var matchedFgPacking);

                mechMap.TryGetValue(detail.MechanicalPackingListCode ?? string.Empty, out var matchedMech);

                if (hasFgPacking && matchedFgPacking != null && matchedFgPacking.Details != null && matchedFgPacking.Details.Count > 0)
                {
                    // Trường hợp 1 (Hàng Dự án / Thành phẩm chế tạo):
                    // Bóc tách từng CỤM CHI TIẾT (TagNo) từ FinishedGoodsPackingDetail
                    foreach (var part in matchedFgPacking.Details.OrderBy(p => p.LineNum))
                    {
                        var resolvedDesignModelId = matchedFgPacking.DesignModelId ??
                                                   matchedFgPacking.MechanicalPackingList?.DesignModelId ??
                                                   matchedMech?.DesignModelId;

                        var resolvedModelId = matchedFgPacking.ModelId ??
                                             matchedFgPacking.MechanicalPackingList?.ModelId ??
                                             matchedMech?.ModelId;

                        var resolvedFgId = matchedFgPacking.FinishedGoodId ??
                                          matchedFgPacking.MechanicalPackingList?.FinishedGoodId ??
                                          matchedMech?.FinishedGoodId;

                        packageDto.Items.Add(new DeliveryPackingReportItemDto
                        {
                            Id = part.Id,
                            LineNum = itemLineNum++,
                            ItemKind = "FinishedGoodPart",
                            Code = part.TagNo,
                            Name = part.SemiFinishedGoodNameSnapshot ?? part.ProductDescription ?? "Cụm chi tiết",
                            SemiFinishedGoodId = part.SemiFinishedGoodId != Guid.Empty ? part.SemiFinishedGoodId : null,
                            Description = part.ProductDescription,
                            FinishedGoodId = resolvedFgId,
                            FinishedGoodCode = matchedFgPacking.FinishedGoodCodeSnapshot ?? detail.FinishedGoodsCode,
                            FinishedGoodName = matchedFgPacking.FinishedGoodNameSnapshot ?? detail.FinishedGoodsName,
                            ModelId = resolvedModelId,
                            ModelCode = matchedFgPacking.ModelCodeSnapshot,
                            ModelName = matchedFgPacking.ModelNameSnapshot,
                            // DesignModelId tra cứu ID không gán cứng
                            DesignModelId = resolvedDesignModelId,
                            DesignModelCode = matchedFgPacking.DesignModelCodeSnapshot ?? detail.DesignModelCode,
                            DesignModelName = matchedFgPacking.DesignModelNameSnapshot ?? detail.DesignModelName,
                            MechanicalPackingListCode = matchedFgPacking.MechanicalPackingList?.Code ?? detail.MechanicalPackingListCode,
                            UomId = part.UOMId,
                            UomName = part.UOMNameSnapshot,
                            DimensionL = part.DimensionL,
                            DimensionW = part.DimensionW,
                            DimensionH = part.DimensionH,
                            Quantity = part.ActualQuantity,
                            Weight = part.ActualWeight,
                            Remark = part.Remark
                        });
                        totalPackageQty += part.ActualQuantity;
                    }
                }
                else
                {
                    // Trường hợp 2 (Bán thẳng SO hoặc Hàng nguyên kiện không qua chế tạo cơ khí):
                    // Lấy thông tin từ chính dòng detail của DeliveryPacking
                    var resolvedDesignModelId = matchedMech?.DesignModelId;
                    var resolvedModelId = matchedMech?.ModelId;
                    var resolvedFgId = matchedMech?.FinishedGoodId;

                    packageDto.Items.Add(new DeliveryPackingReportItemDto
                    {
                        Id = detail.Id,
                        LineNum = itemLineNum++,
                        ItemKind = isSalesOrderSource ? "Material" : "FinishedGoodPart",
                        Code = detail.PackingCode ?? detail.FinishedGoodsCode ?? "SP",
                        Name = detail.FinishedGoodsName ?? "Nguyên vật liệu / Sản phẩm giao",
                        Description = detail.Dimensions,
                        FinishedGoodId = resolvedFgId,
                        FinishedGoodCode = detail.FinishedGoodsCode,
                        FinishedGoodName = detail.FinishedGoodsName,
                        ModelId = resolvedModelId,
                        ModelCode = null,
                        ModelName = null,
                        DesignModelId = resolvedDesignModelId,
                        DesignModelCode = detail.DesignModelCode,
                        DesignModelName = detail.DesignModelName,
                        MechanicalPackingListCode = detail.MechanicalPackingListCode,
                        UomId = null,
                        UomName = "Kiện/Bộ",
                        Quantity = detail.ActualQuantity,
                        Weight = detail.ActualWeight,
                        Remark = detail.Remark
                    });
                    totalPackageQty += detail.ActualQuantity;
                }
            }

            packageDto.ItemCount = packageDto.Items.Count;
            packageDto.TotalQuantity = totalPackageQty;

            resultRows.Add(packageDto);
        }

        // 7. Áp dụng bộ lọc in-memory nghiêm ngặt theo ID cho các điều kiện chi tiết
        var filteredRows = resultRows;

        if (filter.FinishedGoodId.HasValue && filter.FinishedGoodId.Value != Guid.Empty)
        {
            filteredRows = filteredRows
                .Where(r => r.Items.Any(i => i.FinishedGoodId == filter.FinishedGoodId.Value))
                .ToList();
        }

        if (filter.ModelId.HasValue && filter.ModelId.Value != Guid.Empty)
        {
            filteredRows = filteredRows
                .Where(r => r.Items.Any(i => i.ModelId == filter.ModelId.Value))
                .ToList();
        }

        // Lọc theo DesignModelId (tra cứu Guid, KHÔNG gán cứng chuỗi)
        if (filter.DesignModelId.HasValue && filter.DesignModelId.Value != Guid.Empty)
        {
            filteredRows = filteredRows
                .Where(r => r.Items.Any(i => i.DesignModelId == filter.DesignModelId.Value))
                .ToList();
        }

        if (filter.SiteDeliveryStatus.HasValue)
        {
            filteredRows = filteredRows
                .Where(r => r.SiteDeliveryStatus == filter.SiteDeliveryStatus.Value)
                .ToList();
        }

        if (!string.IsNullOrWhiteSpace(filter.SearchText))
        {
            var term = filter.SearchText.Trim().ToLowerInvariant();
            filteredRows = filteredRows.Where(r =>
                (r.PackingCode != null && r.PackingCode.ToLowerInvariant().Contains(term)) ||
                (r.Code != null && r.Code.ToLowerInvariant().Contains(term)) ||
                (r.ProjectName != null && r.ProjectName.ToLowerInvariant().Contains(term)) ||
                (r.SalesOrderCode != null && r.SalesOrderCode.ToLowerInvariant().Contains(term)) ||
                r.Items.Any(i =>
                    (i.Code != null && i.Code.ToLowerInvariant().Contains(term)) ||
                    (i.Name != null && i.Name.ToLowerInvariant().Contains(term)) ||
                    (i.Description != null && i.Description.ToLowerInvariant().Contains(term)))
            ).ToList();
        }

        return filteredRows;
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;
using CogainSolution.Grpc.ErpInfo;
using CogainSolution.Grpc.MasterDataInfo;
using Contracts.Domain.Entities;
using Contracts.Domain.Interfaces;
using Contracts.Services;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Configuration;
using Serilog;
using ServiceDesk.Data.Entities.PackingList;
using ServiceDesk.Data.Entities.SalesOrders;
using ServiceDesk.Services.Interface.PackingList;
using Shared.Dto.ServiceDesk.PackingList;
using Shared.Enums;

namespace ServiceDesk.Services.Implement.PackingList;

/// <summary>
/// Service tổng hợp báo cáo đóng kiện giao hàng (Delivery Packing Report).
/// Hỗ trợ cả 2 nguồn: Dự án (chế tạo) HOẶC Đơn bán hàng SO (bán thẳng NVL).
/// Tuyệt đối không gán cứng chuỗi (DesignModelId, PackingCodesId tra cứu theo ID - Guid).
/// </summary>
public partial class DeliveryPackingReportService(
    IUnitOfWork unitOfWork,
    IConfiguration config,
    IFileService fileService,
    ILogger logger,
    MasterDataInfoGrpc.MasterDataInfoGrpcClient masterDataGrpcClient,
    ErpInfoGrpc.ErpInfoGrpcClient erpGrpcClient
) : IDeliveryPackingReportService
{
    private readonly IUnitOfWork _unitOfWork = unitOfWork;
    private readonly IConfiguration _config = config;
    private readonly IFileService _fileService = fileService;
    private readonly ILogger _logger = logger;
    private readonly MasterDataInfoGrpc.MasterDataInfoGrpcClient _masterDataGrpcClient = masterDataGrpcClient;
    private readonly ErpInfoGrpc.ErpInfoGrpcClient _erpGrpcClient = erpGrpcClient;

    /// <summary>
    /// Lấy danh sách báo cáo đóng kiện giao hàng theo bộ lọc (yêu cầu ProjectId HOẶC SalesOrderId).
    /// </summary>
    public async Task<Result<List<DeliveryPackingReportPackageDto>>> GetReportAsync(DeliveryPackingReportFilterRequest filter)
    {
        var hasProject = filter.ProjectId.HasValue && filter.ProjectId.Value != Guid.Empty;
        var hasSalesOrder = filter.SalesOrderId.HasValue && filter.SalesOrderId.Value != Guid.Empty;

        if (!hasProject && !hasSalesOrder)
        {
            return Result<List<DeliveryPackingReportPackageDto>>.Failure("Bắt buộc chọn Dự án hoặc Đơn bán hàng (SO) để xem báo cáo đóng kiện giao hàng.");
        }

        var resolveProjectTask = hasProject ? ResolveProjectByIdAsync(filter.ProjectId!.Value) : Task.FromResult<(Guid?, Dictionary<string, ProjectSummary>, string?)>((null, [], null));
        var resolveSoTask = hasSalesOrder ? ResolveSalesOrderByIdAsync(filter.SalesOrderId!.Value) : Task.FromResult<(Guid?, Dictionary<Guid, string>, string?)>((null, [], null));
        var excludedIdsTask = GetExcludedWorkItemIdsAsync();

        await Task.WhenAll(resolveProjectTask, resolveSoTask, excludedIdsTask);

        var (_, projMap, projError) = await resolveProjectTask;
        if (projError != null) return Result<List<DeliveryPackingReportPackageDto>>.Failure(projError);

        var (_, soMap, soError) = await resolveSoTask;
        if (soError != null) return Result<List<DeliveryPackingReportPackageDto>>.Failure(soError);

        var excludedIds = await excludedIdsTask;

        List<DeliveryPackingReportPackageDto> rows;
        try
        {
            var deliveryPackingRepo = _unitOfWork.GetRepository<FinishedGoodsDeliveryPacking>().Query().AsNoTracking();
            var siteDeliveryDetailRepo = _unitOfWork.GetRepository<SiteDeliveryDetail>().Query().AsNoTracking();
            var fgPackingRepo = _unitOfWork.GetRepository<FinishedGoodsPacking>().Query().AsNoTracking();
            var mechListRepo = _unitOfWork.GetRepository<MechanicalPackingList>().Query().AsNoTracking();
            var packingCodesRepo = _unitOfWork.GetRepository<PackingCodes>().Query().AsNoTracking();
            var soDetailRepo = _unitOfWork.GetRepository<SalesOrderDetail>().Query().AsNoTracking();

            rows = await DeliveryPackingReportQueryBuilder.BuildReportDataAsync(
                deliveryPackingRepo,
                siteDeliveryDetailRepo,
                fgPackingRepo,
                mechListRepo,
                packingCodesRepo,
                soDetailRepo,
                excludedIds,
                filter,
                projMap,
                soMap);
        }
        catch (Exception ex)
        {
            _logger.Error(ex, "Lỗi khi tổng hợp dữ liệu báo cáo đóng kiện giao hàng. Filter: {@Filter}", filter);
            return Result<List<DeliveryPackingReportPackageDto>>.Failure("Lỗi hệ thống khi tạo báo cáo đóng kiện giao hàng.");
        }

        // Bổ sung thông tin Model / DesignModel (tra cứu ID từ MasterData gRPC, tuyệt đối không gán cứng)
        await EnrichModelInfoAsync(rows);

        // Bổ sung thông tin Cụm bán thành phẩm (SemiFinishedGood)
        await EnrichProductPartInfoAsync(rows);

        // Bổ sung thông tin Đơn vị tính (UOM)
        await EnrichUomInfoAsync(rows);

        return Result<List<DeliveryPackingReportPackageDto>>.Success(rows);
    }

    /// <summary>
    /// Thống kê KPI tổng quan cho báo cáo đóng kiện giao hàng.
    /// </summary>
    public async Task<Result<DeliveryPackingReportSummaryDto>> GetSummaryAsync(DeliveryPackingReportFilterRequest filter)
    {
        var reportResult = await GetReportAsync(filter);
        if (!reportResult.IsSuccess || reportResult.Data == null)
            return Result<DeliveryPackingReportSummaryDto>.Failure(reportResult.Message);

        var packages = reportResult.Data;
        int totalPackages = packages.Count;
        int deliveredPackages = packages.Count(p => p.SiteDeliveryStatus == EPackingReportStatus.Full);
        int inStockPackages = totalPackages - deliveredPackages;

        decimal deliveryPercent = totalPackages > 0
            ? Math.Round((decimal)deliveredPackages * 100m / totalPackages, 2)
            : 0m;

        decimal totalWeight = packages.Sum(p => p.ActualTotalWeight);
        decimal deliveredWeight = packages
            .Where(p => p.SiteDeliveryStatus == EPackingReportStatus.Full)
            .Sum(p => p.ActualTotalWeight);

        int totalItems = packages.Sum(p => p.ItemCount);
        decimal totalItemQty = packages.Sum(p => p.TotalQuantity);

        var summary = new DeliveryPackingReportSummaryDto
        {
            TotalPackages = totalPackages,
            DeliveredPackages = deliveredPackages,
            InStockPackages = inStockPackages,
            DeliveryProgressPercentage = deliveryPercent,
            TotalWeight = totalWeight,
            DeliveredWeight = deliveredWeight,
            TotalItems = totalItems,
            TotalItemQuantity = totalItemQty
        };

        return Result<DeliveryPackingReportSummaryDto>.Success(summary);
    }

    // ─── Helpers: Enrich thông tin qua MasterData gRPC ─────────────────────────────

    /// <summary>
    /// Bổ sung Mã/Tên Model và DesignModel cho các dòng chi tiết (resolve qua gRPC GetAllFinishedGoodModelsAsync).
    /// Map ID string với Guid từ entity; tuyệt đối không gán cứng chuỗi!
    /// </summary>
    private async Task EnrichModelInfoAsync(List<DeliveryPackingReportPackageDto> packages)
    {
        var allItems = packages.SelectMany(p => p.Items).ToList();
        var hasModel = allItems.Any(r =>
            (r.ModelId.HasValue && r.ModelId.Value != Guid.Empty) ||
            (r.DesignModelId.HasValue && r.DesignModelId.Value != Guid.Empty));

        if (!hasModel) return;

        try
        {
            var modelResponse = await _masterDataGrpcClient.GetAllFinishedGoodModelsAsync(
                new Google.Protobuf.WellKnownTypes.Empty());

            if (modelResponse?.Success != true || modelResponse.Items.Count == 0) return;

            var modelMap = modelResponse.Items.ToDictionary(m => m.Id, m => m, StringComparer.OrdinalIgnoreCase);

            foreach (var item in allItems)
            {
                if (item.ModelId.HasValue && item.ModelId.Value != Guid.Empty &&
                    modelMap.TryGetValue(item.ModelId.Value.ToString(), out var model))
                {
                    item.ModelCode = model.Code;
                    item.ModelName = model.Name;
                }

                if (item.DesignModelId.HasValue && item.DesignModelId.Value != Guid.Empty &&
                    modelMap.TryGetValue(item.DesignModelId.Value.ToString(), out var designModel))
                {
                    item.DesignModelCode = designModel.Code;
                    item.DesignModelName = designModel.Name;
                }
            }
        }
        catch (Exception ex)
        {
            _logger.Warning(ex, "Không thể lấy thông tin Model/DesignModel qua gRPC cho báo cáo đóng kiện giao hàng");
        }
    }

    /// <summary>
    /// Bổ sung thông tin Cụm bán thành phẩm (SemiFinishedGood) qua gRPC.
    /// </summary>
    private async Task EnrichProductPartInfoAsync(List<DeliveryPackingReportPackageDto> packages)
    {
        var allItems = packages.SelectMany(p => p.Items).ToList();
        var validItems = allItems.Where(r => r.SemiFinishedGoodId.HasValue && r.SemiFinishedGoodId.Value != Guid.Empty).ToList();
        if (validItems.Count == 0) return;

        try
        {
            var response = await _masterDataGrpcClient.GetAllSemiFinishedGoodsAsync(
                new Google.Protobuf.WellKnownTypes.Empty());

            if (response?.Success != true || response.Items.Count == 0) return;

            var partMap = response.Items.ToDictionary(x => x.Id, x => x, StringComparer.OrdinalIgnoreCase);

            foreach (var item in validItems)
            {
                if (partMap.TryGetValue(item.SemiFinishedGoodId!.Value.ToString(), out var part))
                {
                    item.ProductPartCode = part.Code;
                    item.Name = part.Name;
                }
            }
        }
        catch (Exception ex)
        {
            _logger.Warning(ex, "Không thể lấy thông tin Cụm (SemiFinishedGood) qua gRPC cho báo cáo đóng kiện giao hàng");
        }
    }

    /// <summary>
    /// Bổ sung Tên Đơn vị tính (UOM) qua gRPC.
    /// </summary>
    private async Task EnrichUomInfoAsync(List<DeliveryPackingReportPackageDto> packages)
    {
        var allItems = packages.SelectMany(p => p.Items).ToList();
        var uomIds = allItems
            .Where(r => r.UomId.HasValue && r.UomId.Value != Guid.Empty)
            .Select(r => r.UomId!.Value.ToString())
            .Distinct()
            .ToList();

        if (uomIds.Count == 0) return;

        try
        {
            var uomRequest = new GetIdsRequest();
            uomRequest.Ids.AddRange(uomIds);
            var uomResponse = await _masterDataGrpcClient.GetUnitOfMeasuresByIdsAsync(uomRequest);

            if (uomResponse?.Success == true && uomResponse.Items.Count > 0)
            {
                var uomMap = uomResponse.Items.ToDictionary(x => x.Id, x => x.Name, StringComparer.OrdinalIgnoreCase);

                foreach (var item in allItems)
                {
                    if (item.UomId.HasValue && uomMap.TryGetValue(item.UomId.Value.ToString(), out var uomName))
                    {
                        item.UomName = uomName;
                    }
                }
            }
        }
        catch (Exception ex)
        {
            _logger.Warning(ex, "Không thể lấy thông tin Đơn vị tính qua gRPC cho báo cáo đóng kiện giao hàng");
        }
    }

    // ─── Helpers: Resolve Project & SalesOrder & ExcludedIds ───────────────────────

    protected async Task<(Guid? ProjectId, Dictionary<string, ProjectSummary> ProjMap, string? Error)>
        ResolveProjectByIdAsync(Guid projectId)
    {
        try
        {
            var response = await _masterDataGrpcClient
                .GetProjectsByIdsAsync(new GetIdsRequest { Ids = { projectId.ToString() } })
                .ResponseAsync;

            if (response?.Success != true)
                return (null, new Dictionary<string, ProjectSummary>(), "Không tìm thấy dự án.");

            var project = response.Projects
                .FirstOrDefault(x => string.Equals(x.Id, projectId.ToString(), StringComparison.OrdinalIgnoreCase));

            if (project == null)
                return (null, new Dictionary<string, ProjectSummary>(), "Không tìm thấy dự án.");

            var projMap = new Dictionary<string, ProjectSummary>(StringComparer.OrdinalIgnoreCase)
            {
                [project.Id] = project
            };

            return (projectId, projMap, null);
        }
        catch (Exception ex)
        {
            _logger.Warning(ex, "gRPC error resolving project by id: {ProjectId}", projectId);
            return (null, new Dictionary<string, ProjectSummary>(), "Không thể kết nối đến hệ thống dự án.");
        }
    }

    protected async Task<(Guid? SalesOrderId, Dictionary<Guid, string> SalesOrderMap, string? Error)>
        ResolveSalesOrderByIdAsync(Guid salesOrderId)
    {
        try
        {
            var so = await _unitOfWork.GetRepository<SalesOrder>().Query()
                .AsNoTracking()
                .Where(x => x.Id == salesOrderId)
                .Select(x => new { x.Id, x.Code })
                .FirstOrDefaultAsync();

            if (so == null)
                return (null, [], "Không tìm thấy đơn bán hàng (SO).");

            var soMap = new Dictionary<Guid, string>
            {
                [so.Id] = so.Code
            };

            return (salesOrderId, soMap, null);
        }
        catch (Exception ex)
        {
            _logger.Warning(ex, "Lỗi khi tra cứu thông tin đơn bán hàng: {SalesOrderId}", salesOrderId);
            return (null, [], "Không thể tra cứu thông tin đơn bán hàng.");
        }
    }

    protected async Task<HashSet<Guid>> GetExcludedWorkItemIdsAsync()
    {
        try
        {
            var grpcResponse = await _masterDataGrpcClient.GetWorkItemIdsByStatusAsync(
                new GetWorkItemIdsByStatusRequest
                {
                    StatusEnums = { (int)EWorkItemStatus.Cancelled }
                });

            if (!grpcResponse.Success) return [];

            return [.. grpcResponse.WorkItemIds
                .Where(idStr => Guid.TryParse(idStr, out _))
                .Select(idStr => Guid.Parse(idStr))];
        }
        catch (Exception ex)
        {
            _logger.Warning(ex, "Lỗi khi lấy danh sách WorkItem bị hủy");
            return [];
        }
    }
}

