using System;
using System.IO;
using System.Linq;
using System.Threading.Tasks;
using ClosedXML.Excel;
using Contracts.Domain.Entities;
using Infrastructure.Helpers;
using ServiceDesk.Data.Entities.PackingList;
using Shared.Dto.ServiceDesk.PackingList;
using Shared.Enums;

namespace ServiceDesk.Services.Implement.PackingList;

public partial class DeliveryPackingReportService
{
    public async Task<Result<string>> ExportReportAsync(DeliveryPackingReportFilterRequest filter)
    {
        var reportResult = await GetReportAsync(filter);
        if (!reportResult.IsSuccess || reportResult.Data == null)
            return Result<string>.Failure(reportResult.Message ?? "Không thể lấy dữ liệu báo cáo để export.");

        var packages = reportResult.Data;
        if (packages.Count == 0)
            return Result<string>.Failure("Không có dữ liệu đóng kiện giao hàng để export.");

        int totalItemRows = packages.Sum(p => Math.Max(1, p.Items.Count));
        if (totalItemRows > 30_000)
            return Result<string>.Failure($"Tập dữ liệu quá lớn ({totalItemRows:N0} dòng). Vui lòng thu hẹp bộ lọc.");

        try
        {
            using var workbook = new XLWorkbook();
            var ws = workbook.Worksheets.Add("Report_DeliveryPacking");

            // ─── HEADER ROW 1: Group Headers ──────────────────────────────────────────
            var groupPkg = ws.Range(1, 1, 1, 11).Merge();
            groupPkg.Value = "Thông tin kiện hàng giao (Package Information)";

            var groupItem = ws.Range(1, 12, 1, 26).Merge();
            groupItem.Value = "Chi tiết cụm chi tiết / Nguyên vật liệu bên trong kiện (Item Details)";

            var headerRow1 = ws.Range(1, 1, 1, 26);
            headerRow1.Style.Font.Bold = true;
            headerRow1.Style.Font.FontSize = 11;
            headerRow1.Style.Font.FontColor = XLColor.White;
            headerRow1.Style.Fill.BackgroundColor = XLColor.FromHtml("#1F4E78");
            headerRow1.Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
            headerRow1.Style.Alignment.Vertical = XLAlignmentVerticalValues.Center;
            headerRow1.Style.Border.OutsideBorder = XLBorderStyleValues.Thin;
            headerRow1.Style.Border.InsideBorder = XLBorderStyleValues.Thin;
            ws.Row(1).Height = 26;

            // ─── HEADER ROW 2: Column Headers ─────────────────────────────────────────
            var headers = new string[]
            {
                "STT Kiện", "Mã kiện", "Mã phiếu đóng kiện", "Kích thước (D x R x C mm)", "Khối lượng kiện (kg)",
                "Nguồn hàng", "Mã Dự án / Đơn hàng", "Tên Dự án / Khách hàng", "Lệnh đóng gói",
                "Mã phiếu giao hàng", "Tình trạng giao hàng",
                "STT con", "Loại", "TagNo / Mã NVL", "Tên cụm / Tên NVL",
                "Mã thành phẩm", "Tên thành phẩm", "Model hiệu suất", "Model thiết kế",
                "Đơn vị", "Dài (L)", "Rộng (W)", "Cao (H)", "Số lượng", "Khối lượng (kg)", "Ghi chú"
            };

            for (int i = 0; i < headers.Length; i++)
            {
                var cell = ws.Cell(2, i + 1);
                cell.Value = headers[i];
                cell.Style.Font.Bold = true;
                cell.Style.Font.FontColor = XLColor.White;
                cell.Style.Fill.BackgroundColor = XLColor.FromHtml("#2F5597");
                cell.Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
                cell.Style.Alignment.Vertical = XLAlignmentVerticalValues.Center;
                cell.Style.Alignment.WrapText = true;
                cell.Style.Border.OutsideBorder = XLBorderStyleValues.Thin;
            }
            ws.Row(2).Height = 32;

            ws.Range(2, 1, 2, headers.Length).SetAutoFilter();
            ws.SheetView.FreezeRows(2);

            // ─── POPULATE ROWS ────────────────────────────────────────────────────────
            int currentRow = 3;

            foreach (var pkg in packages)
            {
                int pkgStartRow = currentRow;
                int itemsCount = pkg.Items.Count;
                var sourceCode = pkg.SourceType == "SalesOrder" ? pkg.SalesOrderCode : pkg.ProjectCode;
                var sourceName = pkg.SourceType == "SalesOrder" ? pkg.CustomerName : pkg.ProjectName;
                var sourceDisplay = pkg.SourceType == "SalesOrder" ? "Đơn bán hàng (SO)" : "Dự án chế tạo";

                if (itemsCount == 0)
                {
                    // Dòng chỉ có kiện không có chi tiết con
                    FillPackageCells(ws, currentRow, pkg, sourceDisplay, sourceCode, sourceName);
                    currentRow++;
                }
                else
                {
                    for (int j = 0; j < itemsCount; j++)
                    {
                        var item = pkg.Items[j];
                        FillPackageCells(ws, currentRow, pkg, sourceDisplay, sourceCode, sourceName);

                        // Điền chi tiết con
                        ws.Cell(currentRow, 12).Value = item.LineNum;
                        ws.Cell(currentRow, 13).Value = item.ItemKind == "Material" ? "Nguyên vật liệu" : "Cụm chi tiết";
                        ws.Cell(currentRow, 14).Value = item.Code;
                        ws.Cell(currentRow, 15).Value = item.Name;
                        ws.Cell(currentRow, 16).Value = item.FinishedGoodCode ?? string.Empty;
                        ws.Cell(currentRow, 17).Value = item.FinishedGoodName ?? string.Empty;
                        ws.Cell(currentRow, 18).Value = item.ModelCode ?? string.Empty;
                        ws.Cell(currentRow, 19).Value = item.DesignModelCode ?? string.Empty;
                        ws.Cell(currentRow, 20).Value = item.UomName ?? string.Empty;
                        ws.Cell(currentRow, 21).Value = item.DimensionL.HasValue ? item.DimensionL.Value : string.Empty;
                        ws.Cell(currentRow, 22).Value = item.DimensionW.HasValue ? item.DimensionW.Value : string.Empty;
                        ws.Cell(currentRow, 23).Value = item.DimensionH.HasValue ? item.DimensionH.Value : string.Empty;

                        var qtyCell = ws.Cell(currentRow, 24);
                        qtyCell.Value = item.Quantity;
                        qtyCell.Style.NumberFormat.Format = "#,##0.##";

                        var weightCell = ws.Cell(currentRow, 25);
                        weightCell.Value = item.Weight;
                        weightCell.Style.NumberFormat.Format = "#,##0.00";

                        ws.Cell(currentRow, 26).Value = item.Remark ?? string.Empty;

                        // Định dạng căn lề cho dòng con
                        ws.Cell(currentRow, 12).Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
                        ws.Cell(currentRow, 13).Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
                        ws.Cell(currentRow, 14).Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
                        ws.Cell(currentRow, 20).Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
                        ws.Cell(currentRow, 21).Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Right;
                        ws.Cell(currentRow, 22).Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Right;
                        ws.Cell(currentRow, 23).Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Right;
                        ws.Cell(currentRow, 24).Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Right;
                        ws.Cell(currentRow, 25).Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Right;

                        // Viền
                        for (int c = 12; c <= 26; c++)
                        {
                            ws.Cell(currentRow, c).Style.Border.OutsideBorder = XLBorderStyleValues.Thin;
                            ws.Cell(currentRow, c).Style.Border.OutsideBorderColor = XLColor.FromHtml("#D9D9D9");
                        }

                        currentRow++;
                    }

                    // Merge các ô thuộc cấp Kiện (cột 1 -> 11) nếu có nhiều dòng con
                    if (currentRow - 1 > pkgStartRow)
                    {
                        for (int col = 1; col <= 11; col++)
                        {
                            var mergeRange = ws.Range(pkgStartRow, col, currentRow - 1, col).Merge();
                            mergeRange.Style.Alignment.Vertical = XLAlignmentVerticalValues.Center;
                        }
                    }
                }
            }

            // ─── TỰ ĐỘNG CĂN ĐỘ RỘNG CỘT ────────────────────────────────────────────
            ws.Column(1).Width = 8;   // STT Kiện
            ws.Column(2).Width = 16;  // Mã kiện
            ws.Column(3).Width = 18;  // Mã phiếu đóng kiện
            ws.Column(4).Width = 20;  // Kích thước kiện
            ws.Column(5).Width = 16;  // Khối lượng kiện
            ws.Column(6).Width = 16;  // Nguồn hàng
            ws.Column(7).Width = 18;  // Mã dự án/SO
            ws.Column(8).Width = 28;  // Tên dự án/Khách hàng
            ws.Column(9).Width = 18;  // Lệnh đóng gói
            ws.Column(10).Width = 18; // Mã phiếu giao hàng
            ws.Column(11).Width = 22; // Tình trạng giao hàng
            ws.Column(12).Width = 8;  // STT con
            ws.Column(13).Width = 14; // Loại
            ws.Column(14).Width = 16; // TagNo/Mã NVL
            ws.Column(15).Width = 28; // Tên cụm / Tên NVL
            ws.Column(16).Width = 16; // Mã TP
            ws.Column(17).Width = 24; // Tên TP
            ws.Column(18).Width = 16; // Model hiệu suất
            ws.Column(19).Width = 16; // Model thiết kế
            ws.Column(20).Width = 10; // ĐVT
            ws.Column(21).Width = 10; // Dài
            ws.Column(22).Width = 10; // Rộng
            ws.Column(23).Width = 10; // Cao
            ws.Column(24).Width = 12; // Số lượng
            ws.Column(25).Width = 14; // Khối lượng
            ws.Column(26).Width = 24; // Ghi chú

            // ─── UPLOAD FILE LÊN SERVER FTP/SFTP ──────────────────────────────────────
            await using var ms = new MemoryStream();
            workbook.SaveAs(ms);
            var excelBytes = ms.ToArray();

            if (excelBytes.Length == 0)
                return Result<string>.Failure("Không thể tạo file export.");

            var fileName = $"DeliveryPacking_Report_{DateTime.Now:yyyyMMdd_HHmmss}.xlsx";

            var formFile = new FormFileHelper(new MemoryStream(excelBytes), excelBytes.Length, "file", fileName)
            {
                ContentType = "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"
            };

            string ip = _config["FtpSettings:Ip"] ?? string.Empty;
            string environment = _config["FtpSettings:Environment"] ?? string.Empty;
            string ftpUsername = _config["FtpSettings:Username"] ?? string.Empty;
            string ftpPassword = _config["FtpSettings:Password"] ?? string.Empty;
            string folderName = $"{typeof(FinishedGoodsDeliveryPacking).Name}/Exports";
            EUploadType uploadType = Enum.TryParse<EUploadType>(_config["FtpSettings:UploadType"], out var type)
                ? type : EUploadType.Sftp;

            var uploadResult = _fileService.UploadFile(formFile, ip, ftpUsername, ftpPassword,
                environment, folderName, uploadType, fileName);

            if (uploadResult != null && uploadResult.TryGetValue("filePath", out var exportFilePath) && exportFilePath != null)
            {
                return Result<string>.Success(exportFilePath.ToString()!);
            }

            return Result<string>.Failure("Không thể upload file export lên máy chủ lưu trữ.");
        }
        catch (Exception ex)
        {
            _logger.Error(ex, "Lỗi khi export báo cáo đóng kiện giao hàng Excel");
            return Result<string>.Failure("Lỗi hệ thống khi tạo file Excel export.");
        }
    }

    private static void FillPackageCells(IXLWorksheet ws, int row, DeliveryPackingReportPackageDto pkg,
        string sourceDisplay, string? sourceCode, string? sourceName)
    {
        ws.Cell(row, 1).Value = pkg.STT;
        ws.Cell(row, 2).Value = pkg.PackingCode;
        ws.Cell(row, 3).Value = pkg.Code;
        ws.Cell(row, 4).Value = pkg.Dimensions ?? string.Empty;

        var weightCell = ws.Cell(row, 5);
        weightCell.Value = pkg.ActualTotalWeight;
        weightCell.Style.NumberFormat.Format = "#,##0.00";

        ws.Cell(row, 6).Value = sourceDisplay;
        ws.Cell(row, 7).Value = sourceCode ?? string.Empty;
        ws.Cell(row, 8).Value = sourceName ?? string.Empty;
        ws.Cell(row, 9).Value = pkg.DeliveryPackagingCode ?? string.Empty;
        ws.Cell(row, 10).Value = pkg.SiteDeliveryCode ?? string.Empty;

        var statusCell = ws.Cell(row, 11);
        ApplyDeliveryStatusStyle(statusCell, pkg.SiteDeliveryStatus);

        // Styling cho cột kiện cha
        ws.Cell(row, 1).Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
        ws.Cell(row, 2).Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
        ws.Cell(row, 2).Style.Font.Bold = true;
        ws.Cell(row, 3).Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
        ws.Cell(row, 4).Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
        ws.Cell(row, 5).Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Right;
        ws.Cell(row, 6).Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
        ws.Cell(row, 7).Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
        ws.Cell(row, 9).Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
        ws.Cell(row, 10).Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;

        for (int c = 1; c <= 11; c++)
        {
            ws.Cell(row, c).Style.Border.OutsideBorder = XLBorderStyleValues.Thin;
            ws.Cell(row, c).Style.Border.OutsideBorderColor = XLColor.FromHtml("#B0C4DE");
            ws.Cell(row, c).Style.Fill.BackgroundColor = XLColor.FromHtml("#F2F5F9");
        }
    }

    private static void ApplyDeliveryStatusStyle(IXLCell cell, EPackingReportStatus status)
    {
        switch (status)
        {
            case EPackingReportStatus.Full:
                cell.Value = "Đã giao công trình";
                cell.Style.Fill.BackgroundColor = XLColor.FromHtml("#E2F0D9");
                cell.Style.Font.FontColor = XLColor.FromHtml("#385723");
                break;
            case EPackingReportStatus.Partial:
                cell.Value = "Đang giao hàng";
                cell.Style.Fill.BackgroundColor = XLColor.FromHtml("#FFF2CC");
                cell.Style.Font.FontColor = XLColor.FromHtml("#B25900");
                break;
            default:
                cell.Value = "Chưa giao (Lưu kho)";
                cell.Style.Fill.BackgroundColor = XLColor.FromHtml("#F2F2F2");
                cell.Style.Font.FontColor = XLColor.FromHtml("#595959");
                break;
        }

        cell.Style.Font.Bold = true;
        cell.Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
        cell.Style.Alignment.Vertical = XLAlignmentVerticalValues.Center;
        cell.Style.Border.OutsideBorder = XLBorderStyleValues.Thin;
    }
}

