import { useMemo, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { cn } from '@/lib/utils';
import { ResizableWrapTable, type ResizableWrapTableColumn } from '@shared/components';
import { Button, Combobox, NumericInput } from '@shared/ui';
import type { ReadonlyPackingDetailRow } from './packing-list-readonly-detail-table';

type Props = Readonly<{
  rows: ReadonlyPackingDetailRow[];
  uomOptions: { label: string; value: string }[];
  className?: string;
}>;

type MaterialRow = ReadonlyPackingDetailRow & { readonly _stt: number };

export function PackingListMaterialTable({ rows, uomOptions, className }: Props) {
  const { t } = useTranslation(['mechanicalPackingList', 'common']);

  const [searchText, setSearchText] = useState('');
  const [filterUOM, setFilterUOM] = useState('');
  const [filterQuantityFrom, setFilterQuantityFrom] = useState('');
  const [filterQuantityTo, setFilterQuantityTo] = useState('');
  const [filterWeightFrom, setFilterWeightFrom] = useState('');
  const [filterWeightTo, setFilterWeightTo] = useState('');

  const uomLabel = (id?: string) =>
    (id && uomOptions.find((u) => u.value === id)?.label) || id || '—';

  const getMaterialInfo = (row: ReadonlyPackingDetailRow) => {
    if (row.materialCode || row.materialName) {
      const model =
        row.modelCode && row.modelName
          ? `${row.modelCode} - ${row.modelName}`
          : row.modelName || row.modelCode || '—';
      return {
        code: row.materialCode || '—',
        name: row.materialName || row.productDescription || '—',
        model,
      };
    }
    const desc = row.productDescription || '';
    const match = desc.match(/^([^-]+)\s*-\s*([^(]+)(?:\s*\(([^)]+)\))?$/);
    if (match) {
      return {
        code: match[1].trim(),
        name: match[2].trim(),
        model: match[3]?.trim() || '—',
      };
    }
    return {
      code: '—',
      name: desc || '—',
      model: '—',
    };
  };

  const columns = useMemo<ResizableWrapTableColumn<MaterialRow>[]>(
    () => [
      {
        id: 'stt',
        header: t('mechanicalPackingList:dialogs.add.stt', { defaultValue: 'STT' }),
        defaultWidth: 50,
        minWidth: 40,
        cell: (row) => (
          <span className="block text-center text-xs font-medium text-muted-foreground">
            {row._stt}
          </span>
        ),
      },
      {
        id: 'materialCode',
        header: t('mechanicalPackingList:dialogs.add.materialCode', {
          defaultValue: 'Mã linh kiện',
        }),
        defaultWidth: 140,
        minWidth: 100,
        cell: (row) => {
          const info = getMaterialInfo(row);
          return info.code !== '—' ? (
            <span className="font-mono text-xs font-semibold text-primary">{info.code}</span>
          ) : (
            '—'
          );
        },
      },
      {
        id: 'materialName',
        header: t('mechanicalPackingList:dialogs.add.materialName', {
          defaultValue: 'Tên linh kiện / NVL',
        }),
        defaultWidth: 220,
        minWidth: 160,
        cell: (row) => {
          const info = getMaterialInfo(row);
          return <span className="font-medium text-foreground">{info.name}</span>;
        },
      },
      {
        id: 'materialModel',
        header: t('mechanicalPackingList:dialogs.add.materialModel', {
          defaultValue: 'Model NVL / Quy cách',
        }),
        defaultWidth: 180,
        minWidth: 120,
        cell: (row) => {
          const info = getMaterialInfo(row);
          return info.model || '—';
        },
      },
      {
        id: 'unit',
        header: t('mechanicalPackingList:dialogs.add.unit', { defaultValue: 'Đơn Vị' }),
        defaultWidth: 96,
        minWidth: 80,
        cell: (row) => uomLabel(row.UOMId),
      },
      {
        id: 'quantity',
        header: (
          <span className="block text-right">
            {t('mechanicalPackingList:dialogs.add.quantity', { defaultValue: 'Số Lượng' })}
          </span>
        ),
        defaultWidth: 100,
        minWidth: 80,
        cell: (row) => <span className="block text-right">{row.quantity || '—'}</span>,
      },
      {
        id: 'loosePartsFactoryWeight',
        header: (
          <span className="block text-right">
            {t('mechanicalPackingList:dialogs.add.loosePartsWeight', {
              defaultValue: 'Khối lượng linh kiện (kg)',
            })}
          </span>
        ),
        defaultWidth: 140,
        minWidth: 110,
        cell: (row) => (
          <span className="block text-right font-mono">
            {row.loosePartsFactoryWeight || row.designWeight || '—'}
          </span>
        ),
      },
      {
        id: 'remark',
        header: t('mechanicalPackingList:dialogs.add.note', { defaultValue: 'Ghi Chú' }),
        defaultWidth: 140,
        minWidth: 90,
        cell: (row) => row.remark || '—',
      },
    ],
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [t, uomOptions],
  );

  const tableData = useMemo<MaterialRow[]>(
    () => rows.map((r, index) => ({ ...r, _stt: index + 1 })),
    [rows],
  );

  const filteredData = useMemo(() => {
    let result = tableData;

    const term = searchText.trim().toLowerCase();
    if (term) {
      result = result.filter((r) => {
        const info = getMaterialInfo(r);
        return (
          info.code.toLowerCase().includes(term) ||
          info.name.toLowerCase().includes(term) ||
          info.model.toLowerCase().includes(term) ||
          (r.remark?.toLowerCase() || '').includes(term) ||
          uomLabel(r.UOMId).toLowerCase().includes(term)
        );
      });
    }

    if (filterUOM) {
      result = result.filter((r) => r.UOMId === filterUOM);
    }

    if (filterQuantityFrom || filterQuantityTo) {
      const min = filterQuantityFrom ? Number(filterQuantityFrom) : -Infinity;
      const max = filterQuantityTo ? Number(filterQuantityTo) : Infinity;
      result = result.filter((r) => {
        const qty = Number(r.quantity) || 0;
        return qty >= min && qty <= max;
      });
    }

    if (filterWeightFrom || filterWeightTo) {
      const min = filterWeightFrom ? Number(filterWeightFrom) : -Infinity;
      const max = filterWeightTo ? Number(filterWeightTo) : Infinity;
      result = result.filter((r) => {
        const weight = Number(r.loosePartsFactoryWeight) || Number(r.designWeight) || 0;
        return weight >= min && weight <= max;
      });
    }

    return result;
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [
    tableData,
    searchText,
    filterUOM,
    filterQuantityFrom,
    filterQuantityTo,
    filterWeightFrom,
    filterWeightTo,
  ]);

  const resetFilters = () => {
    setFilterUOM('');
    setFilterQuantityFrom('');
    setFilterQuantityTo('');
    setFilterWeightFrom('');
    setFilterWeightTo('');
  };

  if (!rows.length) {
    return (
      <div className="flex items-center justify-center py-8 text-sm text-muted-foreground border rounded-md">
