        className,
      )}
      columns={columns}
      data={filteredData}
      getRowId={(row) => `${row.materialCode ?? ''}-${row.tagNo ?? ''}-${row._stt}`}
      emptyMessage={t('mechanicalPackingList:dialogs.add.noMaterialData', {
        defaultValue: 'Không có dữ liệu linh kiện / nguyên vật liệu',
      })}
      showPagination={false}
      toolbarProps={{
        searchValue: searchText,
        onSearchChange: setSearchText,
        searchPlaceholder: t('mechanicalPackingList:dialogs.add.searchMaterialPlaceholder', {
          defaultValue: 'Tìm kiếm linh kiện, nguyên vật liệu...',
        }),
        filterLabel: t('common:action.filter', { defaultValue: 'Lọc' }),
        filterPopoverTitle: t('mechanicalPackingList:dialogs.add.filterMaterialTitle', {
          defaultValue: 'Bộ lọc linh kiện / nguyên vật liệu',
        }),
        totalCount: tableData.length,
        filteredCount: filteredData.length,
        renderFilterContent: (close) => (
          <form
            className="space-y-4 w-200"
            onSubmit={(e) => {
              e.preventDefault();
              close();
            }}
          >
            <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4">
              {/* Đơn vị tính */}
              <div className="space-y-1.5">
                <span className="text-sm font-medium text-muted-foreground">
                  {t('mechanicalPackingList:dialogs.add.unit', { defaultValue: 'Đơn Vị' })}
                </span>
                <Combobox
                  options={uomOptions}
                  value={filterUOM}
                  onValueChange={(val) => setFilterUOM(val || '')}
                  placeholder={t('common:select', { defaultValue: 'Chọn đơn vị' })}
                  buttonProps={{ className: 'w-full' }}
                />
              </div>

              {/* Số lượng */}
              <div className="space-y-1.5">
                <span className="text-sm font-medium text-muted-foreground">
                  {t('mechanicalPackingList:dialogs.add.quantity', { defaultValue: 'Số Lượng' })}
                </span>
                <div className="flex items-center gap-2">
                  <NumericInput
                    size="sm"
                    value={filterQuantityFrom}
                    onChange={(e) => setFilterQuantityFrom(e.target.value)}
                    placeholder={t('common:from', { defaultValue: 'Từ' })}
                  />
                  <span className="text-xs text-muted-foreground">-</span>
                  <NumericInput
                    size="sm"
                    value={filterQuantityTo}
                    onChange={(e) => setFilterQuantityTo(e.target.value)}
                    placeholder={t('common:to', { defaultValue: 'Đến' })}
                  />
                </div>
              </div>

              {/* Khối lượng linh kiện */}
              <div className="space-y-1.5">
                <span className="text-sm font-medium text-muted-foreground">
                  {t('mechanicalPackingList:dialogs.add.loosePartsWeight', {
                    defaultValue: 'Khối lượng linh kiện (kg)',
                  })}
                </span>
                <div className="flex items-center gap-2">
                  <NumericInput
                    size="sm"
                    value={filterWeightFrom}
                    onChange={(e) => setFilterWeightFrom(e.target.value)}
                    placeholder={t('common:from', { defaultValue: 'Từ' })}
                  />
                  <span className="text-xs text-muted-foreground">-</span>
                  <NumericInput
                    size="sm"
                    value={filterWeightTo}
                    onChange={(e) => setFilterWeightTo(e.target.value)}
                    placeholder={t('common:to', { defaultValue: 'Đến' })}
                  />
                </div>
              </div>
            </div>

            <div className="flex items-center justify-end gap-2 pt-2 border-t">
              <Button
                type="button"
                variant="outline"
                size="sm"
                onClick={() => {
                  resetFilters();
                  close();
                }}
              >
                {t('common:action.reset', { defaultValue: 'Đặt lại' })}
              </Button>
              <Button type="submit" size="sm">
                {t('common:action.apply', { defaultValue: 'Áp dụng' })}
              </Button>
            </div>
          </form>
        ),
      }}
    />
  );
}

