// Dựng các dòng chi tiết từ Packings của Hồ sơ thiết kế (DesignProfile.packings)
const designProfilePackagingsDetailRows = useMemo<ReadonlyPackingDetailRow[]>(() => {
  const packings = designProfileByIdQuery.data?.data?.details?.[0]?.packings;
  if (!packings || packings.length === 0) return [];
  return packings.map((p) => ({
    rowType: 'packing' as const,
    semiFinishedGoodId: p.semiFinishedGoodId ?? '',
    productDescription: p.description ?? '',
    UOMId: p.unitOfMeasureId ?? '',
    tagNo: p.tagNo ?? '',
    dimensionL: p.dimensionL?.toString() ?? '',
    dimensionW: p.dimensionW?.toString() ?? '',
    dimensionH: p.dimensionH?.toString() ?? '',
    quantity: p.quantity?.toString() ?? '',
    designWeight: p.designWeight?.toString() ?? '',
    remark: p.remarks ?? '',
    insulationFactoryWeight: p.insulationWeight?.toString() ?? '',
    insulationMasonryWeight: p.concreteWeight?.toString() ?? '',
    loosePartsFactoryWeight: p.otherComponentWeight?.toString() ?? '',
  }));
}, [designProfileByIdQuery.data]);

// Helper kiểm tra type linh kiện (hỗ trợ cả enum số, string số, hoặc string tên)
const isSbomComponent = (type: unknown): boolean => {
  if (type === undefined || type === null) return false;
  if (type === ERawMatPmrDetailType.SbomComponent || type === 2 || type === '2') return true;
  if (typeof type === 'string' && type.toLowerCase() === 'sbomcomponent') return true;
  return Number(type) === 2;
};

// Dựng các dòng linh kiện từ BOM của Hồ sơ thiết kế (DesignProfile.rawMatBoms.details với Type là SbomComponent)
const designProfileRawMatComponentRows = useMemo<ReadonlyPackingDetailRow[]>(() => {
  const details = (designProfileByIdQuery.data?.data?.details as any[]) ?? [];
  const allRawMatBomDetails = details.flatMap((d: any) => {
    const boms = d.rawMatBoms ?? (d.rawMatBom ? [d.rawMatBom] : []);
    return boms.flatMap((b: any) => b.details ?? []);
  });

  if (allRawMatBomDetails.length === 0) return [];

  return allRawMatBomDetails
    .filter((r: any) => isSbomComponent(r.type))
    .map((r: any) => {
      const matName = r.materialNameSnapshot || r.material?.name || '';
      const matCode = r.materialCodeSnapshot || r.material?.code || '';
      const modelName =
        r.materialModelNameSnapshot || r.model?.name || (r as any).materialModel?.name || '';
      const modelCode =
        r.materialModelCodeSnapshot || r.model?.code || (r as any).materialModel?.code || '';
      const modelSuffix =
        modelCode && modelName
          ? ` (${modelCode} - ${modelName})`
          : modelName || modelCode
            ? ` (${modelName || modelCode})`
            : '';
      const desc =
        matCode && matName
          ? `${matCode} - ${matName}${modelSuffix}`
          : matName || matCode || r.description || '';

      return {
        rowType: 'material' as const,
        materialCode: matCode,
        materialName: matName,
        modelCode: modelCode,
        modelName: modelName,
        semiFinishedGoodId: r.semiFinishedGoodId ?? '',
        productDescription: desc,
        UOMId: r.unitOfMeasureId ?? r.unitOfMeasure?.id ?? '',
        tagNo: r.tagNo ?? '',
        dimensionL: r.dimensionL?.toString() ?? '',
        dimensionW: r.dimensionW?.toString() ?? '',
        dimensionH: r.dimensionH?.toString() ?? '',
        quantity: r.quantity?.toString() ?? '',
        designWeight: r.designWeight?.toString() ?? '',
        remark: r.remark ?? r.remarks ?? '',
        insulationFactoryWeight: '',
        insulationMasonryWeight: '',
        loosePartsFactoryWeight:
          r.loosePartsFactoryWeight?.toString() ?? r.designWeight?.toString() ?? '',
      };
    });
}, [designProfileByIdQuery.data]);

// Dựng các dòng chi tiết từ Packings của Lệnh sản xuất (ProductionOrderPacking)
const poPackingsDetailRows = useMemo<ReadonlyPackingDetailRow[]>(() => {
  const packings = productionOrderByIdQuery.data?.data?.packings;
  if (!packings || packings.length === 0) return [];
  return packings.map((p) => ({
    rowType: 'packing' as const,
    semiFinishedGoodId: p.semiFinishedGoodId ?? '',
    productDescription: p.description ?? '',
    UOMId: p.unitOfMeasureId ?? '',
    tagNo: p.tagNo ?? '',
    dimensionL: p.dimensionL?.toString() ?? '',
    dimensionW: p.dimensionW?.toString() ?? '',
    dimensionH: p.dimensionH?.toString() ?? '',
    quantity: p.quantity?.toString() ?? '',
    designWeight: p.designWeight?.toString() ?? '',
    remark: p.remarks ?? '',
    insulationFactoryWeight: p.insulationWeight?.toString() ?? '',
    insulationMasonryWeight: p.concreteWeight?.toString() ?? '',
    loosePartsFactoryWeight: p.otherComponentWeight?.toString() ?? '',
  }));
}, [productionOrderByIdQuery.data]);

// Dựng các dòng linh kiện từ RawMats của Lệnh sản xuất (ProductionOrderRawMat với Type là SbomComponent)
const poRawMatComponentRows = useMemo<ReadonlyPackingDetailRow[]>(() => {
  const rawMats = productionOrderByIdQuery.data?.data?.rawMats;
  if (!rawMats || rawMats.length === 0) return [];

  return rawMats
    .filter((r) => isSbomComponent(r.type))
    .map((r) => {
      const matName = (r as any).materialNameSnapshot || (r as any).material?.name || '';
      const matCode = (r as any).materialCodeSnapshot || (r as any).material?.code || '';
      const modelName =
        (r as any).materialModelNameSnapshot ||
        (r as any).materialModel?.name ||
        (r as any).model?.name ||
        '';
      const modelCode =
        (r as any).materialModelCodeSnapshot ||
        (r as any).materialModel?.code ||
        (r as any).model?.code ||
        '';
      const modelSuffix =
        modelCode && modelName
          ? ` (${modelCode} - ${modelName})`
          : modelName || modelCode
            ? ` (${modelName || modelCode})`
            : '';
      const desc =
        matCode && matName
          ? `${matCode} - ${matName}${modelSuffix}`
          : matName || matCode || (r as any).description || '';

      return {
        rowType: 'material' as const,
        materialCode: matCode,
        materialName: matName,
        modelCode: modelCode,
        modelName: modelName,
        semiFinishedGoodId: r.semiFinishedGoodId ?? '',
        productDescription: desc,
        UOMId: r.unitOfMeasureId ?? (r as any).unitOfMeasure?.id ?? '',
        tagNo: (r as any).tagNo ?? '',
        dimensionL: (r as any).dimensionL?.toString() ?? '',
        dimensionW: (r as any).dimensionW?.toString() ?? '',
        dimensionH: (r as any).dimensionH?.toString() ?? '',
        quantity: r.quantity?.toString() ?? '',
        designWeight: (r as any).designWeight?.toString() ?? '',
        remark: (r as any).remark ?? (r as any).remarks ?? '',
        insulationFactoryWeight: '',
        insulationMasonryWeight: '',
        loosePartsFactoryWeight:
          (r as any).loosePartsFactoryWeight?.toString() ??
          (r as any).designWeight?.toString() ??
          '',
      };
    });
}, [productionOrderByIdQuery.data]);

// Dòng Cụm đóng kiện:
// - Chế độ sửa: lọc các dòng có semiFinishedGoodId hoặc kích thước L/W/H hoặc bảo ôn
// - Chế độ tạo: ưu tiên PO.packings, fallback DesignProfile.packings
const effectivePackingRows = useMemo<ReadonlyPackingDetailRow[]>(() => {
  if (isEditMode && fullItem?.details?.length) {
    return fullItem.details
      .filter(
        (d) =>
          !!d.semiFinishedGoodId ||
          !!d.dimensionL ||
          !!d.dimensionW ||
          !!d.dimensionH ||
          !!d.insulationFactoryWeight ||
          !!d.insulationMasonryWeight,
      )
      .map((d) => ({
        rowType: 'packing' as const,
        semiFinishedGoodId: d.semiFinishedGoodId ?? '',
        productDescription: d.productDescription ?? '',
        UOMId: d.uomId ?? '',
        tagNo: d.tagNo ?? '',
        dimensionL: d.dimensionL?.toString() ?? '',
        dimensionW: d.dimensionW?.toString() ?? '',
        dimensionH: d.dimensionH?.toString() ?? '',
        quantity: d.quantity?.toString() ?? '',
        designWeight: d.designWeight?.toString() ?? '',
        remark: d.remark ?? '',
        insulationFactoryWeight: d.insulationFactoryWeight?.toString() ?? '',
        insulationMasonryWeight: d.insulationMasonryWeight?.toString() ?? '',
        loosePartsFactoryWeight: d.loosePartsFactoryWeight?.toString() ?? '',
      }));
  }

  return poPackingsDetailRows.length > 0
    ? poPackingsDetailRows
    : designProfilePackagingsDetailRows;
}, [
  isEditMode,
  fullItem,
  poPackingsDetailRows,
  designProfilePackagingsDetailRows,
]);

// Dòng Linh kiện / Nguyên vật liệu phụ:
// - Chế độ sửa: lọc các dòng không có semiFinishedGoodId và không có kích thước
// - Chế độ tạo: ưu tiên PO.rawMats[SbomComponent], fallback DesignProfile.rawMatBom.details[SbomComponent]
const effectiveComponentRows = useMemo<ReadonlyPackingDetailRow[]>(() => {
  if (isEditMode && fullItem?.details?.length) {
    return fullItem.details
      .filter(
        (d) =>
          !d.semiFinishedGoodId &&
          !d.dimensionL &&
          !d.dimensionW &&
          !d.dimensionH &&
          !d.insulationFactoryWeight &&
          !d.insulationMasonryWeight,
      )
      .map((d) => ({
        rowType: 'material' as const,
        semiFinishedGoodId: d.semiFinishedGoodId ?? '',
        productDescription: d.productDescription ?? '',
        UOMId: d.uomId ?? '',
        tagNo: d.tagNo ?? '',
        dimensionL: d.dimensionL?.toString() ?? '',
        dimensionW: d.dimensionW?.toString() ?? '',
        dimensionH: d.dimensionH?.toString() ?? '',
        quantity: d.quantity?.toString() ?? '',
        designWeight: d.designWeight?.toString() ?? '',
        remark: d.remark ?? '',
        insulationFactoryWeight: d.insulationFactoryWeight?.toString() ?? '',
        insulationMasonryWeight: d.insulationMasonryWeight?.toString() ?? '',
        loosePartsFactoryWeight: d.loosePartsFactoryWeight?.toString() ?? '',
      }));
  }

  return poRawMatComponentRows.length > 0
    ? poRawMatComponentRows
    : designProfileRawMatComponentRows;
}, [
  isEditMode,
  fullItem,
  poRawMatComponentRows,
  designProfileRawMatComponentRows,
]);

// Detail hiển thị và submit: kết hợp cả cụm đóng kiện và linh kiện
const detailRows = useMemo<ReadonlyPackingDetailRow[]>(
  () => [...effectivePackingRows, ...effectiveComponentRows],
  [effectivePackingRows, effectiveComponentRows],
);

