const [createdId, setCreatedId] = useState<string | null>(null);
const [activeDetailTab, setActiveDetailTab] = useState<'packings' | 'materials'>('packings');

const formSchema = useMemo(() => createFormSchema(t), [t]);
const form = useForm<FormValues>({
  resolver: zodResolver(formSchema),
  defaultValues: {
    productionOrderId: '',
    finishedGoodsCode: '',
    finishedGoodsName: '',
    finishedGoodId: null,
    modelId: null,
    designModelId: null,
    createdById: '',
    createdOrganizationId: '',
  },
});

const watchedProductionOrderId = form.watch('productionOrderId');
const watchedFinishedGoodId = form.watch('finishedGoodId');
const watchedModelId = form.watch('modelId');
const watchedDesignModelId = form.watch('designModelId');

// Self-fetch ref-doc selector: refType từ cấu hình danh mục, refDoc = work item của refType đó.
const { selectorProps, setSelectedRefDocument, selectedCatRef } = useRefDocSelector({
  form,
  mode: isEditMode ? 'edit' : 'create',
  workItemCategoryCode: WorkItemCategoryCode.MechanicalPackingList,
  refDocFieldName: 'productionOrderId',
  refTypeFieldName: null,
  detailsFieldName: null,
  autoApplyMappedData: false,
  onRefDocIdChange: () => {
    form.setValue('finishedGoodId', null);
    form.setValue('finishedGoodsCode', '');
    form.setValue('finishedGoodsName', '');
    form.setValue('modelId', null);
    form.setValue('designModelId', null);
  },
});

const refTypeId = selectedCatRef?.refWorkItemCategoryId;

const poDropdownQuery = useQuery({
  queryKey: ['po-dropdown-for-packing-list', refTypeId],
  queryFn: async () => {
    if (!refTypeId) return [];
    const res = await sharedWorkItemService.getDropdown({
      filters: `workItemCategoryId==${refTypeId}&&refDocId!=null`,
      ignoreStatusFilter: true,
    });
    return res.data ?? [];
  },
  enabled: open && !!refTypeId,
});

const poOptions = useMemo(() => {
  return (poDropdownQuery.data ?? []).map((d) => ({
    label: d.name || d.code || '',
    value: String(d.id),
    code: d.code || '',
  }));
}, [poDropdownQuery.data]);

// Lệnh sản xuất đã chọn → dẫn xuất Thành phẩm/Model + Project + Packings + RawMats cho payload
const { getByIdQuery: productionOrderByIdQuery } = useProductionOrder({
