const inlinePackingItems = useMemo(() => {
  const packingsOnly = inlineDetailItems.filter(
    (d) =>
      !!d.semiFinishedGoodId ||
      !!d.dimensionL ||
      !!d.dimensionW ||
      !!d.dimensionH ||
      !!d.insulationFactoryWeight ||
      !!d.insulationMasonryWeight,
  );
  return packingsOnly.length > 0 ? packingsOnly : inlineDetailItems;
}, [inlineDetailItems]);

const savedComponentRows = useMemo<ReadonlyPackingDetailRow[]>(() => {
  return inlineDetailItems
    .filter(
      (d) =>
        !d.semiFinishedGoodId &&
        !d.dimensionL &&
        !d.dimensionW &&
        !d.dimensionH &&
        !d.insulationFactoryWeight &&
        !d.insulationMasonryWeight,
    )
    .map((d) => ({
      id: d.id,
      rowType: 'material' as const,
      semiFinishedGoodId: d.semiFinishedGoodId ?? '',
      productDescription: d.productDescription ?? '',
      UOMId: d.uomId ?? '',
      tagNo: d.tagNo ?? '',
      dimensionL: d.dimensionL?.toString() ?? '',
      dimensionW: d.dimensionW?.toString() ?? '',
      dimensionH: d.dimensionH?.toString() ?? '',
      quantity: d.quantity?.toString() ?? '',
      designWeight: d.designWeight?.toString() ?? '',
      remark: d.remark ?? '',
      insulationFactoryWeight: d.insulationFactoryWeight?.toString() ?? '',
      insulationMasonryWeight: d.insulationMasonryWeight?.toString() ?? '',
      loosePartsFactoryWeight: d.loosePartsFactoryWeight?.toString() ?? '',
    }));
}, [inlineDetailItems]);

const poRawMatComponentRows = useMemo<ReadonlyPackingDetailRow[]>(() => {
  const rawMats = (selectedProductionOrderQuery.data?.data?.rawMats as
    | MaterialSourceItem[]
    | undefined) ?? [];
  if (!rawMats.length) return [];
  return rawMats
    .filter((r) => isSbomComponent(r.type))
    .map(mapMaterialSourceToRow);
}, [selectedProductionOrderQuery.data]);

const designProfileRawMatComponentRows = useMemo<ReadonlyPackingDetailRow[]>(() => {
  const details = selectedDesignProfileQuery.data?.data?.details;
  if (!details || details.length === 0) return [];
  const allRawMatBomDetails: MaterialSourceItem[] = [];
  details.forEach((d) => {
    const boms = d.rawMatBoms as
      | Array<{ details?: MaterialSourceItem[] }>
      | undefined;
    if (Array.isArray(boms)) {
      boms.forEach((bom) => {
        if (Array.isArray(bom.details)) {
          allRawMatBomDetails.push(...bom.details);
        }
      });
    }
  });
  if (allRawMatBomDetails.length === 0) return [];
  return allRawMatBomDetails
    .filter((r) => isSbomComponent(r.type))
    .map(mapMaterialSourceToRow);
}, [selectedDesignProfileQuery.data]);

const effectiveComponentRows = useMemo<ReadonlyPackingDetailRow[]>(() => {
  if (savedComponentRows.length > 0) return savedComponentRows;
  return poRawMatComponentRows.length > 0
    ? poRawMatComponentRows
    : designProfileRawMatComponentRows;
}, [savedComponentRows, poRawMatComponentRows, designProfileRawMatComponentRows]);

const uomOptions = useMemo(
  () => uoms.map((u) => ({ label: u.name, value: u.id })),
  [uoms],
);

const renderDetailTabContent = () => {
  if (!selectedIdForDetail) {
    return (
      <div className="flex h-full items-center justify-center p-8 bg-card border">
        <p className="text-muted-foreground text-sm">
          {t('mechanicalPackingList:detail.placeholder', {
            defaultValue: 'Chọn một dòng ở bảng trên để xem chi tiết.',
          })}
        </p>
      </div>
    );
  }
  if (inlineDetailQuery.isLoading) {
    return (
      <div className="flex h-full items-center justify-center p-8 bg-card border">
        <p className="text-muted-foreground text-sm">
          {t('mechanicalPackingList:detail.loading', { defaultValue: 'Đang tải...' })}
        </p>
      </div>
    );
  }
  if (inlinePackingItems.length === 0 && effectiveComponentRows.length === 0) {
    return (
      <div className="flex h-full items-center justify-center p-8 bg-card border">
        <p className="text-muted-foreground text-sm">
          {t('mechanicalPackingList:detail.noData', { defaultValue: 'Không có chi tiết.' })}
        </p>
      </div>
    );
  }

  return (
    <Tabs
      value={activeDetailTab}
      onValueChange={(val) => setActiveDetailTab(val as 'packings' | 'materials')}
      className="h-full flex flex-col min-w-0 gap-0 border bg-card"
    >
      <div className="flex min-w-0 items-end justify-between gap-2 border-b bg-muted/20 px-2">
        <div className="min-w-0 flex-1 overflow-x-auto pt-1.5 pb-0.5 [&::-webkit-scrollbar]:hidden">
          <TabsList className="inline-flex h-auto min-w-max flex-nowrap gap-1 border-b-0 bg-transparent py-0">
            <TabsTrigger value="packings" className={TAB_TRIGGER_CLASS_NAME}>
              <Boxes className="h-3.5 w-3.5" />
              <span>
                {t('mechanicalPackingList:tab.packings', {
                  defaultValue: 'Cụm chi tiết đóng kiện',
                })}
              </span>
              <span className={TAB_BADGE_CLASS_NAME}>{inlinePackingItems.length}</span>
            </TabsTrigger>

            <TabsTrigger value="materials" className={TAB_TRIGGER_CLASS_NAME}>
              <Layers className="h-3.5 w-3.5" />
              <span>
                {t('mechanicalPackingList:tab.materials', {
                  defaultValue: 'BOM Linh kiện/INVL phụ',
                })}
              </span>
              <span className={TAB_BADGE_CLASS_NAME}>{effectiveComponentRows.length}</span>
            </TabsTrigger>
          </TabsList>
        </div>
      </div>

      {activeDetailTab === 'packings' && (
        <TabsContent
          value="packings"
          className="mt-0! flex-1 min-h-0 overflow-auto bg-card outline-none"
        >
          <PackingListDetailTable
            details={inlinePackingItems}
            uoms={uoms}
            headerTone="primary"
            className="rounded-tl-none border-0 [&_thead_th:first-child]:!rounded-tl-none"
          />
        </TabsContent>
      )}

      {activeDetailTab === 'materials' && (
        <TabsContent
          value="materials"
          className="mt-0! flex-1 min-h-0 overflow-auto bg-card outline-none"
        >
          <PackingListMaterialTable
            rows={effectiveComponentRows}
            uomOptions={uomOptions}
            className="rounded-tl-none border-0 [&_thead_th:first-child]:!rounded-tl-none"
          />
        </TabsContent>
      )}
    </Tabs>
  );
};

