  return packingsOnly.length > 0 ? packingsOnly : details;
}, [details]);

const materialRows = useMemo<ReadonlyPackingDetailRow[]>(() => {
  return details
    .filter(
      (d) =>
        !d.semiFinishedGoodId &&
        !d.dimensionL &&
        !d.dimensionW &&
        !d.dimensionH &&
        !d.insulationFactoryWeight &&
        !d.insulationMasonryWeight,
    )
    .map((r) => {
      const matName = r.materialNameSnapshot || r.material?.name || '';
