        r.materialModel?.name ||
        r.model?.name ||
        '';
      const modelCode =
        r.materialModelCodeSnapshot ||
        r.materialModel?.code ||
        r.model?.code ||
        '';
      const modelSuffix =
        modelCode && modelName
          ? ` (${modelCode} - ${modelName})`
          : modelName || modelCode
            ? ` (${modelName || modelCode})`
            : '';
      const desc =
        matCode && matName
          ? `${matCode} - ${matName}${modelSuffix}`
          : matName || matCode || r.productDescription || '';

      return {
        id: r.id,
        rowType: 'material' as const,
        materialCode: matCode,
        materialName: matName,
        modelCode: modelCode,
        modelName: modelName,
        productDescription: desc,
