const selectedPoId = data?.productionOrderId;
const { getByIdQuery: selectedProductionOrderQuery } = useProductionOrder({
  id: selectedPoId ?? undefined,
  queryParam: {
    getById: {
      isEnable: !!selectedPoId,
      includes: ['Packings', 'RawMats'],
    },
  },
});

const selectedDesignProfileId = selectedProductionOrderQuery.data?.data?.designProfileId;
const { getByIdQuery: selectedDesignProfileQuery } = useDesignProfile({
  id: selectedDesignProfileId ?? undefined,
  queryParam: {
    getById: {
      isEnable: !!selectedDesignProfileId,
      includes: [
        'Details.Packings',
        'Details.RawMatBoms.Details.Material',
        'Details.RawMatBoms.Details.UnitOfMeasure',
        'Details.RawMatBoms.Details.Model',
      ],
    },
  },
});

const [activeDetailTab, setActiveDetailTab] = useState<'packings' | 'materials'>('packings');

const inlinePackingItems = useMemo(() => {
  const packingsOnly = details.filter(
    (d) =>
      !!d.semiFinishedGoodId ||
      !!d.dimensionL ||
      !!d.dimensionW ||
      !!d.dimensionH ||
      !!d.insulationFactoryWeight ||
      !!d.insulationMasonryWeight,
  );
  return packingsOnly.length > 0 ? packingsOnly : details;
}, [details]);

const savedComponentRows = useMemo<ReadonlyPackingDetailRow[]>(() => {
  return details
    .filter(
      (d) =>
        !d.semiFinishedGoodId &&
        !d.dimensionL &&
        !d.dimensionW &&
        !d.dimensionH &&
        !d.insulationFactoryWeight &&
        !d.insulationMasonryWeight,
    )
    .map((d) => ({
      id: d.id,
      rowType: 'material' as const,
      semiFinishedGoodId: d.semiFinishedGoodId ?? '',
      productDescription: d.productDescription ?? '',
      UOMId: d.uomId ?? '',
      tagNo: d.tagNo ?? '',
      dimensionL: d.dimensionL?.toString() ?? '',
      dimensionW: d.dimensionW?.toString() ?? '',
      dimensionH: d.dimensionH?.toString() ?? '',
      quantity: d.quantity?.toString() ?? '',
      designWeight: d.designWeight?.toString() ?? '',
      remark: d.remark ?? '',
      insulationFactoryWeight: d.insulationFactoryWeight?.toString() ?? '',
      insulationMasonryWeight: d.insulationMasonryWeight?.toString() ?? '',
      loosePartsFactoryWeight: d.loosePartsFactoryWeight?.toString() ?? '',
    }));
}, [details]);

const poRawMatComponentRows = useMemo<ReadonlyPackingDetailRow[]>(() => {
  const rawMats = (selectedProductionOrderQuery.data?.data?.rawMats as
    | MaterialSourceItem[]
    | undefined) ?? [];
  if (!rawMats.length) return [];
  return rawMats
    .filter((r) => isSbomComponent(r.type))
    .map(mapMaterialSourceToRow);
}, [selectedProductionOrderQuery.data]);

const designProfileRawMatComponentRows = useMemo<ReadonlyPackingDetailRow[]>(() => {
  const profileDetails = selectedDesignProfileQuery.data?.data?.details;
  if (!profileDetails || profileDetails.length === 0) return [];
  const allRawMatBomDetails: MaterialSourceItem[] = [];
  profileDetails.forEach((d) => {
    const boms = d.rawMatBoms as
      | Array<{ details?: MaterialSourceItem[] }>
      | undefined;
    if (Array.isArray(boms)) {
      boms.forEach((bom) => {
        if (Array.isArray(bom.details)) {
          allRawMatBomDetails.push(...bom.details);
        }
      });
    }
  });
  if (allRawMatBomDetails.length === 0) return [];
  return allRawMatBomDetails
    .filter((r) => isSbomComponent(r.type))
    .map(mapMaterialSourceToRow);
}, [selectedDesignProfileQuery.data]);

const effectiveComponentRows = useMemo<ReadonlyPackingDetailRow[]>(() => {
  if (savedComponentRows.length > 0) return savedComponentRows;
  return poRawMatComponentRows.length > 0
    ? poRawMatComponentRows
    : designProfileRawMatComponentRows;
}, [savedComponentRows, poRawMatComponentRows, designProfileRawMatComponentRows]);

const uomOptions = useMemo(
  () => uoms.map((u) => ({ label: u.name, value: u.id })),
  [uoms],
);

