// Lọc theo DesignModelId (tra cứu Guid, KHÔNG gán cứng chuỗi)
if (filter.DesignModelId.HasValue && filter.DesignModelId.Value != Guid.Empty)
{
    var targetDmId = filter.DesignModelId.Value;
    filteredRows = filteredRows
        .Where(r => r.Items.Any(i => i.DesignModelId == targetDmId))
        .ToList();

    foreach (var r in filteredRows)
    {
        r.Items = r.Items.Where(i => i.DesignModelId == targetDmId).ToList();
        r.ItemCount = r.Items.Count;
        r.TotalQuantity = r.Items.Sum(i => i.Quantity);
    }
}

